--
-- TOC entry 6932 (class 1255 OID 977112)
-- Name: credit_soc_type_get_parties(text, text); Type: FUNCTION; Schema: public; Owner: itstaff
--

CREATE FUNCTION public.credit_soc_type_get_parties(mode text, partycdin text) RETURNS TABLE(party_description text, party_code character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF mode = 'ADD' THEN
        RETURN QUERY
        SELECT 
            fp.party_code || ' - ' || fp.party_name AS party_description,
            fp.party_code
        FROM 
            fam.famc_party fp
        WHERE 
            fp.status = 'A'
            AND fp.party_type IN ('B', 'K', 'U')
            AND fp.party_code NOT IN (
                SELECT ps.party_cd FROM pmm_society ps
            )
        order by fp.party_code;
    ELSIF mode = 'MODIFY' THEN
        RETURN QUERY
        SELECT 
            fp.party_code || ' - ' || fp.party_name AS party_description,
            fp.party_code
        FROM 
            fam.famc_party fp
        WHERE 
            fp.party_type IN ('B', 'K', 'U')
            AND (fp.party_code NOT IN (
                SELECT ps.party_cd FROM pmm_society ps
            )) or (fp.party_code = partyCdIn) 
        order by fp.party_code;
    ELSE
        RAISE EXCEPTION 'Invalid mode: %', mode;
    END IF;
END;
$$;


ALTER FUNCTION public.credit_soc_type_get_parties(mode text, partycdin text) OWNER TO itstaff;

