--
-- TOC entry 6883 (class 1255 OID 23834)
-- Name: fa_sp_alloc(character, integer, integer, character, numeric, date, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_alloc(p_led_cd character, p_txn_no integer, p_cc_cd integer, p_acct_head character, p_alloc_amt numeric, p_alloc_dt date, p_dr_cr_flag character) RETURNS integer
    LANGUAGE plpgsql
    AS $$


-----------------------------------------------------------------
-- This procedure enters at each call one row into the
-- allocation table.
-- Thus the calling program will have to call the SP at
-- least twice , once for debit and then for credit.
-- The responsibility of seeing that the debits match the
-- credits and this amount is equal to tha amount involved
-- in the transaction lies with the calling program.
-- FA cannot be responsible for any error done in calling
-- the procedure.
-----------------------------------------------------------------

declare  p_sr_no          fat_alloc.sr_no%type ;
  p_stat          int ;
  p_no_of_rows    int ;
  v_rowcount int ;
BEGIN

-- check if the transaction number is 0.
-- All other validations would be anyway caught at the
-- time of insert.

/*
set debug file to "/tmp/fa_sp.db";
trace on ;
*/
if p_txn_no = 0 then
        p_stat := 100;
        return p_stat ;
end if;

p_stat := 0 ;
p_no_of_rows := 0 ;



        select  max(sr_no)
        into    p_sr_no
        from    fat_alloc
        where   fat_alloc.led_cd = p_led_cd
        and     fat_alloc.txn_no = p_txn_no ;

        if (p_sr_no is null) then
                p_sr_no := 0 ;
        end if;

        p_sr_no := p_sr_no + 1 ;

               insert into fat_alloc
                (led_cd ,       txn_no ,
                cc_cd ,         acct_head ,
                alloc_amt ,     alloc_dt        ,
                dr_cr_flag,     sr_no           )
        values
                (p_led_cd,      p_txn_no,
                p_cc_cd,        p_acct_head ,
                p_alloc_amt,    p_alloc_dt      ,
                p_dr_cr_flag,   p_sr_no )
        ;

       ---  p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
        Get diagnostics v_rowcount = row_count;
        p_no_of_rows := v_rowcount ;

        if (p_stat = 0 ) and (p_no_of_rows = 0) then
                p_stat := 100 ;
        end if;

        return p_stat ;



END ;
$$;


ALTER FUNCTION public.fa_sp_alloc(p_led_cd character, p_txn_no integer, p_cc_cd integer, p_acct_head character, p_alloc_amt numeric, p_alloc_dt date, p_dr_cr_flag character) OWNER TO postgres;

--
-- TOC entry 6886 (class 1255 OID 23835)
-- Name: fa_sp_alloc002(character, integer, integer, character, character, numeric, date, character, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_alloc002(p_led_cd character, p_txn_no integer, p_cc_cd integer, p_dr_acct_head character, p_cr_acct_head character, p_alloc_amt numeric, p_alloc_dt date, p_mod_cd character, p_au6_no integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

-----------------------------------------------------------------
-- This procedure enters at each call one row into the
-- allocation table.
-- The A/c Heads should be entered properly.
-----------------------------------------------------------------

DECLARE p_sr_no		integer ;
DECLARE p_stat		integer ;
DECLARE p_no_of_rows	integer ;
DECLARE p_no_of_rows_cr	integer ;


BEGIN

-- check if the transaction number is 0.
-- All other validations would be anyway caught at the 
-- time of insert.

--set debug file to "/tmp/fa_sp_alloc002.dbg";
--trace on;

IF p_txn_no = 0 THEN

        p_stat := 100;

	return p_stat ;
END IF ;

p_stat := 0 ;
p_no_of_rows := 0 ;

BEGIN 
	
	select	max(sr_no)
	into	p_sr_no
	from	faa_alloc
	where	faa_alloc.led_cd = p_led_cd
	and	faa_alloc.txn_no = p_txn_no ;

	IF (p_sr_no is null) THEN
		p_sr_no := 0 ;
	END IF ;

p_sr_no := 0 ;
	p_sr_no := p_sr_no + 1 ;

	INSERT INTO faa_alloc
	(txn_no, sr_no, txn_dt, au6_no, alloc_dt, alloc_amt, dr_cr_flag,
	 acct_head, cc_cd, mod_cd, led_cd)
	VALUES
	(p_txn_no, p_sr_no, p_alloc_dt, p_au6_no, p_alloc_dt, p_alloc_amt,
 	 'D', p_dr_acct_head, p_cc_cd, p_mod_cd, p_led_cd);

-- For succ. INSERT, p_no_of_rows contains rowid of last insert.

	--IF (p_stat = 0 ) AND (p_no_of_rows <= 0) THEN
	
--	IF (p_stat = 0 )  THEN

--		p_stat := 100 ;

--		return p_stat;
--	ELSE
--		p_stat := 0;

--	END IF;

--# Add Debit Amount to Online balance

	UPDATE 	fam_acct_onbal
	SET 	online_bal = online_bal + 
		p_alloc_amt
	WHERE 	led_cd = p_led_cd AND
	      	acct_head = p_dr_acct_head;
			
	select count(*) into p_no_of_rows
	from fam_acct_onbal 
	where led_cd = p_led_cd AND
	      	acct_head = p_dr_acct_head;
			
	

--	p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;

IF p_no_of_rows <= 0 THEN
		 
		INSERT INTO fam_acct_onbal
		(led_cd,acct_head,online_bal)
		values(p_led_cd,p_dr_acct_head,
		p_alloc_amt);
	END IF;

-- For Credit

	p_sr_no := p_sr_no + 1 ;

	 
	INSERT INTO faa_alloc
	(txn_no, sr_no, txn_dt, au6_no, alloc_dt, alloc_amt, dr_cr_flag,
	 acct_head, cc_cd, mod_cd, led_cd)
	VALUES
	(p_txn_no, p_sr_no, p_alloc_dt, p_au6_no, p_alloc_dt, p_alloc_amt,
 	'C', p_cr_acct_head, p_cc_cd, p_mod_cd, p_led_cd);

	--p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;

	--IF (p_stat = 0 ) AND (p_no_of_rows <= 0) THEN
--	IF (p_stat = 0 )  THEN
--		p_stat := 100 ;
--		RETURN p_stat;
--	ELSE
--		p_stat := 0;
--	END IF;

--# Subtract Credit Amount from Online balance
	
	UPDATE 	fam_acct_onbal
	SET 	online_bal = online_bal - 
		p_alloc_amt
	WHERE 	led_cd = p_led_cd AND
	      	acct_head = p_cr_acct_head;
--	p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;

	select count(*) into p_no_of_rows_cr
	from fam_acct_onbal 
	where led_cd = p_led_cd AND
	      	acct_head = p_cr_acct_head;
			
	IF p_no_of_rows_cr <= 0 THEN

		p_alloc_amt := -1 * p_alloc_amt ;

		INSERT INTO fam_acct_onbal
		(led_cd,acct_head,online_bal)
		VALUES(p_led_cd,p_cr_acct_head,
		p_alloc_amt);
		
	END IF;

	RETURN p_stat;
end;

--exception
-- when others then
--    set p_stat
--	 raise exception p_stat;
--    return p_stat;
 
END;
$$;


ALTER FUNCTION public.fa_sp_alloc002(p_led_cd character, p_txn_no integer, p_cc_cd integer, p_dr_acct_head character, p_cr_acct_head character, p_alloc_amt numeric, p_alloc_dt date, p_mod_cd character, p_au6_no integer) OWNER TO postgres;

--
-- TOC entry 6887 (class 1255 OID 23836)
-- Name: fa_sp_alloc102(character, integer, integer, character, character, numeric, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_alloc102(p_led_cd character, p_txn_no integer, p_cc_cd integer, p_dr_acct_head character, p_cr_acct_head character, p_alloc_amt numeric, p_alloc_dt date) RETURNS integer
    LANGUAGE plpgsql
    AS $$

-----------------------------------------------------------------
-- This procedure enters at each call one row into the
-- allocation table.
-- The A/c Heads should be entered properly.
-----------------------------------------------------------------
declare  p_sr_no          fat_alloc.sr_no%type ;
  p_stat          int ;
  p_no_of_rows    int ;
  v_rowcount int ;
BEGIN

-- check if the transaction number is 0.
-- All other validations would be anyway caught at the
-- time of insert.

-- with resume ;

if p_txn_no = 0 then
        p_stat := 100;
        return p_stat ;
end if;

p_stat := 0 ;
p_no_of_rows := 0 ;

        select  max(sr_no)
        into    p_sr_no
        from    fat_alloc
        where   fat_alloc.led_cd = p_led_cd
        and     fat_alloc.txn_no = p_txn_no ;

        if (p_sr_no is null) then
                p_sr_no := 0 ;
        end if;

        p_sr_no := p_sr_no + 1 ;

raise notice 'acct_head %', p_dr_acct_head;
        insert into fat_alloc
        (txn_no, sr_no, alloc_dt, alloc_amt, dr_cr_flag,
         acct_head, cc_cd, led_cd)
        values
        (p_txn_no, p_sr_no, p_alloc_dt, p_alloc_amt,
         'D', p_dr_acct_head, p_cc_cd, p_led_cd)
        ;

-- For succ. INSERT, p_no_of_rows contains rowid of last insert.
        --- p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
        Get diagnostics v_rowcount = row_count;
        p_no_of_rows := v_rowcount ;

raise notice 'p_no_of_rows %', p_no_of_rows;

        if (p_stat = 0 ) and (p_no_of_rows <= 0) then
                p_stat := 100 ;
                return p_stat;
        else
                p_stat := 0;
        end if;

        --# Add Debit Amount to Online balance
        UPDATE  fam_acct_onbal
        SET     online_bal = online_bal +
                p_alloc_amt
        WHERE   led_cd = p_led_cd AND
                acct_head = p_dr_acct_head;

        --p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
		Get diagnostics v_rowcount = row_count;
        p_no_of_rows := v_rowcount ;
raise notice 'p_no_of_rows 2 %', p_no_of_rows;

        IF p_no_of_rows <= 0 THEN

                insert into fam_acct_onbal
                (led_cd,acct_head,online_bal)
                values(p_led_cd,p_dr_acct_head,
                p_alloc_amt);
        END IF;

-- For Credit
        p_sr_no := p_sr_no + 1 ;
raise notice 'p_cr_acct_head %', p_cr_acct_head;
        insert into fat_alloc
        (txn_no, sr_no, alloc_dt, alloc_amt, dr_cr_flag,
         acct_head, cc_cd, led_cd)
        values
        (p_txn_no, p_sr_no, p_alloc_dt, p_alloc_amt,
         'C', p_cr_acct_head, p_cc_cd, p_led_cd)
        ;

  ---      p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;

        Get diagnostics v_rowcount = row_count;
        p_no_of_rows := v_rowcount ;
raise notice 'p_no_of_rows 3 %', p_no_of_rows;
        if (p_stat = 0 ) and (p_no_of_rows <= 0) then
                p_stat := 100 ;
                return p_stat;
        else
                p_stat := 0;
        end if;

          --# Subtract Credit Amount from Online balance
        UPDATE  fam_acct_onbal
        SET     online_bal = online_bal -
                p_alloc_amt
        WHERE   led_cd = p_led_cd AND
                acct_head = p_cr_acct_head;
---        p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
        Get diagnostics v_rowcount = row_count;
        p_no_of_rows := v_rowcount ;
raise notice 'p_no_of_rows 4 %', p_no_of_rows;
        IF p_no_of_rows <= 0 THEN
                p_alloc_amt := -1 * p_alloc_amt ;

                insert into fam_acct_onbal
                (led_cd,acct_head,online_bal)
                values(p_led_cd,p_cr_acct_head,
                p_alloc_amt);
        END IF;

        return p_stat ;

END ;
$$;


ALTER FUNCTION public.fa_sp_alloc102(p_led_cd character, p_txn_no integer, p_cc_cd integer, p_dr_acct_head character, p_cr_acct_head character, p_alloc_amt numeric, p_alloc_dt date) OWNER TO postgres;

--
-- TOC entry 6789 (class 1255 OID 23837)
-- Name: fa_sp_books_ext(integer, integer, date, integer, date, numeric, character, character, integer, character, character); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.fa_sp_books_ext(IN p_txn_no integer, IN p_sr_no integer, IN p_txn_dt date, IN p_au6_no integer, IN p_alloc_dt date, IN p_alloc_amt numeric, IN p_dr_cr_flag character, IN p_acct_head character, IN p_cc_cd integer, IN p_mod_cd character, IN p_led_cd character)
    LANGUAGE plpgsql
    AS $$			
		



-----------------------------------------------------------------
--- Changes done for mod code 'CP' for capturing contract no and po no
-- This procedure insert data of books of account data with party_cd
-- The information of contract number and purchase order number also
-- captured in fat_books_ext table in case of BPC and BPS bills respectively.
-----------------------------------------------------------------

declare	p_stat		int ;
	p_no_of_rows	int ;
	p_ast_typ char(5);
 p_string char(100);
 p_party_cd char(7);
 p_con_no int ;
 p_po_no char(14);
 p_imp_id char(10);
 p_emp_no int ;
 p_cp_au6_no int;
 p_cp_led_cd char(2);
 p_cp_mod_cd char(3);
 p_misc_mod_cd char(3);
 
BEGIN

-- check if the transaction number is 0.
-- All other validations would be anyway caught at the
-- time of insert.

--set debug file to "/tmp/fa_sp_books_ext.dbg";

--trace on ;


p_stat := 0 ;
p_no_of_rows := 0 ;

        select mod_cd into p_misc_mod_cd from fam_sysmod
        where main_mod_cd = 'MSB' and mod_cd = p_mod_cd ;

        IF p_misc_mod_cd is not null OR p_misc_mod_cd != '' THEN
           select party_emp_id into p_party_cd from fat_misbills
           where  au6_no = p_au6_no and led_cd = p_led_cd
           and  mod_cd = p_mod_cd ;

           --- -- p_stat := dbinfo("SQLCA.SQLERRD2");
            INSERT INTO fat_books_ext (txn_no,sr_no,txn_dt,au6_no,alloc_dt,
                                         alloc_amt,dr_cr_flag,acct_head,cc_cd,
                                         mod_cd,led_cd,party_cd,con_no,po_no,mod_stat)
                                         VALUES
                                        ( p_txn_no,p_sr_no,p_txn_dt,p_au6_no,p_alloc_dt,
                                          p_alloc_amt,p_dr_cr_flag,p_acct_head,p_cc_cd,
                                          p_mod_cd,p_led_cd,p_party_cd,null,null,null);

          ---  -- p_stat := dbinfo("SQLCA.SQLERRD2");
         
           ----  IF p_stat <= 0 THEN
          ----    ROLLBACK WORK ;
          ---  END IF

        END IF;


       IF p_mod_cd = 'BPC' THEN
             
              select party_cd,con_no into p_party_cd, p_con_no from fat_bpcon
              where au6_no = p_au6_no and led_cd = p_led_cd ;

             -- -- p_stat := dbinfo("SQLCA.SQLERRD2");
             
              INSERT INTO fat_books_ext (txn_no,sr_no,txn_dt,au6_no,alloc_dt,
                                         alloc_amt,dr_cr_flag,acct_head,cc_cd,
                                         mod_cd,led_cd,party_cd,con_no,po_no,mod_stat)
                                         VALUES
                                        ( p_txn_no,p_sr_no,p_txn_dt,p_au6_no,p_alloc_dt,
                                          p_alloc_amt,p_dr_cr_flag,p_acct_head,p_cc_cd,
                                          p_mod_cd,p_led_cd,p_party_cd,p_con_no,null,null);

        	   -- -- p_stat := dbinfo("SQLCA.SQLERRD2");
         

       END IF;

       IF p_mod_cd = 'BPS' THEN
             
              select party_cd,po_no into p_party_cd, p_po_no from fat_bpsup
              where au6_no = p_au6_no and led_cd = p_led_cd ;

              -- p_stat := dbinfo("SQLCA.SQLERRD2");
             
              INSERT INTO fat_books_ext (txn_no,sr_no,txn_dt,au6_no,alloc_dt,
                                         alloc_amt,dr_cr_flag,acct_head,cc_cd,
                                         mod_cd,led_cd,party_cd,con_no,po_no,mod_stat)
                                         VALUES
                                        ( p_txn_no,p_sr_no,p_txn_dt,p_au6_no,p_alloc_dt,
                                          p_alloc_amt,p_dr_cr_flag,p_acct_head,p_cc_cd,
                                          p_mod_cd,p_led_cd,p_party_cd,null,p_po_no,null);
            	-- p_stat := dbinfo("SQLCA.SQLERRD2");         
       END IF;

       IF p_mod_cd = 'CP' THEN
         
          select  party_cd into p_party_cd from fat_abstract
