          select  a.imp_id, b.emp_no  into p_imp_id, p_emp_no from fat_payord a, fam_imprest b
          where a.imp_id = b.imp_id and a.led_cd = b.led_cd
          and a.au6_no = p_au6_no
          and a.led_cd = p_led_cd;

          -- p_stat := dbinfo("SQLCA.SQLERRD2");
              
              INSERT INTO fat_books_imp (txn_no,sr_no,txn_dt,au6_no,alloc_dt,
                                         alloc_amt,dr_cr_flag,acct_head,cc_cd,
                                         mod_cd,led_cd,imp_id,emp_no)
                                         VALUES
                                        ( p_txn_no,p_sr_no,p_txn_dt,p_au6_no,p_alloc_dt,
                                          p_alloc_amt,p_dr_cr_flag,p_acct_head,p_cc_cd,
                                          p_mod_cd,p_led_cd,p_imp_id,p_emp_no);
            	-- p_stat := dbinfo("SQLCA.SQLERRD2");          
				
				
				

       END IF;

       IF p_mod_cd = 'IMS' THEN
          
          select  a.imp_id, b.emp_no  into p_imp_id, p_emp_no from fat_recoup_settle a, fam_imprest b
          where a.imp_id = b.imp_id and a.led_cd = b.led_cd
          and a.au6_no = p_au6_no
          and a.led_cd = p_led_cd;

          -- p_stat := dbinfo("SQLCA.SQLERRD2");
              
              INSERT INTO fat_books_imp (txn_no,sr_no,txn_dt,au6_no,alloc_dt,
                                         alloc_amt,dr_cr_flag,acct_head,cc_cd,
                                         mod_cd,led_cd,imp_id,emp_no)
                                         VALUES
                                        ( p_txn_no,p_sr_no,p_txn_dt,p_au6_no,p_alloc_dt,
                                          p_alloc_amt,p_dr_cr_flag,p_acct_head,p_cc_cd,
                                          p_mod_cd,p_led_cd,p_imp_id,p_emp_no);
            	-- p_stat := dbinfo("SQLCA.SQLERRD2");          
				
				

       END IF;

       IF p_mod_cd = 'EB' THEN
         

              
              INSERT INTO fat_books_ext (txn_no,sr_no,txn_dt,au6_no,alloc_dt,
                                         alloc_amt,dr_cr_flag,acct_head,cc_cd,
                                         mod_cd,led_cd,party_cd,con_no,po_no,mod_stat)
                                         VALUES
                                        ( p_txn_no,p_sr_no,p_txn_dt,p_au6_no,p_alloc_dt,
                                          p_alloc_amt,p_dr_cr_flag,p_acct_head,p_cc_cd,
                                          p_mod_cd,p_led_cd,null,null,null,null);
            	-- p_stat := dbinfo("SQLCA.SQLERRD2");
				
				
				

       END IF;


END ;
$$;


