--
-- TOC entry 6889 (class 1255 OID 23840)
-- Name: fa_sp_cent_oth0001(integer, character, numeric, date, integer, character, integer, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_cent_oth0001(cc_cd_in_l integer, dr_acct_head_in_l character, tran_amt_in_l numeric, tran_date_in_l date, au6_no_in_l integer, led_cd_in_l character, txn_no_in_l integer, mod_cd_in_l character) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE 
	p_status INT;
	cash_acct_head_l fam_acct.acct_head%type;
	p_narrat1        fat_narrat.narrat%type;
	p_stn_name       fam_ledger.short_name%type;
	v_rowcount INT;

--ON EXCEPTION
--	SET    p_status
--	RETURN  p_status;
--END EXCEPTION WITH RESUME;

--set debug file to "/tmp/fa_sp_cent_oth0001.dbg";
--trace on ;

-- SELECT cash_acct_head_l

BEGIN

-- Get cash account head for station operations
SELECT acct_head
INTO   cash_acct_head_l
FROM   fam_def_acct
WHERE  mod_cd = 'CHS';

--LET p_status = dbinfo("sqlca.sqlerrd2");

Get diagnostics v_rowcount = row_count;
        p_status := v_rowcount ;
		
IF p_status <> 1 THEN                                     
	RETURN  p_status;
END IF;

-- Pass Narrations
SELECT short_name 
INTO p_stn_name
FROM fam_ledger
WHERE led_cd = led_cd_in_l;

p_narrat1 := 'Being The Amount Refunded From '||p_stn_name;

p_status := fa_sp_narrat(led_cd_in_l,txn_no_in_l,p_narrat1,'');
IF p_status <> 0 THEN
	RETURN  p_status;
END IF ;

-- Pass allocations
p_status := fa_sp_alloc002(  led_cd_in_l,txn_no_in_l,cc_cd_in_l,
				dr_acct_head_in_l,cash_acct_head_l,
				tran_amt_in_l,tran_date_in_l,mod_cd_in_l,
				au6_no_in_l );
IF p_status <> 0 THEN
	RETURN  p_status;
END IF ;

RETURN  p_status;

END;
	
$$;


ALTER FUNCTION public.fa_sp_cent_oth0001(cc_cd_in_l integer, dr_acct_head_in_l character, tran_amt_in_l numeric, tran_date_in_l date, au6_no_in_l integer, led_cd_in_l character, txn_no_in_l integer, mod_cd_in_l character) OWNER TO postgres;

--
-- TOC entry 6890 (class 1255 OID 23841)
-- Name: fa_sp_cent_ta0001(character, character, character, numeric, character, character, character, character, character, date, character, character, integer, integer, character, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_cent_ta0001(stn_cd_in_l character, party_name_in_l character, pay_mode_in_l character, mr_amt_in_l numeric, cr_acct_head_in_l character, gc_flag_in_l character, bank_name_in_l character, bank_brch_in_l character, chq_dd_no_in_l character, chq_dd_dt_in_l date, login_id_in_l character, led_cd_in_l character, mr_no_in_l integer, txn_no_in_l integer, dep_bank_cd_in_l character, alloc_dt_in_l date) RETURNS integer
    LANGUAGE plpgsql
    AS $$

-- Procedure returns status and MR Number
-- Status 0 is transaction is over
DECLARE
	p_status                int;
	cc_cd_l                  faa_alloc.cc_cd%type;
	dr_acct_head_l           fam_acct.acct_head%type;
	id_desc_l                fat_mrr.id_desc%type;
	cash_acct_head_l         fam_acct.acct_head%type;
	cit_acct_head_l          fam_acct.acct_head%type;
	mod_cd_l                 fam_sysmod.mod_cd%type;

	p_narrat1                fat_narrat.narrat%type;
	p_stn_name               fam_ledger.short_name%type;

	p_junk                int;
	v_rowcount INT;

BEGIN

--ON EXCEPTION
	--SET    p_status

--	trace "STATUS" ||p_status;

--RETURN  p_status;
--END EXCEPTION ;

--set debug file to "/tmp/fa_sp_cent_ta0001.dbg";
--trace on ;

	raise notice 'p_status2 %', p_status;	     
-- Initialise
	p_status     	:= 0;
	cc_cd_l     	:= 0;
	dr_acct_head_l 	:= '';
	id_desc_l      	:= '';
	cash_acct_head_l:= '';
	cit_acct_head_l := '';
	mod_cd_l 		:= 'TAC';
raise notice 'p_status3 %', p_status;
-- Get cash account head for station operations
SELECT acct_head
INTO   cash_acct_head_l
FROM   fam_def_acct
WHERE  mod_cd = 'CHS';

--LET p_status = dbinfo("sqlca.sqlerrd2");
Get diagnostics v_rowcount = row_count;
        p_status := v_rowcount ;
raise notice 'p_status1 %', p_status;		
		
IF p_status <> 1 THEN                                     
	RETURN  p_status;
END IF;

-- Get Chq/DD Remittance Account
SELECT acct_head
INTO   cit_acct_head_l
FROM   fam_def_acct
WHERE  mod_cd = 'GCQ';

--LET p_status = dbinfo("sqlca.sqlerrd2");
Get diagnostics v_rowcount = row_count;
        p_status := v_rowcount ;
IF p_status <> 1 THEN                                     
	RETURN  p_status;
END IF;

-- Let Cost Centre be for Comm & Coaching
SELECT comm_cc_cd
INTO   cc_cd_l
FROM   fap_fasys
WHERE  1=1;

IF (mr_amt_in_l > 0)
THEN

-- Creation of a MR begins here.
-- Form id_desc
	IF gc_flag_in_l = 'C'
	THEN
		id_desc_l := 'Earnings due to Coaching';
	ELSE
		id_desc_l := 'Earnings due to Goods';
	END IF;

-- Step 1 of 5 for MR
INSERT INTO fat_mrr (   mr_no,mr_dt,id_desc,party_name,pay_mode,
			paid_amt,ovr_paid_amt,reg_id,reg_dt,
			auth_id,auth_dt,rcpt_no,txn_no,rem_flag,
			stat,acct_head,
			bank_cd,led_cd,mr_cd,gc_flag,party_cd )
VALUES
		    (   mr_no_in_l,alloc_dt_in_l,id_desc_l,party_name_in_l,
			pay_mode_in_l,
			mr_amt_in_l,0,login_id_in_l,alloc_dt_in_l,
			login_id_in_l,alloc_dt_in_l,0,txn_no_in_l,'N',
			'A',cr_acct_head_in_l,
			dep_bank_cd_in_l,led_cd_in_l,
			'M99',gc_flag_in_l,'' );

--LET p_status = dbinfo("sqlca.sqlerrd2");
Get diagnostics v_rowcount = row_count;
        p_status := v_rowcount ;
IF p_status <= 0 THEN
	RETURN  p_status;
ELSE
	p_status := 0;
END IF;

-- In case of Cheque/DD receipt, there would be one MR for each,
-- in which case a record in fat_mrch needs to be inserted
-- Step 2 of 5 for MR
IF pay_mode_in_l != 'CH'
THEN
	INSERT INTO FAT_MRCH (  chq_dd_no,bank_name,
				bank_brch,chq_dd_dt,
				out_flag,led_cd,
				mr_no )
	VALUES
			     (  chq_dd_no_in_l,bank_name_in_l,
				bank_brch_in_l,chq_dd_dt_in_l,
				'Y',led_cd_in_l,
				mr_no_in_l );
	--LET p_status = dbinfo("sqlca.sqlerrd2");
	Get diagnostics v_rowcount = row_count;
        p_status := v_rowcount ;
	IF p_status <= 0 THEN
		RETURN  p_status;
	ELSE
		p_status := 0;
	END IF;
END IF;

-- Step 3 of 5 for MR

IF pay_mode_in_l != 'CH'
THEN
-- Select Bank Remittance A/c if payment mode is other than Cash
	dr_acct_head_l := cit_acct_head_l;
ELSE
-- Select Cash-In-Hand A/c for Cash payment mode
	dr_acct_head_l := cash_acct_head_l;
END IF;

-- Create a record in faa_alloc for Debiting Cash/Bank Remittance A/c
-- Step 4 of 5 for MR
	p_status := fa_sp_alloc002(  led_cd_in_l,txn_no_in_l,cc_cd_l,
				dr_acct_head_l,cr_acct_head_in_l,
				mr_amt_in_l,alloc_dt_in_l,mod_cd_l,mr_no_in_l );
---			To try  --- Sunil Joshi 27/11/2000
-- LET p_junk = dbinfo("sqlca.sqlerrd0");
-- trace "SQLCA" || p_junk;
--- trace p_status;
IF p_status <> 0 THEN
  raise exception '%', p_status;
	-- RETURN  p_status;
END IF ;
	
-- Give Narration for the MR
-- Step 5 of 5 for MR
SELECT short_name 
INTO p_stn_name
FROM fam_ledger
WHERE led_cd = led_cd_in_l;

IF gc_flag_in_l = 'C' THEN
	p_narrat1 := 'Receipts From '||p_stn_name||' Towards '||'Coaching Transactions ';
ELSE 
	p_narrat1 := 'Receipts From '||p_stn_name||' Towards '||'Freight Transactions ';
END IF;

	p_status := fa_sp_narrat(led_cd_in_l,txn_no_in_l,p_narrat1,mr_no_in_l::text);
IF p_status <> 0 THEN
	RETURN  p_status;
END IF ;
-- Creation of MR ends here

ELSE
-- ELSE above is for condition (mr_amt_in_l > 0)
-- Reduce credit of TA by MR Amt passed
	mr_amt_in_l := -1 * mr_amt_in_l;
-- Put entry in faw_oth_tran and Dr cr A/c passed here, TA 
-- & Cr Cash.
	p_status := fa_sp_cent_oth0001(cc_cd_l,cr_acct_head_in_l,mr_amt_in_l,
			alloc_dt_in_l,0,led_cd_in_l,txn_no_in_l,mod_cd_l);

END IF; 
-- END IF above is for condition (mr_amt_in_l > 0)

-- RETURN status only
RETURN p_status;

END;
	
$$;


ALTER FUNCTION public.fa_sp_cent_ta0001(stn_cd_in_l character, party_name_in_l character, pay_mode_in_l character, mr_amt_in_l numeric, cr_acct_head_in_l character, gc_flag_in_l character, bank_name_in_l character, bank_brch_in_l character, chq_dd_no_in_l character, chq_dd_dt_in_l date, login_id_in_l character, led_cd_in_l character, mr_no_in_l integer, txn_no_in_l integer, dep_bank_cd_in_l character, alloc_dt_in_l date) OWNER TO postgres;

--
-- TOC entry 6891 (class 1255 OID 23843)
-- Name: fa_sp_fat_to_faa(character, character, integer, integer, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_fat_to_faa(mod_cd_in_l character, led_cd_in_l character, txn_no_in_l integer, au6_no_in_l integer, txn_dt_in_l date) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE p_status INTEGER;
 p_no_of_rows INTEGER;
 sr_no_l  faa_alloc.sr_no%type;
 alloc_dt_l  faa_alloc.alloc_dt%type;
 alloc_amt_l  faa_alloc.alloc_amt%type;
 neg_alloc_amt_l  faa_alloc.alloc_amt%type;
 dr_cr_flag_l  faa_alloc.dr_cr_flag%type;
 acct_head_l  faa_alloc.acct_head%type;
 cc_cd_l  faa_alloc.cc_cd%type;
 v_rowcount integer ;
BEGIN

/*
SET debug file to "/tmp/fa_sp_fat_to_faa.dbg";
TRACE ON;
*/
FOR sr_no_l, alloc_dt_l, alloc_amt_l, dr_cr_flag_l, acct_head_l, cc_cd_l IN SELECT sr_no,alloc_dt,alloc_amt,dr_cr_flag,acct_head,cc_cd
        FROM   fat_alloc
        WHERE  led_cd = led_cd_in_l
        AND    txn_no = txn_no_in_l LOOP


        INSERT INTO faa_alloc
        (txn_no, sr_no, txn_dt, au6_no, alloc_dt, alloc_amt, dr_cr_flag,
         acct_head, cc_cd, mod_cd, led_cd)
        VALUES
        (txn_no_in_l,sr_no_l,txn_dt_in_l,au6_no_in_l,alloc_dt_l,alloc_amt_l,
         dr_cr_flag_l,acct_head_l,cc_cd_l,mod_cd_in_l,led_cd_in_l);

       -- p_status := dbinfo("SQLCA.SQLERRD2") ;
		
		Get diagnostics v_rowcount = row_count;
        if  v_rowcount > 0 THEN 
		    p_status :=0 ;
		ELSE 
		    p_status := 100 ;
		END IF ;
		
        IF p_status > 0 THEN
                p_status := 0;
        ELSE
                RETURN p_status;
        END IF;

        IF dr_cr_flag_l = "D" THEN

                UPDATE fam_acct_onbal
                SET    online_bal = online_bal + alloc_amt_l
                WHERE  led_cd = led_cd_in_l 
                AND    acct_head = acct_head_l;

             --   p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
				Get diagnostics v_rowcount = row_count;
				p_no_of_rows := v_rowcount ;


                IF p_no_of_rows <= 0  THEN

                        INSERT INTO fam_acct_onbal
                        (led_cd,acct_head,online_bal)
                        VALUES (led_cd_in_l,acct_head_l,alloc_amt_l);

                  ---      p_status := dbinfo("SQLCA.SQLERRD2") ;
				  Get diagnostics v_rowcount = row_count;
				   if v_rowcount > 0 THEN 
				     p_status := 0 ;
				    ELSE 
					  p_status := 100; 
					END IF ;
				  
				  
                        IF p_status > 0 THEN
                                p_status := 0;
                        ELSE
                                RETURN p_status;
                        END IF;
                END IF;

        ELSE

                UPDATE fam_acct_onbal
                SET    online_bal = online_bal - alloc_amt_l
                WHERE  led_cd = led_cd_in_l 
                AND    acct_head = acct_head_l;

                --p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
				 Get diagnostics v_rowcount = row_count;
				 
				 p_no_of_rows := v_rowcount ;

                IF p_no_of_rows <= 0  THEN
                        neg_alloc_amt_l := -1 * alloc_amt_l;


                        INSERT INTO fam_acct_onbal
                        (led_cd,acct_head,online_bal)
                        VALUES (led_cd_in_l,acct_head_l,neg_alloc_amt_l);

                     ---   p_status := dbinfo("SQLCA.SQLERRD2") ;
						 Get diagnostics v_rowcount = row_count;
						 
						if v_rowcount > 0 THEN 
						   p_status := 0 ;
						else 
						   p_status := 100 ;
						end if ;
						
                        IF p_status > 0 THEN
                                p_status := 0;
                        ELSE
                                RETURN p_status;
                        END IF;
                END IF;

        END IF;

END LOOP;

DELETE FROM fat_alloc
WHERE  led_cd = led_cd_in_l
AND    txn_no = txn_no_in_l;

RETURN p_status;



END ;
$$;


ALTER FUNCTION public.fa_sp_fat_to_faa(mod_cd_in_l character, led_cd_in_l character, txn_no_in_l integer, au6_no_in_l integer, txn_dt_in_l date) OWNER TO postgres;

--
-- TOC entry 6892 (class 1255 OID 23844)
-- Name: fa_sp_gen_oldnxt(character, character, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_gen_oldnxt(p_led_cd character, p_mod_cd character, INOUT p_stat integer, INOUT p_nxt_sr integer) RETURNS record
    LANGUAGE plpgsql
    AS $$

DECLARE p_nxt_sr                     fap_sysmod.last_yr_serno%type;
 p_nxt_sr_char            CHAR(9);
 p_main_mod_cd       fam_sysmod.main_mod_cd%type;
 p_stat                 SMALLINT;
 p_fin_yr       CHAR(4);
 p_yr_code              CHAR(4);
 p_loop           INT;
 p_no_of_rows     INT;
 v_rowcount  INT;
BEGIN

 ---- WITH RESUME

p_nxt_sr := 0;
p_stat := 0;

p_loop := 1 ;
WHILE (p_loop = 1 ) LOOP

           --     trace "p_led_cd in oldnxt porc :"||p_mod_cd;
           ---     trace "********** 1";
           --     trace "p_mod_Cd :"||p_led_cd;
                UPDATE fap_sysmod
                SET     last_yr_serno = last_yr_serno
                WHERE led_cd = p_led_cd
                AND     mod_cd = p_mod_cd  ;
           --     trace "********** 2";

               -- p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
                
                Get diagnostics v_rowcount = row_count;
                  p_no_of_rows = v_rowcount ;
                
                IF (p_stat = 0) AND (p_no_of_rows <= 0) THEN
                        p_stat := 100 ;
                END IF;

                p_stat := fa_sp_islock(p_stat) ;

                IF p_stat = 0 THEN
                        EXIT  ;
                END IF ;
                
              --  IF p_stat = 1 THEN
               ---         RETURN p_stat, 0 ;
               ---  END IF ;

END LOOP ;

SELECT last_yr_serno + 1 
INTO  p_nxt_sr
FROM    fap_sysmod
WHERE led_cd = p_led_cd AND
           mod_cd = p_mod_cd ;
---- Modified for txn no 03/05/2010 
---     LET p_nxt_sr_char =  fa_sp_int_to_char9(p_nxt_sr);
 IF p_mod_cd = 'TXN' THEN  
        p_nxt_sr_char :=  fa_sp_int_to_char9(p_nxt_sr);
 ELSE
        p_nxt_sr_char :=  p_nxt_sr;
        
        IF length(p_nxt_sr_char) = 8 THEN
                p_nxt_sr_char := '0'||p_nxt_sr_char;
        END IF; 
 END IF;
---- end  03/05/2010
        
--- p_fin_yr := p_nxt_sr_char[1,4];

p_fin_yr  = substring(p_nxt_sr_char, 2,4 );
-- trace "********** 3";
p_yr_code = fa_sp_get_year_cd(CURRENT_DATE - 365 ) ;
IF p_fin_yr <> p_yr_code THEN 
-- New fin_yr is started
        p_nxt_sr_char := p_yr_code||'00001';
END IF;
p_nxt_sr := p_nxt_sr_char;

UPDATE  fap_sysmod
SET     last_yr_serno = p_nxt_sr
WHERE led_cd = p_led_cd 
AND   mod_cd = p_mod_cd;

-- p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
Get diagnostics v_rowcount = row_count;

p_no_of_rows  := v_rowcount; 

IF (p_stat = 0) AND (p_no_of_rows <= 0) THEN
        p_stat := 100 ;
END IF;

END ;
$$;


ALTER FUNCTION public.fa_sp_gen_oldnxt(p_led_cd character, p_mod_cd character, INOUT p_stat integer, INOUT p_nxt_sr integer) OWNER TO postgres;

--
-- TOC entry 6893 (class 1255 OID 23845)
-- Name: fa_sp_gennxt(character, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_gennxt(p_user_id character, p_mod_cd character) RETURNS TABLE(p_stat integer, p_nxt_sr integer)
    LANGUAGE plpgsql
    AS $$

-- SQLINES DEMO *** ---------------------------------------------------
-- SQLINES DEMO ***  the next serial no. for the transaction or
-- SQLINES DEMO *** epending on the module code that we pass to this
-- SQLINES DEMO *** returns the next serial no. and the status
-- SQLINES DEMO *** tement.
-- SQLINES DEMO ***  serial no. is invalid if the returned status
-- is not zero.
-- SQLINES DEMO *** ---------------------------------------------------

declare	
--p_nxt_sr		fap_sysmod.last_au6_no%type ;
	p_reg_flag 		fap_sysmod.reg_flag%type ;
