if (p_stat != 0) then
	return next ;
end if ;

raise notice 'value % %',p_stat,p_led_cd;
begin
 -- SQLINES LICENSE FOR EVALUATION USE ONLY
 --with resume

	-- SQLINES DEMO *** w of fap_syamod by a dummy update.
