		where 	led_cd = p_led_cd
		and	mod_cd = p_mod_cd  ;

		-- SQLINES DEMO *** Deepa & Hema 
   	select * into p_nxt_sr_char from  fa_sp_int_to_char9(p_nxt_sr) ;
        IF  p_mod_cd = 'TXN' THEN
            p_nxt_sr_char := '0'||p_nxt_sr_char;
        END IF;
 -- SQLINES DEMO ***  By Dinesh
       p_nxt_sr_char := p_nxt_sr;
		p_fin_yr := substring(p_nxt_sr_char,1,4);
		select * into p_yr_code from fa_sp_get_year_cd(CURRENT_DATE);
		IF p_fin_yr <> p_yr_code THEN -- SQLINES DEMO *** ted
			p_nxt_sr := p_nxt_sr - 1;
		
			UPDATE fap_sysmod
			SET last_yr_serno = p_nxt_sr
			WHERE mod_cd =  p_mod_cd
			AND led_cd = p_led_cd;
                        IF p_mod_cd = 'TXN' THEN
	                   -- SQLINES DEMO *** = p_yr_code||"000001";
	                   p_nxt_sr_char := p_yr_code||"00001";
                        ELSE
	                   p_nxt_sr_char := p_yr_code||"00001";
                        END IF;
		END IF;
		p_nxt_sr := p_nxt_sr_char;
		 

	end if ;

	update	fap_sysmod
	set	last_au6_no = p_nxt_sr
	where 	led_cd = p_led_cd
	and	mod_cd = p_mod_cd  ;

--	p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
Get diagnostics v_rowcount = row_count;
        p_no_of_rows := v_rowcount ;

if (p_stat = 0) and (p_no_of_rows = 0) then
		p_stat := 100 ;
	end if;

	return next ;

end ;

exception when others then 
