CREATE FUNCTION public.fa_sp_gennxt002(led_cd_in_l character, mod_cd_in_l character, INOUT p_stat integer, INOUT p_nxt_sr integer) RETURNS record
    LANGUAGE plpgsql
    AS $$

--  *** ---------------------------------------------------
--  ***  the next serial no. for the transaction or
--  *** epending on the module code that we pass to this
--  *** returns the next serial no. and the status
--  *** tement.
--  ***  serial no. is invalid if the returned status
-- is not zero.
-- *** ---------------------------------------------------

declare
 --p_nxt_sr        integer ;
  p_reg_flag char(1);
  p_main_mod_cd   char(3) ;
  -- p_stat          int ;
  p_no_of_rows    int ;
  p_loop          int ;

   p_yr_code char(4);
   p_fin_yr char(4);
--   *** char char(9);
   p_nxt_sr_char char(10);
   v_rowcount  int;
BEGIN

--- set debug file to "/tmp/fa_sp_gennxt002.dbg";
--   *** t serial number to zero
p_nxt_sr := 0 ;
p_stat := 0;

      
 --with resume

        --   *** w of fap_syamod by a dummy update.
        --   *** n proceed else
        --   *** ying to lock it
        -- else returm error.

        p_loop := 1 ;
        while (p_loop = 1 ) loop

                update  fap_sysmod
                set     last_au6_no = last_au6_no
                where   led_cd = led_cd_in_l
                and     mod_cd = mod_cd_in_l  ;

               -- p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
			   Get diagnostics v_rowcount = row_count;
			   
			   p_no_of_rows:= v_rowcount ;
				---v_rowcount := p_no_of_rows ;

			   
                if (p_stat = 0) and (p_no_of_rows <= 0) then
                       p_stat := 100 ;
                end if;
              
               p_stat := fa_sp_islock(p_stat) ;

              raise notice '1 while ...p_stat %',p_stat ; 
                if p_stat = 0 then
                        exit  ;
                end if ;
                if p_stat = 1 then
                        --return p_stat, 0 ;
						--return next;
				p_nxt_sr := 0;		
                end if ;
              raise notice '2 while ...p_stat %',p_stat ;  
        end loop ;

        --   *** erial number +1 and find if the module
        --   *** er of its own or its parents has to be
        -- picked up.

       
        select  reg_flag,       last_au6_no + 1
        into    p_reg_flag, p_nxt_sr
        from    fap_sysmod
        where   led_cd = led_cd_in_l
        and     mod_cd = mod_cd_in_l  ;

    Raise notice '3 ..... p_reg_flag p_nxt_sr %,%,%', p_reg_flag, p_nxt_sr,mod_cd_in_l ;

   -- trace "p_nxt_sr "||p_nxt_sr;

   --   *** . Deepa & Hema
 --   *** erating of txn number  start
  
   IF mod_cd_in_l = 'TXN'  THEN
       -- CALL fa_sp_int_to_char9(p_nxt_sr) RETURN p_nxt_sr_char;
	    p_nxt_sr_char= fa_sp_int_to_char9(p_nxt_sr) ;
		 --perform fa_sp_int_to_char9(p_nxt_sr) ;
		 Raise notice '4 ..... p_nxt_sr_char %,%', p_nxt_sr_char, mod_cd_in_l;
   ELSE
       -- p_nxt_sr_char = p_nxt_sr;
	   p_nxt_sr_char= fa_sp_int_to_char9(p_nxt_sr) ;
   END IF ;
  --   *** Dinesh 
   -- p_nxt_sr_char := p_nxt_sr ;
 
  --   ***  "TXN" THEN
  --   *** _char = "0"||p_nxt_sr_char;
  --  END IF;
 --   *** erating of txn number  end   

       -- trace "p_nxt_sr_char "||p_nxt_sr_char;

   p_fin_yr := substring(p_nxt_sr_char, 2,4 );
  -- CALL fa_sp_get_year_cd(CURRENT_DATE) RETURNING p_yr_code  ;
  -- CALL fa_sp_get_year_cd(CURRENT_DATE)  ;
       -- trace "4 digit yr code: "||p_yr_code;
	 raise notice '5 ...p_fin_yr %',p_fin_yr ;   
   p_yr_code=fa_sp_get_year_cd(CURRENT_DATE)  ;
   
    raise notice '6 ...p_yr_code %',p_yr_code ;

   IF p_fin_yr <> p_yr_code THEN --   *** ted
              --  trace "New Financial year !!! ";
           p_nxt_sr := p_nxt_sr - 1;

          raise notice '7 ...p_nxt_sr %',p_nxt_sr ;

           UPDATE fap_sysmod
           SET last_yr_serno = p_nxt_sr
           WHERE mod_cd =  mod_cd_in_l
           AND led_cd = led_cd_in_l;

           IF mod_cd_in_l = 'TXN' THEN
              --   *** = p_yr_code||"000001";
              p_nxt_sr_char := p_yr_code||'00001';
           ELSE
              p_nxt_sr_char := p_yr_code||'00001';
           END IF;
		   
		    raise notice '8 ...p_nxt_sr_char %',p_nxt_sr_char ;
   END IF;
   p_nxt_sr := p_nxt_sr_char;
      --  trace "Final p_nxt_sr_char "||p_nxt_sr_char;
   ---

        if p_reg_flag = 'N' then

        --        trace "p_reg_flag = 'N' !!! ";
                --   ***  of the current module.
               
                select  fam_sysmod.main_mod_cd
                into    p_main_mod_cd
                from    fam_sysmod
                where   fam_sysmod.mod_cd = mod_cd_in_l ;

                mod_cd_in_l := p_main_mod_cd ;

                raise notice '9 ...mod_cd_in_l %',mod_cd_in_l ;  
                --   *** w of fap_syamod by a dummy update.
                --   *** n proceed else
                --   *** ying to lock it
                -- else returm error.

                p_loop := 1 ;
                while (p_loop = 1 ) loop
                        update  fap_sysmod
                        set     last_au6_no = last_au6_no
                        where   led_cd = led_cd_in_l
                        and     mod_cd = mod_cd_in_l  ;

                    --    p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
--                         if (p_stat = 0) and (p_no_of_rows <= 0) then
--                                 p_stat := 100 ;
--                         end if;

                       p_stat := fa_sp_islock(p_stat) ;

                        if p_stat = 0 then
                                exit  ;
                        end if ;
                        if p_stat = 1 then
                               -- return p_stat, 0 ;
							   --return next ;
                        end if ;

                end loop ;

                
                select  last_au6_no + 1
                into    p_nxt_sr
                from    fap_sysmod
                where   led_cd = led_cd_in_l
                and     mod_cd = mod_cd_in_l  ;
				
				Raise notice '10.... p_nxt_sr %',p_nxt_sr;

                --   *** Deepa & Hema
        --CALL fa_sp_int_to_char9(p_nxt_sr) RETURNING p_nxt_sr_char;
		 p_nxt_sr_char = fa_sp_int_to_char9(p_nxt_sr) ;
		
        IF  mod_cd_in_l = 'TXN' THEN
            p_nxt_sr_char := "0"||p_nxt_sr_char;
        END IF;
		
		Raise notice '11.... p_nxt_sr_char %',p_nxt_sr_char;
  --   *** Dinesh 
   p_nxt_sr_char := p_nxt_sr ;
                p_fin_yr := substring(p_nxt_sr_char, 2,4 );
               -- CALL fa_sp_get_year_cd(CURRENT_DATE) RETURNING p_yr_code;
				p_yr_code =fa_sp_get_year_cd(CURRENT_DATE);
				
			Raise notice '12.... p_fin_yr p_yr_code %, %',p_fin_yr,p_yr_code ;	
				
                IF p_fin_yr <> p_yr_code THEN --   *** ted
                        p_nxt_sr := p_nxt_sr - 1;

                        UPDATE fap_sysmod
                        SET last_yr_serno = p_nxt_sr
                        WHERE mod_cd =  mod_cd_in_l
                        AND led_cd = led_cd_in_l;

                        IF mod_cd_in_l = 'TXN' THEN
                           --   *** = p_yr_code||"000001";
                           p_nxt_sr_char := p_yr_code||'00001';
                        ELSE
                           p_nxt_sr_char := p_yr_code||'00001';
                        END IF;
						
						Raise notice '13.... p_nxt_sr_char %',p_nxt_sr_char ;
        --   *** p_nxt_sr_char = p_yr_code||"00001";
                END IF;
                p_nxt_sr := p_nxt_sr_char;
                ---

        end if ;

        update  fap_sysmod
        set     last_au6_no = p_nxt_sr
        where   led_cd = led_cd_in_l
        and     mod_cd = mod_cd_in_l  ;

       -- p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
	   
       --- if (p_stat = 0) and (p_no_of_rows <= 0) then
        ---        p_stat := 100 ;
       --- end if;
  -- trace "fap_sysmod updated to "||p_nxt_sr||" for led_cd "||led_cd_in_l||" & "||mod_cd_in_l;
	Raise notice ' 14 ... p_stat p_nxt_sr %,%,%',p_stat,p_nxt_sr,mod_cd_in_l ;
        -- return next ;
    Raise notice ' 15 ... p_stat p_nxt_sr %,%',p_stat,p_nxt_sr; 
	
	exception when others then 
    raise notice 'EXCEPTION % %',sqlstate, SQLERRM;
	
END ;
$$;


ALTER FUNCTION public.fa_sp_gennxt002(led_cd_in_l character, mod_cd_in_l character, INOUT p_stat integer, INOUT p_nxt_sr integer) OWNER TO postgres;

