CREATE FUNCTION public.fa_sp_gennxt003(led_cd_in_l character, mod_cd_in_l character) RETURNS TABLE(p_stat integer, p_nxt_sr integer)
    LANGUAGE plpgsql
    AS $$
-----------------------------------------------------------------------
-- This SP generates the next serial no. for the transaction or
-- the new bill no depending on the module code that we pass to this
-- function. The SP returns the next serial no. and the status
-- of the update statement.
-- Kindly note : The serial no. is invalid if the returned status
-- is not zero.
-----------------------------------------------------------------------

declare  
  ----p_nxt_sr        like    fap_sysmod.last_au6_no ;
  p_reg_flag      CHAR(1);
  p_main_mod_cd   CHAR(3) ;
  -- p_stat          int ;
  p_no_of_rows    int ;
  p_loop          int ;

   p_yr_code char(4);
   p_fin_yr char(4);
-- p_nxt_sr_char char char(9);
   p_nxt_sr_char char(10);
   v_rowcount  int ;
   
BEGIN  

-- set debug file to "/tmp/fa_sp_gennxt002.dbg";
--  *** t serial number to zero
 p_nxt_sr := 0 ;
p_stat := 0;

        
 --- with resume

        -- Lock the reqd. row of fap_syamod by a dummy update.
        -- If successful then proceed else
        -- if locked keep trying to lock it
        -- else returm error.

        p_loop := 1 ;
        while (p_loop = 1 ) loop

                update  fap_sysmod
                set     last_au6_no = last_au6_no
                where   led_cd = led_cd_in_l
                and     mod_cd = mod_cd_in_l  ;
				
				Get diagnostics v_rowcount = row_count;
                 v_rowcount := p_no_of_rows ;

          ---      p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
               if (p_stat = 0) and (p_no_of_rows <= 0) then
                       p_stat := 100 ;
               end if;

               p_stat := fa_sp_islock(p_stat) ;

                if p_stat = 0 then
                        exit   ;
                end if ;
                if p_stat = 1 then
                        return next ;
                end if ;

        end loop ;

         -- select the last serial number +1 and find if the module
        -- has a serial number of its own or its parents has to be
        -- picked up.

       
        select  reg_flag,       last_au6_no + 1
        into    p_reg_flag, p_nxt_sr
        from    fap_sysmod
        where   led_cd = led_cd_in_l
        and     mod_cd = mod_cd_in_l  ;

   --- trace "p_nxt_sr "||p_nxt_sr;

  --- Resetting Nos.... Deepa & Hema
 ---- Changes for generating of txn number  start  
 
   IF mod_cd_in_l = 'TXN'  THEN
        --- CALL fa_sp_int_to_char9(p_nxt_sr) RETURNING p_nxt_sr_char;
        p_nxt_sr_char = fa_sp_int_to_char9(p_nxt_sr) ;
   ELSE
        --- p_nxt_sr_char := p_nxt_sr;
		
		 p_nxt_sr_char = fa_sp_int_to_char9(p_nxt_sr) ;
   END IF ;
  ---- Added one line By Dinesh
   
       -- p_nxt_sr_char := p_nxt_sr;
 
 -- IF  mod_cd_in_l = "TXN" THEN
  --      LET p_nxt_sr_char = "0"||p_nxt_sr_char;
  --  END IF;
 ---- Changes for generating of txn number  end   
 

       --- trace "p_nxt_sr_char "||p_nxt_sr_char;

  ---  p_fin_yr := p_nxt_sr_char[1,4];
    p_fin_yr := substring(p_nxt_sr_char, 2,4 );
   
   raise notice ' ...p_fin_yr %',p_fin_yr ; 
  --  CALL fa_sp_get_year_cd(TODAY) RETURNING p_yr_code  ;
   p_yr_code = fa_sp_get_year_cd(CURRENT_DATE) ;
   
      --  trace "4 digit yr code: "||p_yr_code;

   IF p_fin_yr <> p_yr_code THEN 
               --  trace "New Financial year !!! ";
           p_nxt_sr := p_nxt_sr - 1;

           UPDATE fap_sysmod
           SET last_yr_serno = p_nxt_sr
           WHERE mod_cd =  mod_cd_in_l
           AND led_cd = led_cd_in_l;

           IF mod_cd_in_l = 'TXN' THEN
            
              p_nxt_sr_char := p_yr_code||'00001';
           ELSE
              p_nxt_sr_char := p_yr_code||'00001';
           END IF;
   END IF;
   p_nxt_sr := p_nxt_sr_char;
       ---  trace "Final p_nxt_sr_char "||p_nxt_sr_char;
   ---

        if p_reg_flag = 'N' then

              ---  trace "p_reg_flag = 'N' !!! ";
                -- Obtain the parent of the current module.
                
                select  fam_sysmod.main_mod_cd
                into    p_main_mod_cd
                from    fam_sysmod
                where   fam_sysmod.mod_cd = mod_cd_in_l ;

                mod_cd_in_l := p_main_mod_cd ;

                -- Lock the reqd. row of fap_syamod by a dummy update.
                -- If successful then proceed else
                -- if locked keep trying to lock it
                -- else returm error.

                p_loop := 1 ;
                while (p_loop = 1 ) loop
                        update  fap_sysmod
                        set     last_au6_no = last_au6_no
                        where   led_cd = led_cd_in_l
                        and     mod_cd = mod_cd_in_l  ;

                     --   p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
                     --   if (p_stat = 0) and (p_no_of_rows <= 0) then
                     --           p_stat := 100 ;
                     --   end if;

                        p_stat := fa_sp_islock(p_stat) ;

                        if p_stat = 0 then
                                exit  ;
                        end if ;
                        if p_stat = 1 then
                                return next ;
                        end if ;

                end loop ;

               
                select  last_au6_no + 1
                into    p_nxt_sr
                from    fap_sysmod
                where   led_cd = led_cd_in_l
                and     mod_cd = mod_cd_in_l  ;

                --- Resettin Nos... Deepa & Hema
                
        --- CALL fa_sp_int_to_char9(p_nxt_sr) RETURNING p_nxt_sr_char;
        
          p_nxt_sr_char = fa_sp_int_to_char9(p_nxt_sr) ;
        
        IF  mod_cd_in_l = 'TXN' THEN
            p_nxt_sr_char := '0'||p_nxt_sr_char;
        END IF;
    ---- Added one line By Dinesh
        p_nxt_sr_char := p_nxt_sr;
        
              ---  p_fin_yr := p_nxt_sr_char[1,4];
                 p_fin_yr := substring(p_nxt_sr_char, 1,4 );
                
              ---  CALL fa_sp_get_year_cd(TODAY) RETURNING p_yr_code;
                p_yr_code = fa_sp_get_year_cd(CURRENT_DATE) ;
                
                IF p_fin_yr <> p_yr_code THEN 
                        p_nxt_sr := p_nxt_sr - 1;

                        UPDATE fap_sysmod
                        SET last_yr_serno = p_nxt_sr
                        WHERE mod_cd =  mod_cd_in_l
                        AND led_cd = led_cd_in_l;

                        IF mod_cd_in_l = 'TXN' THEN
                           -- LET p_nxt_sr_char = p_yr_code||"000001";
                           p_nxt_sr_char := p_yr_code||'00001';
                        ELSE
                           p_nxt_sr_char := p_yr_code||'00001';
                        END IF;
        --  LET  p_nxt_sr_char = p_yr_code||"00001";
                END IF;
                p_nxt_sr := p_nxt_sr_char;
                

        end if ;

        update  fap_sysmod
        set     last_au6_no = p_nxt_sr
        where   led_cd = led_cd_in_l
        and     mod_cd = mod_cd_in_l  ;

      --   p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;
      --  if (p_stat = 0) and (p_no_of_rows <= 0) then
       --         p_stat := 100 ;
       -- end if;
  --  trace "fap_sysmod updated to "||p_nxt_sr||" for led_cd "||led_cd_in_l||" & "||mod_cd_in_l;

        return next ;      
END 
 
$$;


