--
-- TOC entry 6896 (class 1255 OID 23851)
-- Name: fa_sp_get_year_cd(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_get_year_cd(date_in_l date) RETURNS character
    LANGUAGE plpgsql
    AS $$
begin
 IF to_char(date_in_l, 'MM')::integer >= 4 THEN
 return ''||to_char(date_in_l , 'YY')||to_char(date_in_l +365 , 'YY');
 ELSE 
 return ''||to_char(date_in_l -365 , 'YY')||to_char(date_in_l, 'YY');
 END IF ;
end;
$$;


ALTER FUNCTION public.fa_sp_get_year_cd(date_in_l date) OWNER TO postgres;

