-- TOC entry 6897 (class 1255 OID 23852)
-- Name: fa_sp_int_to_char9(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_int_to_char9(p_no_int integer) RETURNS TABLE(p_no_char text)
    LANGUAGE plpgsql
    AS $$
 
BEGIN

CREATE TEMP TABLE FA_TEMP_NXTNO
(
   p_no int 
);

insert into FA_TEMP_NXTNO (p_no) values (p_no_int);

for p_no_char 
IN select ltrim(to_char(p_no, '0000000000')) as p_no_char from FA_TEMP_NXTNO loop

RETURN NEXT;
END LOOP;
--RETURN QUERY
 --select ltrim(to_char(p_no, '0000000000')) into p_no_char  from FA_TEMP_NXTNO;

 DROP TABLE IF EXISTS FA_TEMP_NXTNO;
END;
$$;


