--
-- TOC entry 6899 (class 1255 OID 23853)
-- Name: fa_sp_islock(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_islock(p_sqlcode integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

--  *** ---------------------------------------------------
--  ***  to find out the nature of the 
-- sqlca.sqlcode . 
--  *** tatement execution can be classified as either 
--  *** uccesful.
--  *** l could mean either that the resource is locked
--  *** rror has occured.
--  *** haracterisation of errors into three categories.
--  *** grams its sufficient to know into which class
--  ***  falls, the exact value is not of imprtance
-- at runtime.
--  *** however is to find out if the sqlca.sqlcode
--  ***  the resource is locked.  
--  ***  can be at varios levels the sqlca.sqlcode
--  *** t values depending on the type of lock.
--  *** types of locking as one as that is
--  *** ogram.
--  *** fall into the third category.
-- sqlca.sqlcode . 
--  *** ssified as follows 
--  ***     sqlca.sqlcode           return value
--  ***     : 0                     0
--  *** d   : -243, -244, -245,     -1 
--  ***       -250, -289
--  ***     :                       1
--  *** ----------------------------------------------
declare  p_ret_val       int;
BEGIN
if p_sqlcode = 0  then
        p_ret_val := 0 ;
elseif p_sqlcode = -289 then
        p_ret_val := -1;
elseif p_sqlcode = -250 then
        p_ret_val := -1;
elseif p_sqlcode = -243 then
        p_ret_val := -1;
elseif p_sqlcode = -244 then
        p_ret_val := -1;
elseif p_sqlcode = -245 then
        p_ret_val := -1;
else 
        p_ret_val := 1 ;
end if ; 

return p_ret_val ;
END 
$$;


ALTER FUNCTION public.fa_sp_islock(p_sqlcode integer) OWNER TO postgres;

