	-- p_status  INT ;
	 p_loc_cd  fat_jvhd.loc_cd%type;
	 p_cc_cd   fam_cc.cc_cd%type;
	 v_rowcount int;

BEGIN
--on exception
	--set p_status
	--RETURN p_status, p_jv_no ;
--end exception with resume;

--set debug file to "/tmp/fa_jv0004.dbg";
--trace on;

--trace "p_led_cd " || (p_led_cd);
--p_status := 0;
--p_jv_no := 0;
IF p_jv_amt < 0
THEN
	p_jv_amt := -1 * p_jv_amt;
END IF;

--IF p_led_cd IS NULL THEN
