  -- FROM fam_ledger
   --WHERE stn_cde = p_stn_cde;
--ELSE
 --  SELECT cc_cd INTO p_cc_cd
  -- FROM fam_ledger
  -- WHERE led_cd = p_led_cd;
--END IF;
raise notice 'p_reg_id %',p_reg_id;
select * into p_status , p_cc_cd from fa_sp_cc_cd(p_reg_id, 0, 0);
raise notice 'p_status %, p_cc_cd %',p_status , p_cc_cd;
p_loc_cd := 'BLP';

--SELECT loc_cd INTO p_loc_cd
--FROM fam_loc
--WHERE led_cd = p_led_cd;

--Deepa & Hema on 29/03/00
raise notice '8 %', p_jv_date;
IF fa_sp_last_fin_yr(p_jv_date) = 1 THEN 
raise notice '10 %',p_status;
		-- Generate JV No. For last Fin. Year
		--trace "p_led_cd in JV proc :"||p_led_cd;
		select * into p_status, p_jv_no from fa_sp_gen_oldnxt(p_led_cd, 'JV',0,0 );
		raise notice '1 %',p_status;
		IF p_status <> 0 THEN
			--RETURN p_status, 0;
			RETURN next;
		END IF ;
	
		-- Generate TXN No. For last Fin. Year
		select * into p_status, p_txn_no from fa_sp_gen_oldnxt(p_led_cd, 'TXN',0,0);
	raise notice '2 %',p_status;
		IF p_status <> 0 THEN
			--RETURN p_status, 0;
			return next;
		END IF ;
ELSE

raise notice '9 %',p_status;
-- Generate JV No. For current Fin. Year
		select * into p_status, p_jv_no from fa_sp_gennxt002(p_led_cd, 'JV', 0, 0) ;
raise notice '3 %',p_status;
		IF p_status <> 0 THEN
			--RETURN p_status, 0;
			return next;
		END IF ;
	
		-- Generate TXN No. For current Fin. Year
		select * into p_status, p_txn_no from fa_sp_gennxt002(p_led_cd, 'TXN',0,0);
	raise notice '4 %',p_status;
		IF p_status <> 0 THEN
			--RETURN p_status, 0;
			return next;
		END IF ;
END IF;

raise notice 'test 1 %', p_jv_date;
INSERT INTO fat_jvhd
		(jv_no ,	jv_type ,
		jv_dt , 	jv_amt ,
		reg_id , 	auth_id	,
		reg_dt , 	auth_dt	,
		post_dt , 	doc_type	,
		fa_doc_no,	asset_gen_flag ,
		txn_no,	  	rem_flag ,
		stat,		led_cd ,
		loc_cd )
VALUES (    p_jv_no, p_jv_type,
		p_jv_date::date, p_jv_amt,
		p_reg_id, '',
		p_jv_date::date, null,
		p_jv_date::date, p_doc_type,
		p_fa_doc_no, p_asset_gen_flag,
		p_txn_no, 'N',
		'R', p_led_cd,
		p_loc_cd);
raise notice 'test 2';
    --let p_status = dbinfo("sqlca.sqlerrd2");
	Get diagnostics v_rowcount = row_count;
        p_status := v_rowcount ;
		raise notice '5 %',p_status;
    IF p_status <> 1 THEN
		--RETURN p_status, p_jv_no ;
		return next;
    END IF;
-- Narrat
raise notice 'p_led_cd %, p_txn_no %, p_narrat %',p_led_cd, p_txn_no, p_narrat;
p_status := fa_sp_narrat(p_led_cd, p_txn_no, p_narrat, '');
raise notice '6 %',p_status;
IF p_status <> 0 THEN
	--RETURN p_status, 0 ;
	return next;
END IF ;

-- Pass Allocations
raise notice '20 %',p_status;
	p_status := fa_sp_alloc102(  p_led_cd,p_txn_no,p_cc_cd,
				p_dr_acct_head,p_cr_acct_head,
				p_jv_amt,p_jv_date);
				raise notice '7 %',p_status;
raise notice '21 %',p_status;
IF p_status <> 0 THEN
	--return p_status, 0;
	return next;
END IF;

RETURN next ;

raise notice 'p_status %, p_jv_no %', p_status, p_jv_no;

exception when others then 
    raise notice 'EXCEPTION % %',sqlstate, SQLERRM;
	--return next;

END;
	
$$;


