-- SQLINES LICENSE FOR EVALUATION USE ONLY
SELECT comm_cc_cd INTO p_cc_cd
FROM fap_fasys ;

--CALL fa_sp_alloc002(p_led_cd, p_txn_no, p_cc_cd, dr_acct_head_in_l, 
