p_status := fa_sp_alloc002(p_led_cd, p_txn_no, p_cc_cd, dr_acct_head_in_l, 
cr_acct_head_in_l, p_jv_amt, p_reg_dt, p_mod_cd, p_jv_no);

IF p_status <> 0 THEN
