p_narrat1 := 'Being the amount put in Salary Suspense A/c' ;
p_narrat2 := ' ' ;

p_status :=  fa_sp_narrat(p_led_cd, p_txn_no, p_narrat1, p_narrat2);

IF p_status <> 0 THEN
	RETURN p_status ;
END IF ;

RETURN p_status;

EXCEPTION
 when others then
   --set p_status
   return p_status;

END ;
$$;


ALTER FUNCTION public.fa_sp_jv0011(jv_amt_in_l numeric, reg_id_in_l character, reg_dt_in_l date, p_cc_cd integer, dr_acct_head_in_l character) OWNER TO postgres;

--
-- TOC entry 6898 (class 1255 OID 23857)
-- Name: fa_sp_last_fin_yr(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_last_fin_yr(post_dt_in_l date) RETURNS smallint
    LANGUAGE plpgsql
    AS $$


DECLARE curr_yr_end_dt_l DATE;
 book_clos_dt_l   DATE;
 yr_end_mth_l     CHAR(2);
 post_mth_l       CHAR(2);
 curr_mth         SMALLINT;
 book_cls_mth     SMALLINT;
BEGIN

post_mth_l := EXTRACT(MONTH FROM post_dt_in_l);


SELECT yr_end_dt
INTO   curr_yr_end_dt_l
FROM   fap_year
WHERE  stat = 'Y';

yr_end_mth_l := EXTRACT(MONTH FROM curr_yr_end_dt_l);


SELECT book_clos_dt
INTO   book_clos_dt_l
FROM   fap_fasys
WHERE  1=1;

IF (CURRENT_DATE >= curr_yr_end_dt_l AND CURRENT_DATE <= book_clos_dt_l) THEN
        IF post_mth_l = yr_end_mth_l THEN
                RETURN 1;
        ELSE
                RETURN 0;
        END IF;
ELSE
        RETURN 0;
END IF;

END;
$$;


ALTER FUNCTION public.fa_sp_last_fin_yr(post_dt_in_l date) OWNER TO postgres;

