CREATE FUNCTION public.fa_sp_main_eb(mod_cd_in_l character, reg_dt_in_l date, bill_mth_yr_in_l timestamp without time zone, gross_sal_amt_in_l numeric, tot_amt_in_l numeric, nos_sub_bills_in_l integer, reg_id_in_l character) RETURNS TABLE(p_status integer, au6_no_out_l integer)
    LANGUAGE plpgsql
    AS $$

