SET DEBUG FILE TO "/tmp/fa_sp_main_eb.dbg";
TRACE ON;
*/
-- Initialise
p_status := 0;
au6_no_out_l := 0;

-- Validate type of Bill
IF mod_cd_in_l NOT IN ('EBS','ED0','ED1') THEN
        p_status := 100;
        RETURN next ;
        
END IF;
Raise notice 'Mod Code  %' , mod_cd_in_l ;
-- Get ledger code for Central Office

perform fa_sp_ledger002('BLP',p_status,led_cd_l);

IF p_status != 0 THEN
       -- RETURN p_status, au6_no_out_l;
	   return next ;
END IF;

perform fa_sp_gennxt002(led_cd_l, mod_cd_in_l, p_status, au6_no_out_l) ;


-- IF p_status <> 0 THEN
--         RETURN p_status, 0;
-- END IF;


SELECT a.mod_desc
INTO   est_bill_desc_l
FROM   fam_sysmod a
WHERE  a.mod_cd = mod_cd_in_l;


INSERT INTO fat_ebhead (au6_no, bill_mth_yr, reg_dt, est_bill_desc,
tot_amt, nos_sub_bills, reg_id, gross_sal_amt, mod_cd, led_cd)
VALUES (au6_no_out_l, bill_mth_yr_in_l, reg_dt_in_l, est_bill_desc_l,
tot_amt_in_l, nos_sub_bills_in_l, reg_id_in_l, gross_sal_amt_in_l,
mod_cd_in_l, led_cd_l);

-- p_status := dbinfo("SQLCA.SQLERRD2");
Get diagnostics v_rowcount = row_count;
p_status := v_rowcount ;

IF p_status <= 0
THEN
       -- RETURN p_status, au6_no_out_l;
	   RETURN NEXT ;
ELSE
        p_status := 0;
END IF;

return next ;

-- RETURN p_status, au6_no_out_l;
-- EXCEPTION
--  WHEN OTHERS THEN
--         SET    p_status
--         RETURN p_status, 0;

END;
$$;


