--
-- TOC entry 6908 (class 1255 OID 23861)
-- Name: fa_sp_narrat(character, integer, character, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_narrat(p_led_cd character, p_txn_no integer, p_narrat1 character, p_narrat2 character) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare  p_stat          int ;
  p_no_of_rows    int ;
  p_sr_no         int ;
BEGIN

p_stat := 0 ;

 ---with resume
/*
set debug file to "/tmp/fa_sp.db" ;
trace on;
*/

if p_txn_no = 0 then 
        return 100 ;
end if;

if (p_narrat1 is null or p_narrat1 = ' ') and (p_narrat2 is null or p_narrat2 = ' ') then
        return 100 ;
end if;

p_sr_no := 0 ;

if p_narrat1 is not null and p_narrat1 != ' ' then
        p_sr_no := p_sr_no  + 1 ;

        
        insert into fat_narrat
        (led_cd,                txn_no,
        sr_no,                  narrat)
        values
        (p_led_cd,              p_txn_no,
        p_sr_no,                p_narrat1) ;

     --   p_no_of_rows := dbinfo('SQLCA.SQLERRD2') ;
--         if (p_stat = 0) and (p_no_of_rows = 0) then
--                 p_stat := 100 ;
--         end if;

        if (p_stat != 0) then
                return p_stat ;
        end if;
end if;
if p_narrat2 is not null and p_narrat2 != ' ' then
        p_sr_no := p_sr_no  + 1 ;

        
        insert into fat_narrat
        (led_cd,                txn_no,
        sr_no,                  narrat)
        values
        (p_led_cd,              p_txn_no,
        p_sr_no,                p_narrat2) ;

--         p_no_of_rows := dbinfo('SQLCA.SQLERRD2') ;
--         if (p_stat = 0) and (p_no_of_rows = 0) then
--                 p_stat := 100 ;
--         end if;

        if (p_stat != 0) then
                return p_stat ;
        end if;
end if;

return p_stat ;

END ;
$$;


ALTER FUNCTION public.fa_sp_narrat(p_led_cd character, p_txn_no integer, p_narrat1 character, p_narrat2 character) OWNER TO postgres;

--
-- TOC entry 6909 (class 1255 OID 23862)
-- Name: fa_sp_narstn(character, integer, integer, character, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_narstn(p_led_cd character, p_txn_no integer, p_sr_no integer, p_narrat1 character, p_flag character) RETURNS smallint
    LANGUAGE plpgsql
    AS $$

/*

trace on;
set debug file to "/tmp/fa_sp.dbg";
*/

 
DECLARE p_ret1 SMALLINT;
BEGIN
p_ret1 := 1;  
IF p_flag = 'D' THEN
        DELETE FROM fat_narrat where
        led_cd = p_led_cd AND
        txn_no = p_txn_no;
END IF ;
IF p_flag = 'R' THEN
              insert into fat_narrat
        (led_cd,                txn_no,
        sr_no,                  narrat)
        values
        (p_led_cd,              p_txn_no,
        p_sr_no,                p_narrat1) ;
END IF;
RETURN p_ret1;

END
$$;


