--
-- TOC entry 6911 (class 1255 OID 23863)
-- Name: fa_sp_party_master(character, character, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_party_master(party_cd_in_l character, party_name_in_l character, mode_in_l character) RETURNS smallint
    LANGUAGE plpgsql
    AS $$ 	
DECLARE  p_stat  SMALLINT ;
  acct_head_l  fam_def_acct.acct_head%type;
BEGIN

acct_head_l := '00000000';
p_stat := 0 ;

raise notice 'Mod code is %', mode_in_l;
IF mode_in_l = 'A' THEN
-- Insert into fam_party

    IF NOT(party_cd_in_l[1] = 'A' OR party_cd_in_l[1] = 'G' OR
           party_cd_in_l[1] = 'B' OR party_cd_in_l[1] = 'K' OR
           party_cd_in_l[1] = 'D' OR party_cd_in_l[1] = 'J' OR
           party_cd_in_l[1] = 'U' )
    THEN
        
		Raise exception 'No Rows Found' ;
    ELSE
            SELECT acct_head
            INTO   acct_head_l
            FROM   fam_def_acct
            WHERE  fam_def_acct.mod_cd = 'PMM';
            IF (acct_head_l IS NULL OR acct_head_l = '00000000')
            THEN
                Raise exception 'No Rows Found' ;
            ELSE
                    insert into fam_party (
                        party_cd, party_name, cont_per, pan_no, bank_cd,
                        bank_acct_no, build_name, str_no_name, city_name,
                        district, state_name, pin_cd, tel_no, tlx_no, fax_no,
                        rem_txt, stat, led_cd, acct_head, res_cd)
                    values (
                        party_cd_in_l, party_name_in_l, NULL,
                        NULL, NULL, NULL,
                        NULL, NULL, NULL,
                        NULL, NULL, NULL,
                        NULL, NULL, NULL,
                        NULL, 'a', '01',
                        acct_head_l, NULL);
             END IF;
    END IF;
END IF ;
IF mode_in_l = 'M' THEN
-- Update fam_party
raise notice 'Mode is %',mode_in_l ;
    UPDATE fam_party
    SET party_name = party_name_in_l
    WHERE fam_party.party_cd = party_cd_in_l;
raise notice '2 Mode is %',mode_in_l ;	
END IF ;
IF mode_in_l = 'D' THEN
 -- -- Update fam_party as cancelled
     UPDATE fam_party
     SET stat = 'C',
         res_cd = 'RFPD'
     WHERE fam_party.party_cd = party_cd_in_l
     AND   fam_party.stat = 'a';
END IF ;	 


RETURN p_stat;

END;
$$;


ALTER FUNCTION public.fa_sp_party_master(party_cd_in_l character, party_name_in_l character, mode_in_l character) OWNER TO postgres;

