v_rowcount := p_status ;
-- p_status := dbinfo("sqlca.sqlerrd2");Raise notice 'output p_stat led_cd_out_1 %,%',  p_stat,led_cd_out_l;Raise notice 'output p_stat led_cd_out_1 %,%',  p_stat,led_cd_out_l;

IF p_status <> 0 THEN                                     
        -- RETURN  p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l, dep_bank_cd_out_l,alloc_dt_out_l;
	 Raise notice ' Return 2';
	RETURN NEXT ;
	Raise notice ' Return 2';
END IF;

-- Get Ledger Code from fam_ledger using STATION environment variable
-- which is passed a an I/P parameter
--perform  fa_sp_ledger002(stn_cd_in_l, 0 ,'' )  ;
select * into p_status, led_cd_out_l  from fa_sp_ledger002(stn_cd_in_l, 0 ,'' ) ;  
---from fa_sp_gen_oldnxt(p_led_cd, 'JV',0,0 );
Raise notice 'output led_cd_out_l  %',  led_cd_out_l; 
IF p_status <> 0 THEN                                     
       --- RETURN  p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l,dep_bank_cd_out_l,alloc_dt_out_l;
	  Raise notice ' Return 3';
	  return next ;
	  Raise notice ' Return 3';
END IF;

Raise notice 'output led_cd_out_l  %',  led_cd_out_l;

-- Let Cost Centre be for Comm & Coaching

SELECT comm_cc_cd
INTO   cc_cd_l
FROM   fap_fasys
WHERE  1=1;

IF (mr_amt_in_l > 0) THEN
-- Creation of a MR begins here.
-- Form id_desc

IF gc_flag_in_l = 'C'
THEN
        id_desc_l := 'Earnings due to Coaching';
ELSE
        id_desc_l := 'Earnings due to Goods';
END IF;

Raise notice ' id_desc_l,stn_cd_in_l %,%',id_desc_l , stn_cd_in_l;
-- Generate MR No. at Station
-- select  fa_sp_gennxt002(stn_cd_in_l,'MR',p_status , led_cd_out_l)  ; 
 select * into p_status , mr_no_out_l from fa_sp_gennxt002(led_cd_out_l,'MR',0 , 0 );
 
 
 
 Raise notice 'fa_sp_gennxt002 output  %,%', p_status, mr_no_out_l ;
 
 
--- RETURNING p_status,mr_no_out_l;

IF p_status <> 0 THEN
       ---  RETURN  p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l, dep_bank_cd_out_l,alloc_dt_out_l;
		Raise notice ' Return 4';
		RETURN NEXT ;	
		Raise notice ' Return 4';
END IF;

-- Generate next TXN No. at Station

       -- CALL fa_sp_gennxt003(led_cd_out_l,'TXN') RETURNING p_status,txn_no_out_l;
		--  perform fa_sp_gennxt003(led_cd_out_l,'TXN') ;
Raise notice 'Before calling fa_sp_gennxt003 output  %,%', p_status, led_cd_out_l ;		
		
		 select * into p_status,txn_no_out_l from fa_sp_gennxt003 (led_cd_out_l,'TXN') ;
		 
		  Raise notice 'fa_sp_gennxt003 output  %,%', p_status, txn_no_out_l ; 
        IF p_status <> 0 THEN
               -- RETURN  p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l, dep_bank_cd_out_l,alloc_dt_out_l;
            Raise notice ' Return 5';
			RETURN NEXT ;
				  
				  Raise notice ' Return 5';
		END IF;

-- Get Depositing Bank from famk_dep_stnbank

SELECT  bank_cd 
INTO    dep_bank_cd_out_l
FROM    famk_dep_stnbank
where  stn_cd = stn_cd_in_l;

Get diagnostics v_rowcount = row_count;
--v_rowcount := p_status ;

select count(*) into li_bank_cnt from famk_dep_stnbank
where  stn_cd = stn_cd_in_l; 

--- p_status := dbinfo("sqlca.sqlerrd2");
IF li_bank_cnt <> 1 THEN
       -- RETURN  p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l,dep_bank_cd_out_l,alloc_dt_out_l;
				Raise notice ' Return 6';
				RETURN  NEXT ;
				Raise notice ' Return 6';
END IF; 

-- Step 1 of 5 for MR 

INSERT INTO fat_mrr (   mr_no,mr_dt,id_desc,party_name,pay_mode,
                        paid_amt,ovr_paid_amt,reg_id,reg_dt,
                        auth_id,auth_dt,rcpt_no,txn_no,rem_flag,
                        stat,acct_head,
                        bank_cd,led_cd,mr_cd,gc_flag,party_cd )
VALUES
                    (   mr_no_out_l,alloc_dt_out_l::date,id_desc_l,party_name_in_l,
                        pay_mode_in_l,
                        mr_amt_in_l,0,login_id_in_l,alloc_dt_out_l::date,
                        login_id_in_l,alloc_dt_out_l,0,txn_no_out_l,'N',
                        'A',cr_acct_head_in_l,
                        dep_bank_cd_out_l,led_cd_out_l,
                        'M99',gc_flag_in_l,'' );

--- p_status := dbinfo("sqlca.sqlerrd2");
Get diagnostics v_rowcount = row_count;
li_cnt_mr := v_rowcount ;
Raise notice 'Output 7... v_rowcount %', v_rowcount ;


p_status := v_rowcount ;


Raise notice 'Output 7... p_status %', p_status ;
IF p_status <= 0 THEN
        ---RETURN  p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l, dep_bank_cd_out_l,alloc_dt_out_l;
		Raise notice ' Return 7';
		RETURN NEXT ;		
		Raise notice ' Return 7';		
ELSE
        p_status := 0;
END IF;

-- In case of Cheque/DD receipt, there would be one MR for each,
-- in which case a record in fat_mrch needs to be inserted
-- Step 2 of 5 for MR

IF pay_mode_in_l != 'CH' THEN
      
        INSERT INTO FAT_MRCH (  chq_dd_no,bank_name,
                                bank_brch,chq_dd_dt,
                                out_flag,led_cd,
                                mr_no )
        VALUES
                             (  chq_dd_no_in_l,bank_name_in_l,
                                bank_brch_in_l,chq_dd_dt_in_l::date,
                                'Y',led_cd_out_l,
                                mr_no_out_l );

Get diagnostics v_rowcount = row_count;
v_rowcount := p_status ;

      --  p_status := dbinfo("sqlca.sqlerrd2");
        IF p_status <> 1 THEN
                --- RETURN  p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l,dep_bank_cd_out_l,alloc_dt_out_l;
			Raise notice ' Return 8';
			RETURN NEXT ;
			Raise notice ' Return 8';
        ELSE
                p_status := 0;
        END IF;
END IF;

-- Step 3 of 5 for MR

IF pay_mode_in_l != 'CH'
THEN
-- Select Bank Remittance A/c if payment mode is other than Cash
        dr_acct_head_l := cit_acct_head_l;
ELSE
-- Select Cash-In-Hand A/c for Cash payment mode
        dr_acct_head_l := cash_acct_head_l;
END IF;

-- Create a record in faa_alloc for Debiting Cash/Bank Remittance A/c
-- Step 4 of 5 for MR
p_status := fa_sp_alloc002(  led_cd_out_l,txn_no_out_l,cc_cd_l,
                                dr_acct_head_l,cr_acct_head_in_l,
                                mr_amt_in_l,alloc_dt_out_l,mod_cd_l,
                                mr_no_out_l );
IF p_status <> 0 THEN
       -- RETURN  p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l, dep_bank_cd_out_l,alloc_dt_out_l;	
		Raise notice ' Return 9';
		RETURN NEXT ;	
		Raise notice ' Return 9';
END IF ;

-- Give Narration for the MR
-- Step 5 of 5 for MR
p_status := fa_sp_narrat(led_cd_out_l,txn_no_out_l,
                            'Being Receipt For TA',mr_no_out_l::text);
							
IF p_status <> 0 THEN
       -- RETURN  p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l, dep_bank_cd_out_l,alloc_dt_out_l;
		Raise notice ' Return 10';
		RETURN NEXT ;	
		Raise notice ' Return 10';
END IF ;
-- Creation of MR ends here

ELSE
-- ELSE above is for condition (mr_amt_in_l > 0)
-- Reduce credit of TA by MR Amt passed
mr_amt_in_l := -1 * mr_amt_in_l;
-- Put entry in faw_oth_tran and Dr cr A/c passed here, TA 
-- & Cr Cash.
-- CALL fa_sp_stn_oth0001( stn_cd_in_l,cc_cd_l,cr_acct_head_in_l,mr_amt_in_l,alloc_dt_out_l,0,gc_flag_in_l,mod_cd_l)RETURNING p_status, led_cd_out_l, txn_no_out_l; 
-- perform fa_sp_stn_oth0001( stn_cd_in_l,cc_cd_l,cr_acct_head_in_l,mr_amt_in_l,alloc_dt_out_l,0,gc_flag_in_l,mod_cd_l) ;
   select * into p_status, led_cd_out_l, txn_no_out_l from  fa_sp_stn_oth0001(stn_cd_in_l,cc_cd_l,cr_acct_head_in_l,mr_amt_in_l,alloc_dt_out_l,0,gc_flag_in_l,mod_cd_l, 0, '', 0) ;
IF p_status <> 0 THEN
       --  RETURN  p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l, dep_bank_cd_out_l,alloc_dt_out_l;
		RETURN NEXT ;	
		Raise notice ' Return 11';
END IF ;

END IF; 
-- END IF above is for condition (mr_amt_in_l > 0)

-- Now in the modified one returns status (0 succ.),ledger code for station,
-- MR No.,Txn No.,Dep. Bank Code for that Station
-- This current procedure will be run only at station. Using its return values
-- a call to a SP in the central database can be given to get the station data
-- in the central database.

--- RETURN p_status,led_cd_out_l,mr_no_out_l,txn_no_out_l,dep_bank_cd_out_l,alloc_dt_out_l;
RETURN NEXT ;
Raise notice ' Return 12';
exception when others then 
    raise notice 'EXCEPTION % %',sqlstate, SQLERRM;
	

END ;
$$;


ALTER FUNCTION public.fa_sp_stn_ta0001(stn_cd_in_l text, party_name_in_l text, pay_mode_in_l text, mr_amt_in_l numeric, cr_acct_head_in_l text, gc_flag_in_l text, bank_name_in_l text, bank_brch_in_l text, chq_dd_no_in_l text, chq_dd_dt_in_l date, login_id_in_l text) OWNER TO postgres;

--
-- TOC entry 6915 (class 1255 OID 23868)
-- Name: fa_sp_sub_eb(character, integer, date, character, numeric, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_sub_eb(mod_cd_in_l character, au6_no_in_l integer, reg_dt_in_l date, party_name_in_l character, tot_amt_in_l numeric, reg_id_in_l character) RETURNS integer
    LANGUAGE plpgsql
    AS $$


DECLARE p_status INT;
 led_cd_l  fam_ledger.led_cd%type;
 sub_au6_no_l  fat_ebsub.sub_au6_no%type;
 bill_mth_yr_l  fat_ebhead.bill_mth_yr%type;
 txn_no_l  fat_ebsub.txn_no%type;
 txn_cert_no_l  fat_ebsub.txn_cert_no%type;
 sub_desc_l  fat_ebsub.sub_desc%type;
 narrat_l CHAR(80);
 cc_cd_l  fat_alloc.cc_cd%type;
 dr_acct_head_l  fam_acct.acct_head%type;
 cr_acct_head_l  fam_acct.acct_head%type;
 v_rowcount int ;
BEGIN

-- WITH RESUME;
/*
SET DEBUG FILE TO "/tmp/fa_sp_sub_eb.dbg";
TRACE ON;
*/
-- Initialise
p_status := 0;
 -- Validate type of Bill
IF mod_cd_in_l NOT IN ('EBS','ED0','ED1')
THEN

        RETURN 100;
END IF;
-- Get ledger code for Central Office

---CALL fa_sp_ledger002('BLP') RETURNING p_status, led_cd_l;
perform fa_sp_ledger002('BLP',p_status, led_cd_l );

IF p_status != 0
THEN
        RETURN p_status;
END IF;

--CALL  fa_sp_gennxt002(led_cd_l, 'ESS') RETURNING p_status, sub_au6_no_l;
perform fa_sp_gennxt002(led_cd_l, 'ESS',p_status, sub_au6_no_l );

IF p_status <> 0 THEN
        RETURN p_status;
END IF;

--- CALL fa_sp_gennxt002(led_cd_l, 'TXN') RETURNING p_status, txn_no_l;

perform fa_sp_gennxt002(led_cd_l, 'TXN',p_status, txn_no_l ) ;


IF p_status <> 0 THEN
        RETURN p_status;
END IF;

-- CALL fa_sp_gennxt002(led_cd_l, 'TXN') RETURNING p_status, txn_cert_no_l;
perform fa_sp_gennxt002(led_cd_l, 'TXN', p_status, txn_cert_no_l) ;

IF p_status <> 0 THEN
        RETURN p_status;
END IF;


SELECT a.bill_mth_yr
INTO   bill_mth_yr_l
FROM   fat_ebhead a
WHERE  a.led_cd = led_cd_l
AND    a.au6_no = au6_no_in_l;
-- p_status := dbinfo("SQLCA.SQLERRD2");
Get diagnostics v_rowcount = row_count;
 p_status := v_rowcount;



IF p_status <> 1 THEN
   p_status := 100 ; 
        RETURN p_status ;
END IF;

IF mod_cd_in_l = 'EBS'
THEN
        sub_desc_l := 'Subsidiary Salary Bill for ' || bill_mth_yr_l;
END IF;
IF mod_cd_in_l = 'ED0'
THEN
        sub_desc_l := 'Subsidiary Deduction Bill for ' || bill_mth_yr_l;
END IF;
IF mod_cd_in_l = 'ED1'
THEN
        sub_desc_l := 'Subsidiary IT Deduction Bill for ' || bill_mth_yr_l;
END IF;


INSERT INTO fat_ebsub
(sub_au6_no, sub_desc, sbank_cd, rbank_cd, party_name, tot_amt, cert_amt,
admit_amt, reg_dt, due_dt, cert_dt, veri_dt, pass_dt, reg_id, cert_id,
veri_id, pass_id, last_ser_no, paid_amt, txn_no, txn_cert_no, txn_ver_no,
txn_pass_no, rem_flag, rem_cert_flag, rem_ver_flag, rem_pass_flag, stat,
mod_cd, au6_no, led_cd)
VALUES (sub_au6_no_l, sub_desc_l, null, null, party_name_in_l, tot_amt_in_l,
tot_amt_in_l, 0.0, reg_dt_in_l, reg_dt_in_l, reg_dt_in_l, null, null,
reg_id_in_l, reg_id_in_l, null, null, 0, 0.0, txn_no_l, txn_cert_no_l, 0, 0,
'N','N', 'N', 'N', 't', mod_cd_in_l, au6_no_in_l, led_cd_l);
-- p_status := dbinfo("SQLCA.SQLERRD2");
Get diagnostics v_rowcount = row_count;
p_status := v_rowcount ;
IF p_status <= 0
THEN
        RETURN p_status;
ELSE
        p_status := 0;
END IF;

narrat_l := 'Being ' || sub_desc_l;
-- CALL fa_sp_narrat(led_cd_l, txn_no_l, narrat_l, ' ') RETURNING p_status;
p_status:= fa_sp_narrat(led_cd_l, txn_no_l, narrat_l, ' ') ;
IF p_status != 0
THEN
        RETURN p_status;
END IF;


SELECT a.cc_cd
INTO   cc_cd_l
FROM   fap_fasys a
WHERE  1=1;


SELECT a.acct_head
INTO   dr_acct_head_l
FROM   fam_def_acct a
WHERE  a.mod_cd = 'PSA';

--p_status := dbinfo("SQLCA.SQLERRD2");
Get diagnostics v_rowcount = row_count;
   p_status := v_rowcount ;

IF p_status <> 1 THEN
    p_status := 100 ;
        RETURN p_status ;
END IF;


SELECT a.acct_head
INTO   cr_acct_head_l
FROM   fam_def_acct a
WHERE  a.mod_cd = 'TRS';
--p_status := dbinfo("SQLCA.SQLERRD2");

Get diagnostics v_rowcount = row_count;
   p_status := v_rowcount ;

IF p_status <> 1 THEN
   p_status := 100 ;
   --     RETURN 100;
   RETURN p_Status ;
END IF;

-- Pass Allocations
p_status := fa_sp_alloc102(  led_cd_l,txn_no_l,cc_cd_l,
                                dr_acct_head_l,cr_acct_head_l,
                                tot_amt_in_l,reg_dt_in_l);
IF p_status != 0 THEN
        RETURN p_status;
END IF;

RETURN p_status;

END;
$$;


ALTER FUNCTION public.fa_sp_sub_eb(mod_cd_in_l character, au6_no_in_l integer, reg_dt_in_l date, party_name_in_l character, tot_amt_in_l numeric, reg_id_in_l character) OWNER TO postgres;

--
-- TOC entry 6795 (class 1255 OID 23869)
-- Name: fa_sp_upd_remarks(character, integer, character, character, character, character); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.fa_sp_upd_remarks(IN p_led_cd character, IN p_txn_no integer, IN p_pre_stat character, IN p_post_stat character, IN p_pre_reg_id character, IN p_post_reg_id character)
    LANGUAGE plpgsql
    AS $$

                
          
DECLARE  p_status  smallint ;
   p_cycle SMALLINT;
   p_sr_no SMALLINT;
  p_string CHAR(80);
-- introduced the var:uid for jrap-audit trail in jan 2005 --
 uid char(8);
 
begin

-- call getcurrentuser() returning uid;
 uid := '';
 
/*
SET DEBUG FILE TO "/tmp/rem_upd.dbg";
TRACE "Date : "||CURRENT;
TRACE uid;
TRACE ON;
*/

SELECT max(cycle_no)
INTO p_cycle
FROM fat_remark
WHERE txn_no = p_txn_no
AND   led_cd = p_led_cd;

SELECT max(sr_no)
INTO p_sr_no
FROM fat_remark
WHERE txn_no = p_txn_no
AND led_cd = p_led_cd
AND cycle_no = p_cycle;

IF p_post_stat = 'R' AND p_pre_stat = 'R' THEN
        IF p_pre_reg_id <> p_post_reg_id THEN
                p_cycle := p_cycle + 1;
                p_sr_no := 1;
        ELSE
                p_sr_no := p_sr_no + 1;
        END IF;
ELSE
        p_cycle := p_cycle + 1;
        p_sr_no := 1;
END IF;

--
--Initialisation to take care of old data . 2 b removed later on
IF p_cycle IS NULL THEN
   p_cycle := 1;
END IF;

IF p_sr_no IS NULL THEN
   p_sr_no := 1;
END IF;

IF p_post_stat = 'R' THEN
        p_string := 'System Remark : Modified by '||uid|| ' On '||CURRENT_TIMESTAMP;
END IF ;		
IF p_post_stat = 't' THEN
        p_string := 'System Remark :  Certified OK by '|| uid|| ' On '|| CURRENT_TIMESTAMP;
END IF ;		
IF p_post_stat = 'n' THEN
        p_string := 'System Remark : Certified Not OK by '|| uid|| ' On '||CURRENT_TIMESTAMP;
END IF 	;	
IF p_post_stat = 'V' THEN
        p_string := 'System Remark : Verified OK by '|| uid|| ' On '|| CURRENT_TIMESTAMP;
END IF ;		
IF p_post_stat = 'i' THEN
        p_string := 'System Remark : Verified Not OK by '|| uid|| ' On '|| CURRENT_TIMESTAMP;
END IF;
-- introduced the var:uid for jrap-audit trail in jan 2005 --

INSERT INTO fat_remark(led_cd,txn_no,cycle_no,sr_no,rem_txt,
        user_id,rem_date,stage_flag)
VALUES (p_led_cd,p_txn_no,p_cycle,p_sr_no,p_string,
        uid,CURRENT_TIMESTAMP,p_post_stat);
        
-- p_status := DBINFO("SQLCA.SQLERRD2");

--TRACE OFF;

END ;
$$;


ALTER PROCEDURE public.fa_sp_upd_remarks(IN p_led_cd character, IN p_txn_no integer, IN p_pre_stat character, IN p_post_stat character, IN p_pre_reg_id character, IN p_post_reg_id character) OWNER TO postgres;

--
-- TOC entry 6917 (class 1255 OID 23870)
-- Name: fa_sp_updmrr(character, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fa_sp_updmrr(p_led_cd character, p_mr_no integer, p_pis_no integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

-------------------------------------------------------------
-- This procedure updates the fat_mrr table to put the 
-- proper PIS no and status.
-- This procedure will be called from stations for every MR
-- for the given PIS.
--
-------------------------------------------------------------
declare  p_stat          int ;
  p_no_of_rows    int ;
  v_rowcount  int ;  
begin

p_stat := 0 ;



/*
set debug file to "/tmp/fa_sp_updmrr.dbg" with append;
trace on;

trace "PIS no is " || p_pis_no;
trace "MR no is "  || p_mr_no;
trace "Led Cd is " || p_led_cd;
*/

UPDATE fat_mrr
SET    pis_no = p_pis_no,
                 stat   = 'B'
WHERE  mr_no = p_mr_no
AND    led_cd = p_led_cd;

-- p_no_of_rows := dbinfo("SQLCA.SQLERRD2") ;

Get diagnostics v_rowcount = row_count;
p_no_of_rows  := v_rowcount  ;

/*
trace "No of rows Updated " || p_no_of_rows;
*/
IF p_no_of_rows <> 1 THEN
       --- raise exception p_stat;
       p_stat := p_no_of_rows ;  
        
        Raise exception 'No Rows Found %', p_stat;

END IF;

return p_stat ;

end ;
$$;


ALTER FUNCTION public.fa_sp_updmrr(p_led_cd character, p_mr_no integer, p_pis_no integer) OWNER TO postgres;

--
-- TOC entry 6918 (class 1255 OID 23871)
