--

CREATE FUNCTION public.fak_sp_aj01(gd_jv_amt numeric, gc_reg_id character, gdt_post_dt date, gc_narrat1 character, gc_narrat2 character) RETURNS TABLE(li_status integer, li_jv_no integer, li_txn_no integer)
    LANGUAGE plpgsql
    AS $$
DECLARE  lc_narrat1        fat_narrat.narrat%type ;
  lc_narrat2        fat_narrat.narrat%type ;
  li_led_cd         fam_ledger.led_cd%type ;
  lc_stat           fat_jvhd.stat%type ;
  --li_status       INT ;
  li_no_of_rows   INT ;
  --li_jv_no          fat_jvhd.jv_no%type ;
  lc_jv_type        fat_jvhd.jv_type%type ;
  ldt_jv_dt         fat_jvhd.jv_dt%type ;
  ld_jv_amt         fat_jvhd.jv_amt%type ;
  lc_reg_id         fat_jvhd.reg_id%type ;
  lc_auth_id        fat_jvhd.auth_id%type ;
  ldt_reg_dt        fat_jvhd.reg_dt%type ;
  ldt_auth_dt       fat_jvhd.auth_dt%type ;
  ldt_post_dt       fat_jvhd.post_dt%type ;
  lc_doc_type       fat_jvhd.doc_type%type ;
  li_fa_doc_no      fat_jvhd.fa_doc_no%type ;
  lc_ast_gen_flag   fat_jvhd.asset_gen_flag%type ;
  --li_txn_no         fat_jvhd.txn_no%type ;
  lc_rem_flag       fat_jvhd.rem_flag%type ;
  li_loc_cd         fat_jvhd.loc_cd%type ;
  v_rowcount 		int;
BEGIN

 -- SQLINES LICENSE FOR EVALUATION USE ONLY
 --with resume ;
/*
set debug file to "/tmp/fak_sp_aj01.dbg";
trace on ;
*/
li_status := 0 ;
li_no_of_rows := 0 ;

--perform fa_sp_ledger002("BLP", li_status,li_led_cd);
select * into li_status, li_led_cd from fa_sp_ledger002('BLP', 0, '' );

IF li_status <> 0 THEN
