--
-- TOC entry 6919 (class 1255 OID 23872)
-- Name: fak_sp_al01(character, text, integer, integer, text, numeric, date, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fak_sp_al01(gc_dr_cr_flag character, gi_led_cd text, gi_txn_no integer, gi_cc_cd integer, gc_acct_head text, gd_alloc_amt numeric, gdt_alloc_dt date, gc_mod_cd text, gi_au6_no integer, gi_sr_no integer) RETURNS TABLE(li_sr_no integer, li_stat integer)
    LANGUAGE plpgsql
    AS $$

  DECLARE  
  --li_sr_no faa_alloc.sr_no%type ;
   --li_stat  int ;
   li_no_of_rows  int ;
   v_rowcount INT;
   
BEGIN

 /*
  set debug file to "/tmp/fak_sp_al01.dbg";
  trace on;
*/

  IF gi_txn_no = 0 THEN
        li_stat := 100;
		
Raise Notice '%',li_stat;
Raise Notice '%',li_sr_no;
		
		
       return next ;

  END IF;

  li_stat := 0 ;
  li_no_of_rows := 0 ;

  IF (gi_sr_no is null) THEN
     gi_sr_no := 0 ;
  END IF;

  li_sr_no := gi_sr_no + 1 ;
Raise Notice '%',li_sr_no;
  -- SQLINES LICENSE FOR EVALUATION USE ONLY
  INSERT INTO faa_alloc
   (txn_no, sr_no, txn_dt, au6_no, alloc_dt, alloc_amt, dr_cr_flag,
    acct_head, cc_cd, mod_cd, led_cd)
    VALUES
   (gi_txn_no, li_sr_no, gdt_alloc_dt, gi_au6_no, gdt_alloc_dt, gd_alloc_amt,
    gc_dr_cr_flag, gc_acct_head, gi_cc_cd, gc_mod_cd, gi_led_cd)
        ;

  -- SQLINES DEMO ***  li_no_of_rows contains rowid of last insert.
  
Get diagnostics v_rowcount = row_count;
        li_no_of_rows := v_rowcount ;

Raise Notice '%',li_no_of_rows;

  IF (li_stat = 0 ) and (li_no_of_rows <= 0) THEN
        li_stat := 100 ;
        RETURN next ;
  ELSE
        li_stat := 0;
  END IF;

  -- SQLINES DEMO ***  balance
  IF gc_dr_cr_flag = 'C' THEN
    gd_alloc_amt  := gd_alloc_amt * -1;
  END IF;

  UPDATE  fam_acct_onbal
      SET       online_bal = online_bal + 
                gd_alloc_amt
        WHERE   led_cd = gi_led_cd AND
                acct_head = gc_acct_head;

 raise Notice '%',gi_led_cd;
 raise Notice '%',gc_acct_head ;
 raise Notice '%',gd_alloc_amt;

Get diagnostics v_rowcount = row_count;
        li_no_of_rows := v_rowcount ;

raise Notice '%',li_no_of_rows;

  IF li_no_of_rows <= 0 THEN
      -- SQLINES LICENSE FOR EVALUATION USE ONLY
      INSERT into fam_acct_onbal
              (led_cd,   acct_head,    online_bal)
        VALUES(gi_led_cd,gc_acct_head, gd_alloc_amt);
  END IF;

        RETURN next ;
Raise warning '%',li_stat;
Raise warning '%',li_sr_no;

  END ;
$$;


