ALTER FUNCTION public.fak_sp_tajv01(gd_jv_amt numeric, gc_reg_id text, gdt_post_dt date, gc_narrat1 text, gc_narrat2 text, gi_jvyr integer) OWNER TO postgres;

--
-- TOC entry 7063 (class 1255 OID 1083772)
-- Name: get_summary_report_for_manual_entries(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: itstaff
--

CREATE FUNCTION public.get_summary_report_for_manual_entries(start_year text, end_year text, pf_flg_filter text, emp_no_filter text, emp_division_cd_filter text) RETURNS TABLE(empno text, pfyearmonth date, supcpf numeric, supvpf numeric, supapf numeric, suplpf numeric, exlpf numeric, loanvpf numeric, loancpf numeric, sttcpf numeric, sttvpf numeric, sttkpf numeric, stticpf numeric, sttivpf numeric, sttikpf numeric, paycpf numeric, payvpf numeric, payapf numeric, paylpf numeric, empdivisioncd text, empshortname text, empdesigcd text, stncde text, pfflg text)
    LANGUAGE plpgsql
    AS $$

BEGIN

    RETURN QUERY
    WITH emp_months AS (
        SELECT 
            base.emp_no, 
            TO_DATE(pf_month || '-01', 'YYYY-MM-DD') AS pf_yearmonth
        FROM (
            SELECT pfyr.emp_no
            FROM pmtk_pfyr pfyr
            JOIN pmm_employee c ON pfyr.emp_no = c.emp_no
            JOIN pmm_city a ON c.stn_cde = a.city_cd
            WHERE TO_CHAR(pfyr.pf_yr_frm, 'YYYY') = start_year 
              AND TO_CHAR(pfyr.pf_yr_to, 'YYYY') = end_year
        ) base
        CROSS JOIN LATERAL (
            SELECT TO_CHAR(DATE_TRUNC('month', d), 'YYYY-MM') AS pf_month
            FROM generate_series(
                TO_DATE(start_year || '-04-01', 'YYYY-MM-DD'),
                TO_DATE(end_year || '-03-01', 'YYYY-MM-DD'),
                interval '1 month'
            ) d
        ) month_list
    ),
    settlement AS (
        SELECT emp_no, stt_yearmonth,
               SUM(cpf_paid) AS stt_cpf,
               SUM(vpf_paid) AS stt_vpf,
               SUM(kpf_paid) AS stt_kpf,
               SUM(stt_icpf) AS stt_icpf,
               SUM(stt_ivpf) AS stt_ivpf,
               SUM(stt_ikpf) AS stt_ikpf
        FROM pmmk_pfsetl
        GROUP BY emp_no, stt_yearmonth
    ),
    modified_pfmnt AS (
        SELECT emp_no, pf_yearmonth, pay_cpf, pay_vpf, pay_apf, pay_lpf
        FROM pmtk_pfmnt
        WHERE CAST(emp_no AS TEXT) || TO_CHAR(pf_yearmonth, 'YYYY-MM') IN (
            SELECT CAST(emp_no AS TEXT) || TO_CHAR(pf_yearmonth, 'YYYY-MM')
            FROM pmhk_pfmnt
            WHERE mod_del_flag = 'M'
        )
    )
    SELECT 
        --em.emp_no as empNo,
		CAST(em.emp_no AS TEXT) AS empNo,
        em.pf_yearmonth as pfYearmonth,
        coalesce(b.sup_cpf,0.00) as supCpf,
        coalesce(b.sup_vpf,0.00) as supVpf,
        coalesce(b.sup_apf,0.00) as supApf,
        coalesce(b.sup_lpf,0.00) as supLpf,
        coalesce(b.exlpf,0.00) as exLpf,
        coalesce(l.loan_vpf,0.00) as loanVpf,
        coalesce(l.loan_cpf,0.00) as loanCpf,
        coalesce(s.stt_cpf,0.00) as sttCpf,
        coalesce(s.stt_vpf,0.00) as sttVpf,
        coalesce(s.stt_kpf,0.00) as sttKpf,
        coalesce(s.stt_icpf,0.00) as sttIcpf,
        coalesce(s.stt_ivpf,0.00) as sttIvpf,
        coalesce(s.stt_ikpf,0.00) as sttIkpf,
       coalesce( m.pay_cpf,0.00) as payCpf,
        coalesce(m.pay_vpf,0.00) as payVpf,
        coalesce(m.pay_apf,0.00) as payApf,
        coalesce(m.pay_lpf,0.00) as payLpf,
       -- c.emp_division_cd,
       -- e.emp_short_name,
       -- e.emp_desig_cd,
       -- e.stn_cde,
       -- pf.pf_flg
	     CAST(c.emp_division_cd AS TEXT) AS empDivisionCd,
        CAST(e.emp_short_name AS TEXT) AS empShortName,
        CAST(e.emp_desig_cd AS TEXT) AS empDesigCd,
        CAST(e.stn_cde AS TEXT) AS stnCde,
        CAST(pf.pf_flg AS TEXT) AS pfFlg
    FROM emp_months em
    LEFT JOIN pmtk_pfsup b 
        ON em.emp_no = b.emp_no 
       AND TO_CHAR(em.pf_yearmonth, 'YYYY-MM') = TO_CHAR(b.pf_yearmonth, 'YYYY-MM')
    LEFT JOIN pmtk_pfloan l 
        ON em.emp_no = l.emp_no 
       AND TO_CHAR(em.pf_yearmonth, 'YYYY-MM') = TO_CHAR(l.pf_yearmonth, 'YYYY-MM')
    LEFT JOIN settlement s
        ON em.emp_no = s.emp_no 
       AND TO_CHAR(em.pf_yearmonth, 'YYYY-MM') = TO_CHAR(s.stt_yearmonth, 'YYYY-MM')
    LEFT JOIN modified_pfmnt m
        ON em.emp_no = m.emp_no 
       AND TO_CHAR(em.pf_yearmonth, 'YYYY-MM') = TO_CHAR(m.pf_yearmonth, 'YYYY-MM')
    JOIN pmm_employee e ON em.emp_no = e.emp_no
    JOIN pmm_city c ON e.stn_cde = c.city_cd
    JOIN pmtk_pfyr pf 
        ON em.emp_no = pf.emp_no 
       AND TO_CHAR(pf.pf_yr_frm, 'YYYY') = start_year
       AND TO_CHAR(pf.pf_yr_to, 'YYYY') = end_year
	   AND (pf_flg_filter = '0' OR pf.pf_flg = CAST(pf_flg_filter AS smallint))
    WHERE 
        (b.sup_cpf IS NOT NULL OR b.sup_vpf IS NOT NULL OR b.sup_apf IS NOT NULL OR b.sup_lpf IS NOT NULL OR b.exlpf IS NOT NULL OR
         m.pay_cpf IS NOT NULL OR m.pay_vpf IS NOT NULL OR m.pay_apf IS NOT NULL OR m.pay_lpf IS NOT NULL OR
         l.loan_cpf IS NOT NULL OR l.loan_vpf IS NOT NULL OR
         s.stt_cpf IS NOT NULL OR s.stt_vpf IS NOT NULL OR s.stt_kpf IS NOT NULL OR 
         s.stt_icpf IS NOT NULL OR s.stt_ivpf IS NOT NULL OR s.stt_ikpf IS NOT NULL)
		AND (emp_no_filter = 'All' OR CAST(em.emp_no AS TEXT) = emp_no_filter)
        AND (emp_division_cd_filter = 'All' OR c.emp_division_cd = emp_division_cd_filter)
    ORDER BY c.emp_division_cd, pf.pf_flg,em.pf_yearmonth, em.emp_no;

END;
$$;


ALTER FUNCTION public.get_summary_report_for_manual_entries(start_year text, end_year text, pf_flg_filter text, emp_no_filter text, emp_division_cd_filter text) OWNER TO itstaff;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
