-- Name: pmm_employee; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pmm_employee (
    emp_no integer NOT NULL,
    emp_surname character(15),
    emp_firstname character(15) NOT NULL,
    emp_midname character(15),
    emp_address1 character varying(80) NOT NULL,
    emp_address2 character(40),
    emp_address3 character(40),
    emp_state_cd character(3),
    emp_pincode integer,
    stn_cde character(5) NOT NULL,
    emp_rep_stn_cd character(5) NOT NULL,
    emp_birth_dt date NOT NULL,
    emp_sex character(1) NOT NULL,
    emp_marital_stat character(1) NOT NULL,
    led_cd character(2),
    emp_short_name character(30) NOT NULL,
    host_name character(15),
    emp_origin_rly character(4) NOT NULL,
    emp_crew character(1) NOT NULL,
    emp_report_to character(8) NOT NULL,
    emp_fitness_stat character(1),
    emp_med_done_dt date,
    emp_med_due_dt date,
    emp_join_dt date NOT NULL,
    emp_catg_cd character(2) NOT NULL,
    emp_dept_cd smallint NOT NULL,
    emp_desig_cd character(8) NOT NULL,
    emp_curr_stat character(1) NOT NULL,
    emp_religion_cd character(1) NOT NULL,
    emp_community_cd character(3) NOT NULL,
    emp_consignee_no character(5),
    emp_loc_cd character(5) NOT NULL,
    emp_office_ph character(15),
    emp_res_ph character(15),
    emp_per_address1 character varying(80),
    emp_per_address2 character(40),
    emp_per_address3 character(40),
    emp_per_pin integer,
    emp_current_basic numeric(8,2),
    emp_seniority_no smallint,
    emp_join_letter_no character(15),
    emp_join_let_date date,
    emp_post_flg character(1),
    emp_union_flg character(1),
    emp_res_flg character(1),
    emp_father_name character(20),
    emp_bank_no character(12),
    bank_name character(5),
    pan_gir_no character(10),
    emp_provident_no character(11),
    emp_pension_amt numeric(8,2),
    emp_nationality character(15),
    emp_regular_dt date,
    emp_adhoc_dt date,
    emp_rect_cd smallint,
    emp_branch_cd character(3),
    emp_app_auth_cd character(8) NOT NULL,
    emp_classific_no character(2) NOT NULL,
    emp_unit_cd character(5) NOT NULL,
    emp_blood_grp character(3) NOT NULL,
    zonal_cd character(3) NOT NULL,
    emp_per_state character(3),
    status_org character(1),
    increment_flg character(1),
    prom_tran_flg character(1),
    safety_sen_flg character(1),
    admin_flg character(1),
    last_date date,
    user_id integer,
    "timestamp" timestamp without time zone
);


ALTER TABLE public.pmm_employee OWNER TO postgres;

