--
-- TOC entry 6910 (class 1255 OID 23881)
-- Name: gm_sf_grievance_assign_action(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gm_sf_grievance_assign_action(empno integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE  count      INT;
  cnt1      INT;
BEGIN

    -- SQLINES LICENSE FOR EVALUATION USE ONLY
    select count(*) into count from gmtk_coms_hdr a,gmtk_assign_hdr c where  a.complaint_no=c.complaint_no and 
        a.status not in ('Close','Sback','Can') and c.assign_to=empno;
         
IF count > 0 THEN        

ELSE
        -- SQLINES LICENSE FOR EVALUATION USE ONLY
        select count(*) into cnt1 from gmpk_coms_param where param_cd='GREV' 
        and param_value='admin' and trim(param_desc)=cast (empno as text);

        IF cnt1 > 0 THEN
     -- SQLINES LICENSE FOR EVALUATION USE ONLY
     select count(*) into count from gmtk_coms_hdr where
         status not in ('Close','Sback','Can','Assign','Fwd','Action') and type='GREV';
        END IF;
         
END IF;  
         
RETURN count;
END ;
$$;


ALTER FUNCTION public.gm_sf_grievance_assign_action(empno integer) OWNER TO postgres;

