--
-- TOC entry 6923 (class 1255 OID 23884)
-- Name: gm_sp_pc_01(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gm_sp_pc_01(empno integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE  rcount      INT;
DECLARE  empDesigCd  CHAR(8);
BEGIN

select emp_desig_cd into empDesigCd from  pmm_employee where emp_no=empno;


select count(*) into rcount
from gmt_insp_record_dtl
where respn_dept in (select emp_dept_cd from pmm_employee where emp_no=empno)
and insp_status  !='CLOSED'
and (respn_desig  like empDesigCd||',%'
or  respn_desig like '%,'||empDesigCd||',%'
or  respn_desig  like '%,'||empDesigCd
or  respn_desig like empDesigCd||'%');
 

RETURN rcount;
END ;
$$;


ALTER FUNCTION public.gm_sp_pc_01(empno integer) OWNER TO postgres;

