--

CREATE FUNCTION public.hm_sp_cl_01(empno integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE  r_count      INT;
BEGIN

select count(*) into r_count from hmt_cln_exam
where disposal_cd is null
and doctor_note_1 is null
and doctor_name = (select SUBSTR(emp_short_name,5,24) from pmm_employee
where emp_no=empno);

RETURN r_count;
END;

$$;


