--
-- TOC entry 6926 (class 1255 OID 23887)
-- Name: hm_sp_pq_02(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hm_sp_pq_02(empno integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE  r_count      INT;
BEGIN

select count(a.claim_id) into r_count 
from hmtk_medclm_header a, pmm_employee b
where a.claimant_emp_no=b.emp_no
and a.claim_status = 'F' 
and b.stn_cde in(select b.stn_cde from hmm_health_unit a, hmmk_health_unit_stn b 
where a.hl_unit_cd=b.hl_unit_cd 
and a.stn_cde in(select a.stn_cde from pmm_employee a, pmm_designation b 
where a.emp_desig_cd=b.emp_desig_cd 
and a.emp_curr_stat='A' 
and a.emp_dept_cd=8 
and b.executive_post='E' 
and a.emp_no =empno));

RETURN r_count;
END;
$$;


ALTER FUNCTION public.hm_sp_pq_02(empno integer) OWNER TO postgres;

--
-- TOC entry 6927 (class 1255 OID 23888)
-- Name: hm_sp_pq_03(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hm_sp_pq_03(empno integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE  r_count      INT;
BEGIN

select count(a.claim_id) into r_count 
from hmtk_medclm_header a, pmm_employee b, pmm_city c
where a.claimant_emp_no=b.emp_no 
and b.stn_cde=c.city_cd 
and a.claim_status = 'Q' 
and c.emp_division_cd in(select c.emp_division_cd from pmm_employee a, pmm_designation b, pmm_city c 
where a.emp_desig_cd=b.emp_desig_cd 
and a.stn_cde=c.city_cd 
and a.emp_curr_stat='A' 
and a.emp_dept_cd=2 
and b.executive_post='E'
and a.emp_no=empno);

RETURN r_count;
END;
$$;


ALTER FUNCTION public.hm_sp_pq_03(empno integer) OWNER TO postgres;

