BEGIN

select count(emp_no) into r_count from pmtk_iod_proc where ((record_stat in ('S') and  iod_sr_no not in (select iod_sr_no from  pmtk_iod_ext) or (record_stat in ('S') and iod_sr_no in (select iod_sr_no from  pmtk_iod_ext where ext_stat='Z')))) and trim(cast(emp_no as char(5)))||trim(cast(iod_sr_no as char(5))) not in (select trim(cast(emp_no as char(5)))||trim(cast(iod_sr_no as char(5))) from pmtk_iod_fitness) and med_official=empno ;

