--
-- TOC entry 6929 (class 1255 OID 23890)
-- Name: months_between(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.months_between(t_start date, t_end date) RETURNS integer
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
select ((extract('years' from $2)::int -  extract('years' from $1)::int) * 12) 
    - extract('month' from $1)::int + extract('month' from $2)::int
$_$;


ALTER FUNCTION public.months_between(t_start date, t_end date) OWNER TO postgres;

