CREATE FUNCTION public.pm_iprs_imov_1(empno integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE rcount INT;
BEGIN



 select count( *) into rcount from
 (select distinct a.txn_no from pmtk_iprs_imov a
 where a.status_flag  in ('AR','AM','BF') and a.fwd_auth = CAST(empno AS VARCHAR(10)) ) as iprsCnt;


 return rcount;

END
$$;


