 where a.status_flag  in ('DC') and a.dis_app_auth=CAST(empno AS VARCHAR(10))  and c.emp_desig_cd= b.emp_desig_cd and a.emp_no=b.emp_no and c.executive_post='E' )) as iprsCount;

Raise notice 'output rcount  %',  rcount;

return next;
END
$$;


