    AS $$


BEGIN

 select count( *) into rcount from
  ((select distinct a.txn_no from pmtk_iprs_shares a ,pmm_employee b, pmm_designation c
where a.status_flag  in ('AE') and a.app_auth=CAST(empno AS VARCHAR(10))  and c.emp_desig_cd= b.emp_desig_cd and a.emp_no=b.emp_no and c.executive_post='N' )
union
(select distinct a.txn_no from pmtk_iprs_shares a ,pmm_employee b, pmm_designation c
where a.status_flag  in ('AC') and a.app_auth=CAST(empno AS VARCHAR(10))  and c.emp_desig_cd= b.emp_desig_cd and a.emp_no=b.emp_no and c.executive_post='E' )
union
(select distinct a.txn_no from pmtk_iprs_liquid a ,pmm_employee b, pmm_designation c
where a.status_flag  in ('AE') and a.app_auth=CAST(empno AS VARCHAR(10))  and c.emp_desig_cd= b.emp_desig_cd and a.emp_no=b.emp_no and c.executive_post='N' )
union
(select distinct a.txn_no from pmtk_iprs_liquid a ,pmm_employee b, pmm_designation c
where a.status_flag  in ('AC') and a.app_auth=CAST(empno AS VARCHAR(10))  and c.emp_desig_cd= b.emp_desig_cd and a.emp_no=b.emp_no and c.executive_post='E' ) ) as distinctAll;

 Raise notice 'output rcount  %',  rcount;
 return next;
END
$$;


