--
-- TOC entry 6935 (class 1255 OID 23928)
-- Name: pm_sf_neaparpending(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pm_sf_neaparpending(empno integer) RETURNS TABLE(countofpendingapar integer)
    LANGUAGE plpgsql
    AS $$

DECLARE  
countApar int;
countRepr int;
countRefer int;

begin

select count(*)::integer into countApar
from  pmtk_neapar_hdr b, pmtk_neapar_hierarchy a
where a.emp_no=b.emp_no and a.fin_year=b.fin_year and b.status = 'P'
and hierarchy_emp = empno and ((b.currently_with = 'ASR' and a.hierarchy_cd = 'ASR')
OR (b.currently_with = 'RVR' and a.hierarchy_cd = 'RVR')
OR (b.currently_with = 'CSN' and a.hierarchy_cd = 'CSN')
OR (b.currently_with = 'ACC' and a.hierarchy_cd = 'ACC'));

Raise notice 'output countApar  %',  countApar;

select count(*)::integer into countRepr 
from pmtk_neapar_represent
where rep_status='REG' and apar_id in (
	select (emp_no::text)||'-'||substring(fin_year,1,4)||substring(fin_year,6,2) 
	from pmtk_neapar_hierarchy 
	where form_type in ('A','D') and hierarchy_cd='RVR' and hierarchy_emp = empno ) 
OR	rep_status='REG' and apar_id in
	(select (emp_no::text)||'-'||substring(fin_year,1,4)||substring(fin_year,6,2)
	from pmtk_neapar_hierarchy	
	where form_type in ('B','C')
and hierarchy_cd='ACC' and hierarchy_emp = empno );

Raise notice 'output countRepr  %',  countRepr;

select count(*)::integer into countRefer 
from pmtk_neapar_refer 
where emp_no=empno and reffile_user_id is null 
and apar_id in (
	select apar_id 
	from pmtk_neapar_represent 
	where rep_status='REG');
	
Raise notice 'output countRefer  %',  countRefer;

countOfPendingApar = countApar+countRepr+countRefer;

Raise notice 'output countOfPendingApar  %',  countOfPendingApar;

return next;

end; 
$$;


ALTER FUNCTION public.pm_sf_neaparpending(empno integer) OWNER TO postgres;

--
-- TOC entry 6936 (class 1255 OID 23929)
-- Name: pm_sf_pmfa_getamount(integer, smallint, timestamp without time zone, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pm_sf_pmfa_getamount(p_emp_no integer, p_ad_cd smallint, p_pay_yearmonth timestamp without time zone, p_flag character) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare  p_stat  int ;
  FLG char(1);
  STS char(1);
  AMT int;
 C int;
 Z int;
 
   
BEGIN

--- on exception
--- set p_stat
--raise exception -746,0, "Unable to get amount ";
--- end exception;

--- set debug file to "/tmp/pmfa_getAmount.txt";

--- trace on ;

p_stat := 0 ;

-- if p_flag  is 'T' then use transaction tables  and if p_flag is 'H' then use history table

IF p_flag = 'T' THEN
        ---check if employee has an entry in header table

        SELECT COUNT(H.stopage_flag) INTO C from pmtk_emp_paymod_hdr H  WHERE  H.pay_yearmonth=p_pay_yearMonth  AND  H.emp_no=p_emp_no;

        IF C = 0 THEN
                -- Get the amount from paysheet
                select ad_amount INTO AMT from pmhk_pay_monthly where emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth and ad_cd=p_ad_cd ;
                RETURN AMT;

        ELSE
                ---get status from header table
                SELECT  H.stopage_flag INTO FLG  from pmtk_emp_paymod_hdr H WHERE H.emp_no=p_emp_no AND  H.pay_yearmonth=p_pay_yearMonth ;

                ---if the flag is P i.e. partial payment then
                IF FLG ='P'  THEN
                        ----check if there is an entry for given ad code
                        SELECT COUNT(d.STATUS) into Z  from pmtk_emp_paymod_dtl D WHERE D.emp_no=p_emp_no AND D.pay_yearmonth=p_pay_yearMonth AND D.ad_cd=p_ad_cd;
                        IF Z= 0 THEN
                                ----GET AMOUNT FROM MONTHLY TABLE
                                select ad_amount INTO AMT from pmhk_pay_monthly where emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth and ad_cd=p_ad_cd ;
                                RETURN AMT;

                        ELSE
                                ----GET amount depending upon the status

                                SELECT D.status INTO STS from pmtk_emp_paymod_dtl D WHERE D.emp_no=p_emp_no AND D.pay_yearmonth=p_pay_yearMonth AND D.ad_cd=p_ad_cd;
                                IF STS='F' THEN
                                        SELECT  ad_amount INTO AMT from pmtk_emp_paymod_dtl WHERE  emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth AND ad_cd=p_ad_cd ;
                                END IF;
                                IF STS='D' THEN
                                        SELECT  ad_amount INTO AMT from pmtk_emp_paymod_dtl WHERE  emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth AND ad_cd=p_ad_cd ;
                                END IF;

                                IF STS='R' THEN
                                        select ad_amount INTO AMT from pmhk_pay_monthly where emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth and ad_cd=p_ad_cd ;
                                END IF;
                        END IF;
                END IF;

                ----if flag is R in header table i.e. rejected then get the amount from monthly table
                IF FLG = 'R' THEN
                        select ad_amount INTO AMT from pmhk_pay_monthly where emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth and ad_cd=p_ad_cd ;
                END IF ;

                -----if flag in header table in F , that is full stoppage is marked  by junior employee then return amount as zero.
                IF FLG = 'F' THEN
                         AMT := 0;
                END IF ;
                -----if flag in header table in A , that is full stoppage is authorized by senior employee then return amount as zero.
                IF FLG = 'A' THEN
                         AMT := 0;
                END IF ;

                RETURN AMT;
        END IF;
END IF;

IF p_flag = 'H' THEN
        ---check if employee has an entry in header atble

        SELECT COUNT(H.stopage_flag) INTO C from pmhk_emp_paymod_hdr H  WHERE  H.pay_yearmonth=p_pay_yearMonth  AND  H.emp_no=p_emp_no;

        IF C = 0 THEN
                -- Get the amount from paysheet
                select ad_amount INTO AMT from pmhk_pay_monthly where emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth and ad_cd=p_ad_cd ;
                RETURN AMT;

        ELSE
                ---get status from header table
                SELECT  H.stopage_flag INTO FLG  from pmhk_emp_paymod_hdr H WHERE H.emp_no=p_emp_no AND  H.pay_yearmonth=p_pay_yearMonth ;

                IF FLG ='P'  THEN
                        ----check if there is an entry for given ad code
                        SELECT COUNT(d.STATUS) into Z  from pmhk_emp_paymod_dtl D WHERE D.emp_no=p_emp_no AND D.pay_yearmonth=p_pay_yearMonth AND D.ad_cd=p_ad_cd;
                        IF Z= 0 THEN
                                ----GET AMOUNT FROM MONTHLY TABLE
                                select ad_amount INTO AMT from pmhk_pay_monthly where emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth and ad_cd=p_ad_cd ;
                                RETURN AMT;

                        ELSE
                                ----GET amount depending upon the status

                                SELECT D.status INTO STS from pmhk_emp_paymod_dtl D WHERE D.emp_no=p_emp_no AND D.pay_yearmonth=p_pay_yearMonth AND D.ad_cd=p_ad_cd;
                                IF STS='F' THEN
                                        SELECT  ad_amount INTO AMT from pmhk_emp_paymod_dtl WHERE  emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth AND ad_cd=p_ad_cd ;
                                END IF;
                                IF STS='D' THEN
                                        SELECT  ad_amount INTO AMT from pmhk_emp_paymod_dtl WHERE  emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth AND ad_cd=p_ad_cd ;
                                END IF;

                                IF STS='R' THEN
                                        select ad_amount INTO AMT from pmhk_pay_monthly where emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth and ad_cd=p_ad_cd ;
                                END IF;
                        END IF;
                END IF;

                ----if flag is R in header table i.e. rejected then get the amount from monthly table
                IF FLG = 'R' THEN
                        select ad_amount INTO AMT from pmhk_pay_monthly where emp_no=p_emp_no AND pay_yearmonth=p_pay_yearMonth and ad_cd=p_ad_cd ;
                END IF ;

                -----if flag in header table in F , that is full stoppage is marked  by junior employee then return amount as zero.
                IF FLG = 'F' THEN
                         AMT := 0;
                END IF ;
                -----if flag in header table in A , that is full stoppage is authorized by senior employee then return amount as zero.
                IF FLG = 'A' THEN
                         AMT := 0;
                END IF ;

                RETURN AMT;
        END IF;
END IF;
END;
$$;


ALTER FUNCTION public.pm_sf_pmfa_getamount(p_emp_no integer, p_ad_cd smallint, p_pay_yearmonth timestamp without time zone, p_flag character) OWNER TO postgres;

