-- TOC entry 7076 (class 1255 OID 23937)
-- Name: pm_sp_pq_15(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pm_sp_pq_15(empno integer) RETURNS TABLE(r_count integer)
    LANGUAGE plpgsql
    AS $$

BEGIN

drop table if exists temp_photo_ver_cnt_001 ;
drop table if exists temp_photo_ver_cnt_002 ;
drop table if exists temp_photo_ver_cnt_003 ;
drop table if exists temp_photo_ver_cnt_004 ;
drop table if exists temp_doc_ver_cnt_001 ;
drop table if exists temp_doc_ver_cnt_002 ;
drop table if exists temp_doc_ver_cnt_003 ;
drop table if exists temp_doc_ver_cnt_004 ;
drop table if exists temp_ph_doc_ver_cnt ;
drop table if exists temp_ph_doc_ver_cnt_grpby ;

CREATE TEMP TABLE temp_photo_ver_cnt_001 as select a.emp_no, a.depn_no, count(*) as self_umid_photo_tbl
from pmmk_empdepn_photo_dtl a, pmmk_photo_param b, pmm_employee c, pmm_depn_fly d, pmm_relation e
where a.emp_no = c.emp_no and a.emp_no = d.emp_no and c.emp_no = d.emp_no and c.emp_curr_stat = 'A'
and a.depn_no = d.depn_no and a.depn_no = 0 and COALESCE(((current_date-d.depn_birth_dt)/365)) > (select age_ph_upd from pmtk_param_ext)
and a.relation_cd = d.relation_cd and a.relation_cd = e.relation_cd and d.relation_cd = e.relation_cd
and a.photo_cd = b.photo_cd and b.man_opt = 'M' and b.purpose_code = 'UM' and a.status in('R','M','V','S','D')
and a.ver_userid = empno group by 1,2
having count(*) = (select count(*) as self_umid_photo_param from pmmk_photo_param where man_opt = 'M' and purpose_code = 'UM') ;

CREATE TEMP TABLE temp_photo_ver_cnt_002 as select a.emp_no, a.depn_no, count(*) as fly_umid_photo_tbl
from pmmk_empdepn_photo_dtl a, pmmk_photo_param b, pmm_employee c, pmm_depn_fly d, pmm_relation e, pmmk_depn_bloodgroup_dtl f
where a.emp_no = c.emp_no and a.emp_no = d.emp_no and a.emp_no = f.emp_no
and c.emp_no = d.emp_no and c.emp_no = f.emp_no and c.emp_curr_stat = 'A'
and a.depn_no = d.depn_no and a.depn_no = f.depn_no and d.depn_no = f.depn_no
and a.depn_no != 0 and COALESCE(((current_date-d.depn_birth_dt)/365)) > (select age_ph_upd from pmtk_param_ext)
and a.relation_cd = d.relation_cd and a.relation_cd = e.relation_cd and d.relation_cd = e.relation_cd and e.depn_flg = 'F'
and a.photo_cd = b.photo_cd and b.man_opt_depn = 'M' and b.purpose_code = 'UM' and a.status in('R','M','V','S','D')
and a.ver_userid = empno group by 1,2
having count(*) = (select count(*) as fly_umid_photo_param from pmmk_photo_param where man_opt_depn = 'M' and purpose_code = 'UM') ;

CREATE TEMP TABLE temp_photo_ver_cnt_003 as select a.emp_no, a.depn_no, count(*) as blage_umid_photo
from pmmk_empdepn_photo_dtl a, pmmk_photo_param b, pmm_employee c, pmm_depn_fly d, pmm_relation e, pmmk_depn_bloodgroup_dtl f
where a.emp_no = c.emp_no and a.emp_no = d.emp_no and a.emp_no = f.emp_no
and c.emp_no = d.emp_no and c.emp_no = f.emp_no and c.emp_curr_stat = 'A'
and a.depn_no = d.depn_no and a.depn_no = f.depn_no and d.depn_no = f.depn_no
and a.depn_no != 0 and COALESCE(((current_date-d.depn_birth_dt)/365)) < (select age_ph_upd from pmtk_param_ext)
and a.relation_cd = d.relation_cd and a.relation_cd = e.relation_cd and d.relation_cd = e.relation_cd and e.depn_flg = 'F'
and a.photo_cd = b.photo_cd and b.man_opt_blage = 'M' and b.purpose_code = 'UM' and a.status in('R','M','V','S','D')
and a.ver_userid = empno group by 1,2
having count(*) = (select count(*) as blage_umid_photo_param from pmmk_photo_param where man_opt_blage = 'M' and purpose_code = 'UM') ;

CREATE TEMP TABLE temp_photo_ver_cnt_004 as select a.emp_no, a.depn_no, count(*) as depn_umid_photo
from pmmk_empdepn_photo_dtl a, pmmk_photo_param b, pmm_employee c, pmm_depn_fly d, pmm_relation e, pmmk_depn_bloodgroup_dtl f
