where a.app_userid = empno and a.depn_no = 0 and a.status in('V')
and a.doc_no_main = b.doc_no_main and a.doc_no_sub = b.doc_no_sub
and b.purpose_code = 'UM' and b.man_opt_fly = 'M'
and a.emp_no in(select emp_no from temp_doc_app_cnt_001 where emp_no = a.emp_no and depn_no = a.depn_no)
UNION ALL
SELECT emp_no, depn_no, 'D' as catg from pmtk_empdepn_doc_dtl a, pmmk_empdepn_doc_param_sub b
where a.app_userid = empno and a.depn_no != 0 and a.status in('V')
and a.doc_no_main = b.doc_no_main and a.doc_no_sub = b.doc_no_sub
and b.purpose_code = 'UM' and b.man_opt_depn = 'M'
and a.emp_no in(select emp_no from temp_doc_app_cnt_001 where emp_no = a.emp_no and depn_no = a.depn_no)
UNION ALL
SELECT emp_no, depn_no, 'D' as catg from pmtk_empdepn_doc_dtl a, pmmk_empdepn_doc_param_sub b
where a.app_userid = empno and a.depn_no != 0 and a.status in('V')
and a.doc_no_main = b.doc_no_main and a.doc_no_sub = b.doc_no_sub
and b.purpose_code = 'UM' and b.man_opt_blage = 'M'
and a.emp_no in(select emp_no from temp_doc_app_cnt_001 where emp_no = a.emp_no and depn_no = a.depn_no)
UNION ALL
SELECT emp_no, depn_no, 'D' as catg from pmtk_empdepn_doc_dtl a, pmmk_empdepn_doc_param_sub b
where a.app_userid = empno and a.depn_no != 0 and a.status in('V')
and a.doc_no_main = b.doc_no_main and a.doc_no_sub = b.doc_no_sub
and b.purpose_code = 'UM' and b.man_opt_oth_depn = 'M'
and a.emp_no in(select emp_no from temp_doc_app_cnt_001 where emp_no = a.emp_no and depn_no = a.depn_no) ) ;

CREATE TEMP TABLE temp_ph_doc_app_cnt_grpby as
select * from temp_ph_doc_app_cnt group by 1,2,3 order by emp_no, depn_no, catg ;

select count(*)::integer into r_count from temp_ph_doc_app_cnt_grpby ;

Raise notice 'output r_count  %',  r_count;

drop table if exists temp_photo_app_cnt_001 ;
drop table if exists temp_photo_app_cnt_002 ;
drop table if exists temp_photo_app_cnt_003 ;
drop table if exists temp_photo_app_cnt_004 ;
drop table if exists temp_doc_app_cnt_001 ;
drop table if exists temp_doc_app_cnt_002 ;
drop table if exists temp_doc_app_cnt_003 ;
drop table if exists temp_doc_app_cnt_004 ;
drop table if exists temp_ph_doc_app_cnt ;
drop table if exists temp_ph_doc_app_cnt_grpby ;

return next;

END
$$;


