--

CREATE FUNCTION public.pm_sp_tp_01(empno integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$


--DEFINE count INT;
--DEFINE cnt1 INT;
--DEFINE cnt2 INT;

DECLARE count INT;
DECLARE cnt1 INT;
DECLARE cnt2 INT;

BEGIN

select count(*) into cnt1  from pmtk_transfer
where assign_user_id = empno and second_auth is not null
and stat_flag = 'RC' ;

select count(*)  into cnt2 from pmtk_transfer
where assign_user_id = empno and second_auth is  null
and stat_flag = 'NC';

--let count=cnt1+cnt2;
count=cnt1+cnt2;

--RETURN count;
--END PROCEDURE;

RETURN count;
END;
$$;


