--
-- TOC entry 6939 (class 1255 OID 23974)
-- Name: pmp_checkpmfaprocess(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pmp_checkpmfaprocess(in_zone_cd text, in_pay_yearmonth text, in_process text) RETURNS TABLE(v_for_zone text, v_pay_yearmonth timestamp without time zone, v_pd_flag character)
    LANGUAGE plpgsql
    AS $$
Declare
in_pay_yearmn TIMESTAMP;
	
BEGIN
in_pay_yearmn := TO_DATE(in_pay_yearmonth, 'yyyy-MM');

	IF IN_PROCESS ='P' THEN
		FOR V_FOR_ZONE, V_PAY_YEARMONTH, V_PD_FLAG
			IN SELECT 
				PPS.FOR_ZONE AS FOR_ZONE,
				PPS.PAY_YEARMONTH AS PAY_YEARMONTH,
				PPS.PD_FLAG AS PD_FLAG
					FROM 
				PMTK_PMFAI_STAT PPS
				WHERE PPS.FOR_ZONE = IN_ZONE_CD AND
					PPS.PAY_YEARMONTH = in_pay_yearmn
					AND
					PPS.PD_FLAG IN ('P','A','p','a') LOOP
			RETURN NEXT;
		END LOOP;

	ELSIF IN_PROCESS ='D' THEN 
		FOR V_FOR_ZONE, V_PAY_YEARMONTH, V_PD_FLAG
			IN SELECT 
				PPS.FOR_ZONE AS FOR_ZONE,
				PPS.PAY_YEARMONTH AS PAY_YEARMONTH,
				PPS.PD_FLAG AS PD_FLAG
					FROM 
				PMTK_PMFAI_STAT PPS 
				WHERE PPS.FOR_ZONE = IN_ZONE_CD AND
					PPS.PAY_YEARMONTH = in_pay_yearmn   AND
					PPS.PD_FLAG IN ('A','a') LOOP
			RETURN NEXT;
		END LOOP;	 
	END IF;
END;
$$;


ALTER FUNCTION public.pmp_checkpmfaprocess(in_zone_cd text, in_pay_yearmonth text, in_process text) OWNER TO postgres;

