--

CREATE FUNCTION public.pmp_getemployeesdept(in_unit_cd character varying, in_emp_no integer) RETURNS TABLE(p_emp_no integer, p_emp_short_name text, p_emp_desig_cd text, p_last_date date)
    LANGUAGE plpgsql
    AS $$
  
BEGIN
                                                                                                                                                                     
IF IN_UNIT_CD ISNULL and IN_EMP_NO ISNULL THEN
  FOR P_EMP_NO, P_EMP_SHORT_NAME, P_EMP_DESIG_CD, P_LAST_DATE
    IN SELECT  PE.EMP_NO,
                PE.EMP_SHORT_NAME,
                PE.EMP_DESIG_CD,
                PE.LAST_DATE
           FROM PMM_EMPLOYEE PE
        WHERE PE.EMP_CURR_STAT='A' LOOP 
   RETURN NEXT;
 END LOOP;

ELSE
  FOR P_EMP_NO, P_EMP_SHORT_NAME, P_EMP_DESIG_CD, P_LAST_DATE
    IN SELECT  PE.EMP_NO,
                PE.EMP_SHORT_NAME,
                PE.EMP_DESIG_CD,
                PE.LAST_DATE
           FROM PMM_EMPLOYEE PE
        WHERE PE.EMP_CURR_STAT='A' AND PE.STN_CDE IN 
        (
                SELECT CITY_CD FROM PMM_CITY PC WHERE PC.EMP_DIVISION_CD =IN_UNIT_CD
        )
		 and emp_dept_cd in (select emp_dept_cd from pmm_employee where emp_no=IN_EMP_NO) 
		LOOP
   RETURN  NEXT;
  END LOOP;
  
END IF;
END  ;
$$;


