--

CREATE FUNCTION public.pmp_getemployeesfa(in_unit_cd character varying) RETURNS TABLE(p_emp_no integer, p_emp_short_name text, p_emp_desig_cd text, p_last_date date)
    LANGUAGE plpgsql
    AS $$
  
BEGIN
                                                                                                                                                                     
IF in_unit_cd='' THEN
  FOR p_emp_no, p_emp_short_name, p_emp_desig_cd, p_last_date
    IN SELECT  PE.EMP_NO,
                PE.EMP_SHORT_NAME,
                PE.EMP_DESIG_CD,
                PE.LAST_DATE
           FROM PMM_EMPLOYEE PE
        WHERE PE.EMP_CURR_STAT='A' LOOP 
   RETURN NEXT;
 END LOOP;

ELSE
 FOR p_emp_no, p_emp_short_name, p_emp_desig_cd, p_last_date
    IN SELECT  PE.EMP_NO,
                PE.EMP_SHORT_NAME,
                PE.EMP_DESIG_CD,
                PE.LAST_DATE
           FROM PMM_EMPLOYEE PE
        WHERE PE.EMP_CURR_STAT='A' AND PE.STN_CDE IN 
        (
                SELECT CITY_CD FROM PMM_CITY PC WHERE PC.EMP_DIVISION_CD =in_unit_cd
        ) LOOP
   RETURN  NEXT;
  END LOOP;
  
END IF;
END  ;
$$;


