-- TOC entry 6951 (class 1255 OID 23986)
-- Name: pmp_getkrrehsemployee(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pmp_getkrrehsemployee(in_threshold integer) RETURNS TABLE(p_emp_no integer, p_emp_short_name text, p_emp_desig_cd text, p_last_date date)
    LANGUAGE plpgsql
    AS $$

DECLARE 
 P_CURRENT_DATE DATE;
begin
--P_CURRENT_DATE := CURRENT;
FOR P_EMP_NO, P_EMP_SHORT_NAME, P_EMP_DESIG_CD, P_LAST_DATE
IN SELECT
EMP_NO,
EMP_SHORT_NAME,
EMP_DESIG_CD,
LAST_DATE
FROM(
SELECT
PE.EMP_NO,
PE.EMP_SHORT_NAME,
PE.EMP_DESIG_CD,
PE.LAST_DATE
FROM PMM_EMPLOYEE PE
WHERE PE.EMP_CURR_STAT = 'A'
AND (CAST (PE.LAST_DATE AS DATE) - CAST(CURRENT_DATE AS DATE) ) BETWEEN 0 AND IN_THRESHOLD
UNION
SELECT
PE.EMP_NO,
PE.EMP_SHORT_NAME,
PE.EMP_DESIG_CD,
PE.LAST_DATE
FROM PMM_EMPLOYEE PE
WHERE PE.EMP_CURR_STAT != 'A'
) s LOOP
RETURN NEXT;
END LOOP;
END;
$$;


