--
-- TOC entry 6953 (class 1255 OID 23987)
-- Name: pmp_getpaymentadviceboa(character, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pmp_getpaymentadviceboa(in_zone_cd character, in_pay_yearmonth timestamp without time zone) RETURNS TABLE(v_au6_jv_no integer, v_alloc_amt integer, v_dr_cr_flag character, v_account_head_id bigint, v_cost_centre_id bigint, v_account_head_code text, v_cost_centre_code integer, v_sh_desc text)
    LANGUAGE plpgsql
    AS $$

	

BEGIN

 FOR V_AU6_JV_NO, V_ALLOC_AMT, V_DR_CR_FLAG, V_ACCOUNT_HEAD_ID, V_COST_CENTRE_ID, V_ACCOUNT_HEAD_CODE, V_COST_CENTRE_CODE, V_SH_DESC
		IN SELECT 
			FA.AU6_JV_NO AS AU6_JV_NO,
			FA.ALLOC_AMT AS ALLOC_AMT,
			FA.DR_CR_FLAG AS DR_CR_FLAG ,
			FPAHM.ACCOUNT_HEAD_ID AS ACCOUNT_HEAD_ID,
			FPCM.COST_CENTRE_ID AS COST_CENTRE_ID,
			FA.ACCT_HEAD as ACCOUNT_HEAD_CODE,
			FA.CC_CD as COST_CENTRE_CODE,
			FACT.SH_DESC
			FROM 
			FATK_ALLOCATION FA
			LEFT OUTER JOIN FAPK_PMFA_ACCT_HEAD_MAP FPAHM ON
				FA.ACCT_HEAD = FPAHM.ACCT_HEAD
			LEFT OUTER JOIN FAPK_PMFA_CCCD_MAP FPCM ON 
				FA.CC_CD = FPCM.CC_CD 
			LEFT OUTER join FAM_ACCT  FACT ON
				FA.ACCT_HEAD = FACT.ACCT_HEAD
		WHERE AU6_JV_NO IN
			(
				SELECT FSB.SUB_AU6_JV_NO
				FROM FAHK_SUB_BILL FSB WHERE FSB.MOD_CD IN ('JVP', 'JVA') AND FSB.ZONE_CD= IN_ZONE_CD AND FSB.PAY_YEARMONTH = IN_PAY_YEARMONTH
				AND FSB.PAY_AMT !=0  
			)
                        AND FA.LED_CD = IN_ZONE_CD LOOP
	RETURN NEXT;

END LOOP;	 
END    ;
$$;


ALTER FUNCTION public.pmp_getpaymentadviceboa(in_zone_cd character, in_pay_yearmonth timestamp without time zone) OWNER TO postgres;

--
-- TOC entry 6954 (class 1255 OID 23988)
-- Name: pmp_getpaymentadvicejv(character, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pmp_getpaymentadvicejv(in_zone_cd character, in_pay_yearmonth timestamp without time zone) RETURNS TABLE(v_voucher_type_id bigint, v_sub_au6_jv_no integer, v_sub_desc text, v_pay_yearmonth timestamp without time zone, v_pay_amt integer, v_fa_date date, v_state_id smallint, v_unit_id smallint, v_profit_center smallint, v_voucher_type text, v_pay_zone text)
    LANGUAGE plpgsql
    AS $$

BEGIN
	
 FOR V_VOUCHER_TYPE_ID, V_SUB_AU6_JV_NO, V_SUB_DESC, V_PAY_YEARMONTH, V_PAY_AMT, V_FA_DATE, V_STATE_ID, V_UNIT_ID, V_PROFIT_CENTER, V_VOUCHER_TYPE, V_PAY_ZONE
	IN SELECT 
		FPVTM.VOUCHER_TYPE_ID AS VOUCHER_TYPE_ID,
		FSB.SUB_AU6_JV_NO AS SUB_AU6_JV_NO,
		FSB.SUB_DESC AS SUB_DESC ,
		FSB.PAY_YEARMONTH AS PAY_YEARMONTH,
		(FSB.PAY_AMT + FSB.ADDL_CHARGES) AS PAY_AMT,
		FSB.FA_DATE AS FA_DATE,
		FPUSM.STATE_ID AS STATE_ID,
		FPUSM.UNIT_ID AS UNIT_ID,
		FPUSM.PROFIT_CENTER AS PROFIT_CENTER,
		FSB.MOD_CD AS VOUCHER_TYPE,
		FSB.ZONE_CD AS PAY_ZONE
	FROM 
		FAHK_SUB_BILL FSB
	LEFT OUTER JOIN FAPK_PMFA_UNIT_STATE_MAP FPUSM ON
		FSB.ZONE_CD = FPUSM.PAY_ZONE
	LEFT OUTER JOIN FAPK_PMFA_VCH_TYPE_MAP FPVTM ON
		FSB.MOD_CD = FPVTM.MOD_CD
	WHERE FSB.MOD_CD IN ('JVP','JVA')  AND FSB.ZONE_CD = IN_ZONE_CD AND
		FSB.PAY_YEARMONTH = IN_PAY_YEARMONTH AND
		PAY_AMT !=0 LOOP 
	
		RETURN NEXT;

END LOOP;	 
END;
$$;


ALTER FUNCTION public.pmp_getpaymentadvicejv(in_zone_cd character, in_pay_yearmonth timestamp without time zone) OWNER TO postgres;

