--

CREATE FUNCTION public.pmp_getpmbillboa(in_zone_cd character, in_pay_yearmonth timestamp without time zone, in_mod_cd character) RETURNS TABLE(v_au6_jv_no integer, v_alloc_amt integer, v_dr_cr_flag character, v_account_head_id bigint, v_cost_centre_id bigint, v_account_head_code text, v_cost_centre_code integer, v_sh_desc text)
    LANGUAGE plpgsql
    AS $$

	
  
BEGIN

 FOR V_AU6_JV_NO, V_ALLOC_AMT, V_DR_CR_FLAG, V_ACCOUNT_HEAD_ID, V_COST_CENTRE_ID, V_ACCOUNT_HEAD_CODE, V_COST_CENTRE_CODE, V_SH_DESC
	IN SELECT 
		FA.AU6_JV_NO AS AU6_JV_NO,
		FA.ALLOC_AMT AS ALLOC_AMT,
		FA.DR_CR_FLAG AS DR_CR_FLAG ,
		FPAHM.ACCOUNT_HEAD_ID AS ACCOUNT_HEAD_ID,
		FPCM.COST_CENTRE_ID AS COST_CENTRE_ID,
		FA.ACCT_HEAD as ACCOUNT_HEAD_CODE,
		FA.CC_CD as COST_CENTRE_CODE,
		FACT.SH_DESC
	FROM 
		FATK_ALLOCATION FA
		LEFT OUTER JOIN FAPK_PMFA_ACCT_HEAD_MAP FPAHM ON
			FA.ACCT_HEAD = FPAHM.ACCT_HEAD
		LEFT OUTER JOIN FAPK_PMFA_CCCD_MAP FPCM ON 
			FA.CC_CD =FPCM.CC_CD 
		LEFT OUTER join fam_acct  FACT ON
			FA.ACCT_HEAD = FACT.ACCT_HEAD	
	WHERE AU6_JV_NO IN
