--
-- TOC entry 6956 (class 1255 OID 23990)
-- Name: pmp_getpmbills(character, timestamp without time zone, character, character, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pmp_getpmbills(in_zone_cd character, in_pay_yearmonth timestamp without time zone, in_mod_cd1 character, in_mod_cd2 character, in_mod_cd3 character) RETURNS TABLE(v_voucher_type_id bigint, v_sub_au6_jv_no integer, v_sub_desc text, v_pay_yearmonth timestamp without time zone, v_party_id bigint, v_pay_amt integer, v_fa_date date, v_state_id smallint, v_unit_id smallint, v_profit_center smallint, v_voucher_type text, v_pay_zone text, v_party_cd text, v_party_name text)
    LANGUAGE plpgsql
    AS $$
BEGIN
	
 FOR V_VOUCHER_TYPE_ID, V_SUB_AU6_JV_NO, V_SUB_DESC, V_PAY_YEARMONTH, V_PARTY_ID, V_PAY_AMT, V_FA_DATE, V_STATE_ID, V_UNIT_ID, V_PROFIT_CENTER, V_VOUCHER_TYPE, V_PAY_ZONE, V_PARTY_CD, V_PARTY_NAME
	IN SELECT 
		FPVTM.VOUCHER_TYPE_ID AS VOUCHER_TYPE_ID,
		FSB.SUB_AU6_JV_NO AS SUB_AU6_JV_NO,
		FSB.SUB_DESC AS SUB_DESC ,
		FSB.PAY_YEARMONTH AS PAY_YEARMONTH,
		FPPM.PARTY_ID AS PARTY_ID,
		(FSB.PAY_AMT + FSB.ADDL_CHARGES) AS PAY_AMT,
		FSB.FA_DATE AS FA_DATE,
		FPUSM.STATE_ID AS STATE_ID,
		FPUSM.UNIT_ID AS UNIT_ID,
		FPUSM.PROFIT_CENTER AS PROFIT_CENTER,
		FSB.MOD_CD AS VOUCHER_TYPE,
		FSB.ZONE_CD AS PAY_ZONE,
		FSB.PARTY_CD AS PARTY_CD,
		FP.PARTY_NAME
			FROM 
				FAHK_SUB_BILL FSB
			LEFT OUTER JOIN FAPK_PMFA_UNIT_STATE_MAP FPUSM ON
				FSB.ZONE_CD = FPUSM.PAY_ZONE
			LEFT OUTER JOIN FAPK_PMFA_PARTY_MAP FPPM ON 
				FSB.PARTY_CD = FPPM.PARTY_CD 
			LEFT OUTER JOIN FAPK_PMFA_VCH_TYPE_MAP FPVTM ON
				FSB.MOD_CD = FPVTM.MOD_CD
			left outer join FAM_PARTY FP on
				FSB.PARTY_CD = FP.PARTY_CD
			WHERE FSB.MOD_CD IN (IN_MOD_CD1 ,IN_MOD_CD2,IN_MOD_CD3) AND FSB.ZONE_CD = IN_ZONE_CD AND
                        FSB.PAY_YEARMONTH = IN_PAY_YEARMONTH  

			AND PAY_AMT !=0 LOOP 

	RETURN NEXT;

END LOOP;	 
END  ;
$$;


ALTER FUNCTION public.pmp_getpmbills(in_zone_cd character, in_pay_yearmonth timestamp without time zone, in_mod_cd1 character, in_mod_cd2 character, in_mod_cd3 character) OWNER TO postgres;

--
-- TOC entry 6957 (class 1255 OID 23991)
-- Name: pmp_validateexecutive(integer, character, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pmp_validateexecutive(in_emp_no integer, in_short_name character, in_designation character) RETURNS TABLE(v_valid integer)
    LANGUAGE plpgsql
    AS $$

	
begin

	FOR V_VALID
		IN SELECT
			(CASE WHEN EMP_NO = IN_EMP_NO AND EMP_SHORT_NAME = IN_SHORT_NAME and EMP_DESIG_CD = IN_DESIGNATION THEN 1 ELSE 0 END) AS VALID
			FROM
			(
				SELECT 		
					PE.EMP_NO ,
					PE.EMP_SHORT_NAME ,
					PD.EMP_DESIG_CD 
				FROM 
					PMM_EMPLOYEE PE 
				LEFT JOIN PMMK_DESIG_EXT PD ON 
					PE.EMP_DESIG_CD = PD.EMP_DESIG_CD 
				WHERE EMP_NO = IN_EMP_NO
					  AND PD.EXECUTIVE_POST ='E'
			) s LOOP
		RETURN NEXT;
	END LOOP;
END 
;
$$;


ALTER FUNCTION public.pmp_validateexecutive(in_emp_no integer, in_short_name character, in_designation character) OWNER TO postgres;

