        FOR V_VALID
                IN SELECT
                        (CASE WHEN EMP_NO = IN_EMP_NO
                                                AND EMP_SHORT_NAME = IN_SHORT_NAME
                                                AND EMP_DESIG_CD = IN_DESIGNATION
                                                AND EMP_DEPT_CD = IN_DEPT_CODE
