                                WHERE EMP_NO = IN_EMP_NO
                                          AND PD.EXECUTIVE_POST ='E'
                                          AND PE.EMP_DEPT_CD =IN_DEPT_CODE
                        ) s LOOP
                RETURN	NEXT;
        END LOOP;
END ;
$$;


