--
-- TOC entry 6800 (class 1255 OID 103701)
-- Name: sa_insert_sam_user(integer, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sa_insert_sam_user(ip_emp_no integer, ip_last_date date) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
    sql             varchar;
    p_exec_flag     CHAR(1);
BEGIN
    SELECT a.executive_post INTO p_exec_flag FROM pmm_designation a, pmm_employee b WHERE a.emp_desig_cd=b.emp_desig_cd AND b.emp_no=ip_emp_no; 

    IF p_exec_flag = 'N' THEN
        INSERT INTO sam_user(user_id, emp_no, user_status, exp_date, role_id, email, internet)
        VALUES (CAST(ip_emp_no AS text), ip_emp_no, 'A', ip_last_date, 7829, 'Y', 'Y');

        INSERT INTO samk_user(user_id, emp_no, user_status, exp_date, role_id, reporting_officerno, time_stamp, created_by, request_id, request_date, stn_cde)
        VALUES (CAST(ip_emp_no AS text), ip_emp_no, 'A', ip_last_date, 7829, NULL, CURRENT_TIMESTAMP, 'system', 0, CURRENT_DATE, 'BLP');
    END IF;

    IF p_exec_flag = 'E' THEN
        INSERT INTO sam_user(user_id, emp_no, user_status, exp_date, role_id, email, internet)
        VALUES (CAST(ip_emp_no AS text), ip_emp_no, 'A', ip_last_date, 3520, 'Y', 'Y');

        INSERT INTO samk_user(user_id, emp_no, user_status, exp_date, role_id, reporting_officerno, time_stamp, created_by, request_id, request_date, stn_cde)
        VALUES (CAST(ip_emp_no AS text), ip_emp_no, 'A', ip_last_date, 3520, NULL, CURRENT_TIMESTAMP, 'system', 0, CURRENT_DATE, 'BLP');
    END IF;

    UPDATE sam_user_passwd SET passwd = 'bHW2rCSK/8d90nA69UxsIA==', time_stamp = CURRENT_TIMESTAMP 
	WHERE user_id = CAST(ip_emp_no AS text);

    sql = 'copy (SELECT a.emp_no,
                COALESCE(trim(a.emp_firstname),'''') ||'' ''|| COALESCE(trim(a.emp_midname),'''') ||'' ''|| COALESCE(trim(a.emp_surname),''''),
                COALESCE(trim(a.emp_surname),''.''), COALESCE(trim(a.emp_firstname),''''), COALESCE(trim(a.emp_midname),''.''),
                trim(b.emp_dept_desc),
                trim(a.emp_desig_cd),
                trim((CASE WHEN c.emp_division_cd = ''CO'' THEN ''BELAPUR'' WHEN c.emp_division_cd = ''RN'' THEN ''RATNAGIRI'' WHEN
                c.emp_division_cd = ''KW'' THEN ''KARWAR'' END)),
                trim(d.state_description),
                trim(concat(''/home/'',a.emp_no))
                FROM pmm_employee a, pmm_department b, pmm_city c, pmm_state d WHERE
                a.emp_dept_cd=b.emp_dept_cd AND a.stn_cde=c.city_cd
                AND a.emp_curr_stat=''A'' AND c.state_cd=d.state_cd AND a.emp_no = %L)
                TO ''/home/jrapusr/ldap/newuserdata.unl'' delimiter ''|'';';

    EXECUTE format(sql, ip_emp_no);

    COPY ( SELECT '' ) TO PROGRAM 'sh /home/jrapusr/ldap/ldapuseradd.sh';

    RETURN;
END;
$$;


ALTER FUNCTION public.sa_insert_sam_user(ip_emp_no integer, ip_last_date date) OWNER TO postgres;

--
-- TOC entry 6808 (class 1255 OID 108765)
-- Name: sa_insert_um_user(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sa_insert_um_user(ip_emp_no integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    p_exec_flag CHAR(1);
    user_uid integer;
    flag boolean;
    def_unit smallint;
    emp_name CHAR(30);
    emp_desig CHAR(8);
    emp_last_dt date;
BEGIN
    SELECT emp_short_name, emp_desig_cd, last_date
    INTO emp_name, emp_desig, emp_last_dt
    FROM pmm_employee
    WHERE emp_no = ip_emp_no;

    SELECT MAX(uid)+1
    INTO user_uid
    FROM fam.ummc_user;

    INSERT INTO fam.ummc_user
    VALUES (
        user_uid, 
        CAST(ip_emp_no AS text), 
        NULL, NULL, 'password', NULL, 'A', 'N', 'Y', 
        CURRENT_DATE, emp_last_dt, CURRENT_TIMESTAMP, 1004, 
        NULL, emp_name, emp_desig, NULL
    );

    select COUNT(*)>=1
    INTO flag
    FROM pmtk_last_pay
    WHERE sub_zone_cd NOT LIKE 'OL' AND emp_no = CAST(ip_emp_no AS integer);
    
    IF flag THEN
        INSERT INTO fam.umtc_user_default_unit (uid, unit_id)
        VALUES (user_uid, 4);
    ELSE
        SELECT CASE
                WHEN emp_division_cd = 'CO' THEN 1
                WHEN emp_division_cd = 'RN' THEN 2
                WHEN emp_division_cd = 'KW' THEN 3
                ELSE 0
        END
        INTO def_unit
        FROM pmm_city
        WHERE city_cd = (SELECT stn_cde FROM pmm_employee WHERE emp_no = ip_emp_no);

        IF def_unit IS NOT NULL THEN
                INSERT INTO fam.umtc_user_default_unit (uid, unit_id)
                VALUES (user_uid, def_unit);
        END IF;

    END IF;

    PERFORM setval('umtc_user_role_user_role_id_seq', MAX(a.user_role_id)) FROM fam.umtc_user_role a;

    INSERT INTO fam.umtc_user_role (user_role_id, request_id, uid, role_id, unit_id, operated_on, operated_by)
    SELECT nextval('umtc_user_role_user_role_id_seq'), NULL, user_uid, a.role_id, 1, CURRENT_TIMESTAMP, '1004'
    FROM fam.ummc_role a
    WHERE a.status = 'A' AND a.is_default = 'Y';

    RETURN;
END;
$$;


