CREATE FUNCTION public.sa_update_ldap_emailmob(ip_emp_no integer) RETURNS void
    LANGUAGE plpgsql
    AS $$

        DECLARE exec_cmd char(50);
		sql varchar;
BEGIN
	 	sql = 'copy (SELECT emp_no,
		concat(''+91'',COALESCE(NULLIF(emp_mobile_no,''''), personal_mobile)) as mobile,
		COALESCE(NULLIF(trim(email_id),''''),trim(personal_email_id)) as mail
        FROM gmmk_email_details where login_active_flag=''Y'' and primary_acct_flag=''P'' 
		and emp_no = %L) 
		to ''/home/jrapusr/ldap/emlmobusrdata.unl'' delimiter ''|'';';
		
		EXECUTE format(sql, ip_emp_no);
	
		COPY ( SELECT '' ) TO PROGRAM 'sh /home/jrapusr/ldap/ldapusremlmob.sh';
	
	RETURN;

END ;
$$;


