-- Name: si_sf_indentapprove(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.si_sf_indentapprove(empno integer) RETURNS TABLE(rcount integer)
    LANGUAGE plpgsql
    AS $$
BEGIN  
 
    select count(distinct a.indent_no) into rcount
from sit_ind_hdr a 
where a.xfer_status ='N' 
and a.apprv_official=(select emp_desig_cd from pmm_employee where emp_no=empno) 
and LEFT(a.loc_cd,2)=(select LEFT(depot_cd,2) from sim_depot_con_loc 
where consignee_loc_cd=(select stn_cde from pmm_employee where emp_no=empno))
and a.indent_no in (select distinct indent_no from sit_std_ind_dtl where indent_status !='C' and fund_avl_flag  in('N',NULL) ) ;

return next;

END
$$;


