--

CREATE FUNCTION public.si_sf_zeroqtyins() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
    IF (new.cb_stock = 0 ) THEN
    insert into sitk_zeroqtyupd (dep_sub_cd,pl_no,dt_zeroqty,flag_zeroqty)
select x0.dep_sub_cd ,x0.pl_no ,CURRENT_DATE ,'I' from sitk_stk_subd x0 where ((
new.cb_stock = 0 ) AND (new.pl_no = x0.pl_no ) AND (dep_sub_cd != 'BLP') ) ;
    END IF;
    RETURN NULL;
END;
$$;


