--
-- TOC entry 6809 (class 1255 OID 337552)
-- Name: sifap_getgrndetails(text); Type: FUNCTION; Schema: public; Owner: itstaff
--

CREATE FUNCTION public.sifap_getgrndetails(in_grn_voucher_no text) RETURNS TABLE(p_grn_voucher_no text, p_insp_cert_no text, p_insp_cl_dt text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	
	-- Declare a variable to store the converted text array
    v_grn_voucher_array text[];
BEGIN

	-- Convert the comma-separated string to a text array
    v_grn_voucher_array := string_to_array(in_grn_voucher_no, ',');

	RETURN QUERY
	SELECT 
		consignee_cd::text || '-' || sr_no::text,
		insp_cert_no::text, 
		to_char(insp_cl_dt, 'DD/MM/YYYY')::text
	FROM sitk_sifa_grn_dtl 
	WHERE TRIM(consignee_cd) || '-' || sr_no = ANY(v_grn_voucher_array);
	
END;
$$;


ALTER FUNCTION public.sifap_getgrndetails(in_grn_voucher_no text) OWNER TO itstaff;

--
-- TOC entry 6810 (class 1255 OID 368298)
-- Name: sifap_grir_settled_dtls(integer, date, date, integer); Type: FUNCTION; Schema: public; Owner: itstaff
--

CREATE FUNCTION public.sifap_grir_settled_dtls(in_acct_head_id integer, in_posting_date_start date, in_posting_date_end date, in_unit_id integer DEFAULT NULL::integer) RETURNS TABLE(accept_qty numeric, invoice_quantity numeric, posting_date text, voucher_type_desc text, party_code text, party_name text, registration_no text, registration_date text, invoice_no text, invoice_date text, grn_no text, grn_date text, total_bill_amount numeric, contract_or_po_no text, debit numeric, credit numeric, boa_id text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH debit_agg AS (
        SELECT
            b.boa_id,
            SUM(CASE WHEN a.credit_debit_flag = 'D' THEN a.amount ELSE 0 END) AS debit
        FROM fam.fatc_boa_head a
        JOIN fam.fatc_boa b ON a.boa_id = b.boa_id
        WHERE b.status IN ('A', 'P', 'M', 'D')
            AND (in_unit_id IS NULL OR b.unit_id = in_unit_id)
            AND b.posting_date BETWEEN in_posting_date_start AND in_posting_date_end
            AND a.account_head_id = in_acct_head_id
        GROUP BY b.boa_id
    ),
    credit_agg AS (
        SELECT
            b.boa_id,
            SUM(CASE WHEN a.credit_debit_flag = 'C' THEN a.amount ELSE 0 END) AS credit
        FROM fam.fatc_boa_head a
        JOIN fam.fatc_boa b ON a.boa_id = b.boa_id
        WHERE b.status IN ('A', 'P', 'M', 'D')
            AND (in_unit_id IS NULL OR b.unit_id = in_unit_id)
            AND b.posting_date BETWEEN in_posting_date_start AND in_posting_date_end
            AND a.account_head_id = in_acct_head_id
        GROUP BY b.boa_id
    )
    SELECT DISTINCT
	g.accept_qty, 
	f.invoice_quantity,
	to_char(b.posting_date,'DD/MM/YYYY')::text  AS posting_date, 
	d.voucher_type_desc::text, 
	c.party_code::text,
	c.party_name::text,
	b.registration_no::text,
	to_char(b.registration_date,'DD/MM/YYYY')::text  AS registration_date,
	e.invoice_no::text, 
	to_char(e.invoice_date,'DD/MM/YYYY')::text  AS invoice_date,
	f.grn_voucher_no::text, 
	to_char(g.insp_cl_dt,'DD/MM/YYYY')::text AS grn_date,
	e.total_bill_amount::numeric,
	CASE	WHEN b.voucher_type_id = 17 THEN b.contract_no::text
			WHEN b.voucher_type_id = 18 THEN b.po_no::text
			ELSE NULL
	END AS contract_or_po_no,
	COALESCE(da.debit, 0)::numeric AS debit,
	COALESCE(ca.credit, 0)::numeric AS credit,
	a.boa_id::text
	FROM fam.fatc_boa_head a JOIN fam.fatc_boa b ON a.boa_id = b.boa_id
	LEFT JOIN fam.famc_party c ON c.party_id = a.party_id
	JOIN fam.famc_voucher_type d ON d.voucher_type_id = b.voucher_type_id
	LEFT JOIN fam.fatc_bill e ON e.bill_id = b.bill_id
	JOIN fam.fatc_bill_item f ON f.bill_id = e.bill_id
	JOIN sitk_sifa_grn_dtl g ON g.consignee_cd||'-'||sr_no=f.grn_voucher_no
	JOIN debit_agg da ON da.boa_id = a.boa_id
	JOIN credit_agg ca ON ca.boa_id = a.boa_id;
END;
$$;


ALTER FUNCTION public.sifap_grir_settled_dtls(in_acct_head_id integer, in_posting_date_start date, in_posting_date_end date, in_unit_id integer) OWNER TO itstaff;

