--
-- TOC entry 6968 (class 1255 OID 24005)
-- Name: sip_getgrnlist(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_getgrnlist(po_num text, unit_idn integer) RETURNS TABLE(p_consignee_cd text, p_sr_no integer, p_chalan_no text)
    LANGUAGE plpgsql
    AS $$

 BEGIN

FOR P_CONSIGNEE_CD, P_SR_NO, P_CHALAN_NO
	IN SELECT  DISTINCT A.CONSIGNEE_CD ,
			A.SR_NO,
			A.CHALAN_NO
	FROM SITK_SIFA_GRN_DTL A
		INNER JOIN SITK_RECEIPT_HDR B
		ON A.PO_NO = B.PO_NO AND A.CONSIGNEE_CD = B.CONSIGNEE_CD
		INNER JOIN SIM_CONSIGNEE D
		ON A.CONSIGNEE_CD = D.CONSIGNEE_CD AND D.CONSIGNEE_LOC_CD = B.DELIVERY_AT
		INNER JOIN SIM_DEPOT_CON_LOC E
		ON D.CONSIGNEE_LOC_CD = E.CONSIGNEE_LOC_CD
		INNER JOIN SIM_DEPOT C
		ON C.DEPOT_CD = E.DEPOT_CD
	WHERE A.PO_NO = PO_NUM
		AND C.UNIT_ID =UNIT_IDN
		AND B.INSP_CLEAR = 'Y' LOOP
	RETURN NEXT;  
END LOOP;
END;

$$;


ALTER FUNCTION public.sip_getgrnlist(po_num text, unit_idn integer) OWNER TO postgres;

--
-- TOC entry 6969 (class 1255 OID 24006)
-- Name: sip_getgrnlist2(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_getgrnlist2(l_po_no text, l_unit_id integer, l_state_id integer) RETURNS TABLE(p_consignee_cd character, p_sr_no integer, p_chalan_no character)
    LANGUAGE plpgsql
    AS $$
 
BEGIN

FOR P_CONSIGNEE_CD, P_SR_NO, P_CHALAN_NO
	IN SELECT  DISTINCT SSGD.CONSIGNEE_CD ,
			SSGD.SR_NO,
			SSGD.CHALAN_NO
	FROM SITK_SIFA_GRN_DTL SSGD
		INNER JOIN SITK_RECEIPT_HDR SRH 
		ON SSGD.PO_NO = SRH.PO_NO AND SSGD.CONSIGNEE_CD = SRH.CONSIGNEE_CD
		INNER JOIN SIM_CONSIGNEE SC 
		ON SSGD.CONSIGNEE_CD = SC.CONSIGNEE_CD AND SC.CONSIGNEE_LOC_CD = SRH.DELIVERY_AT
		INNER JOIN SIM_DEPOT_CON_LOC SDCL 
		ON SC.CONSIGNEE_LOC_CD = SDCL.CONSIGNEE_LOC_CD
		INNER JOIN SIM_DEPOT SD 
		ON SD.DEPOT_CD = SDCL.DEPOT_CD
	WHERE SSGD.PO_NO = l_po_no
		AND SD.UNIT_ID =l_unit_id
		AND SD.STATE_ID = l_state_id 
		AND SRH.INSP_CLEAR = 'Y' LOOP
	RETURN NEXT;  

END LOOP;
END     ;
$$;


ALTER FUNCTION public.sip_getgrnlist2(l_po_no text, l_unit_id integer, l_state_id integer) OWNER TO postgres;

