--
-- TOC entry 6971 (class 1255 OID 24011)
-- Name: sip_getitemdetail(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_getitemdetail(in_po_no text, in_pl_no text, in_consignee_code text, in_sr_no integer) RETURNS TABLE(p_quantity numeric, p_pur_uom character, p_po_rate numeric)
    LANGUAGE plpgsql
    AS $$
 
BEGIN

FOR P_QUANTITY, P_PUR_UOM, P_PO_RATE
 IN SELECT SSTD.QUANTITY,
  		SU.SHORT_DESC10,
  		SSTD.TOTAL_LAND_COST - SSTD.SALES_TAX AS PO_RATE
   FROM SIT_STD_TENDER_DEC SSTD
  INNER JOIN 
    ( SELECT PARTY_CD,
    		 PO_AMEND_NO,
    		 PO_NO 
    	FROM SIT_STD_PO_HDR 
    	WHERE PO_NO=IN_PO_NO
    ) AS SSPH
  	ON SSTD.TENDER_NO=SUBSTR(SSPH.PO_NO,1,9) 
  	AND SSTD.PL_NO= IN_PL_NO
  INNER JOIN SITK_SIFA_GRN_DTL SSGD
  	ON SSGD.PO_NO = IN_PO_NO 
  	AND SSGD.PL_NO = IN_PL_NO
  	AND SSGD.SR_NO = IN_SR_NO
  	AND SSGD.CONSIGNEE_CD = IN_CONSIGNEE_CODE
  INNER JOIN SIM_CONSIGNEE SC
  	ON SSGD.CONSIGNEE_CD = SC.CONSIGNEE_CD
  LEFT OUTER JOIN SIM_UOM SU 
  	ON SSTD.PUR_UOM = SU.UOM
  WHERE SSTD.PARTY_CD=SSPH.PARTY_CD AND
  		SSTD.AMEND_NO=CAST(SSPH.PO_AMEND_NO AS INT ) AND 

  		SC.CONSIGNEE_LOC_CD = SSTD.DELIVERY_PLACE LOOP 
 
  RETURN NEXT;    
  END LOOP;
END ;

$$;


ALTER FUNCTION public.sip_getitemdetail(in_po_no text, in_pl_no text, in_consignee_code text, in_sr_no integer) OWNER TO postgres;

