CREATE FUNCTION public.sip_getmaxpartycode(in_party_initial character) RETURNS TABLE(v_max_party_code character varying)
    LANGUAGE plpgsql
    AS $$
	
BEGIN

FOR V_MAX_PARTY_CODE
	IN SELECT 
		PARTY_CD
	FROM SIM_PARTY 
	WHERE PARTY_CD LIKE IN_PARTY_INITIAL
	ORDER BY CAST(SUBSTR(PARTY_CD, 3) AS INT) DESC LIMIT 1 LOOP
	RETURN NEXT;
END LOOP;
END;
$$;


