--
-- TOC entry 6973 (class 1255 OID 24013)
-- Name: sip_getpartypurchaseorder(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_getpartypurchaseorder(in_party_code character varying) RETURNS TABLE(p_po_no character, p_po_dt date, p_party_cd character, p_total_value numeric, p_unit_cd character)
    LANGUAGE plpgsql
    AS $$
  
 DECLARE 
BEGIN
 
 FOR P_PO_NO, P_PO_DT, P_PARTY_CD, P_TOTAL_VALUE, P_UNIT_CD
	IN SELECT  SSPH.PO_NO,
			SSPH.PO_DT,
			SSPH.PARTY_CD,
			SSPH.TOTAL_VALUE,
			SD.UNIT_CD
	FROM SIT_STD_PO_HDR SSPH
	INNER JOIN SIM_PUR_SECTION SPS ON
		SPS.PUR_SEC=SSPH.PUR_SEC
	INNER JOIN SIM_DEPOT SD ON
		SUBSTR(SD.DEPOT_CD,1,2) = SUBSTR(SPS.LOC_CD,1,2)
	WHERE 
		SSPH.PO_FLAG IN ('F','M')
		AND SSPH.PARTY_CD = IN_PARTY_CODE LOOP
		RETURN NEXT;    
  END LOOP;
END    ;

$$;


ALTER FUNCTION public.sip_getpartypurchaseorder(in_party_code character varying) OWNER TO postgres;

--
-- TOC entry 6958 (class 1255 OID 24014)
-- Name: sip_getpartytrade(character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_getpartytrade(in_party_cd character) RETURNS TABLE(p_party_cd character, p_trade_grp character, p_short_desc character, p_long_desc character)
    LANGUAGE plpgsql
    AS $$
  
begin

FOR P_PARTY_CD, P_TRADE_GRP, P_SHORT_DESC, P_LONG_DESC
	IN SELECT  
		SPT.PARTY_CD ,
		SPT.TRADE_GRP,
		STG.SHORT_DESC10,
		STG.LONG_DESC80 
	FROM SIM_PARTY_TRADE SPT
	LEFT JOIN SIM_TRADE_GRP STG 
		ON SPT.TRADE_GRP = STG.TRADE_GRP
	WHERE SPT.PARTY_CD = IN_PARTY_CD LOOP
	RETURN NEXT;    
END LOOP;
END;

$$;


ALTER FUNCTION public.sip_getpartytrade(in_party_cd character) OWNER TO postgres;

--
-- TOC entry 6975 (class 1255 OID 24015)
-- Name: sip_getpostates(character, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_getpostates(in_po_no character, in_unit_id integer) RETURNS TABLE(p_state_id integer)
    LANGUAGE plpgsql
    AS $$
 
BEGIN

	FOR P_STATE_ID
		IN SELECT 
			DISTINCT SD.STATE_ID 
			FROM 
			SIT_STD_TENDER_DEC SSTD 
			INNER JOIN SIT_STD_PO_HDR SSPH   
				ON SSTD.TENDER_NO=SUBSTR(SSPH.PO_NO,1,9) 
			INNER JOIN SIM_DEPOT SD 
				ON SSTD.DELIVERY_PLACE = SD.DEPOT_CD AND SD.UNIT_ID = IN_UNIT_ID 
		WHERE 
			SSPH.PO_NO = IN_PO_NO
			AND SSPH.PO_FLAG IN ('F','M') LOOP
		RETURN NEXT;    
	END LOOP;
END;

$$;


ALTER FUNCTION public.sip_getpostates(in_po_no character, in_unit_id integer) OWNER TO postgres;

--
-- TOC entry 6967 (class 1255 OID 24016)
-- Name: sip_getpototaltaxablevalue(character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_getpototaltaxablevalue(in_po_no character) RETURNS TABLE(p_total_taxable_value numeric)
    LANGUAGE plpgsql
    AS $$
 
BEGIN
 
FOR P_TOTAL_TAXABLE_VALUE
	IN SELECT SUM((SSTD.TOTAL_LAND_COST - SSTD.SALES_TAX)*SSTD.QUANTITY) AS TOTAL_TAXABLE_VALUE
	  	   FROM SIT_STD_TENDER_DEC SSTD ,SIT_STD_PO_HDR SSPH
	  WHERE 
		SSPH.PO_NO =IN_PO_NO AND SUBSTRING(SSPH.PO_NO FROM 1 FOR 9)=SSTD.TENDER_NO
		AND SSPH.PO_FLAG IN ('F','M') AND SSTD.PO_FLAG IN ('F','M') AND SSTD.PARTY_CD = SSPH.PARTY_CD
		AND CAST(SSPH.PO_AMEND_NO as int) = SSTD.AMEND_NO
		GROUP BY PO_NO LOOP
	   RETURN NEXT;    
END LOOP;
END  ;

$$;


ALTER FUNCTION public.sip_getpototaltaxablevalue(in_po_no character) OWNER TO postgres;

--
-- TOC entry 6976 (class 1255 OID 24017)
-- Name: sip_getpurchaseorder(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_getpurchaseorder(uni_cd character varying) RETURNS TABLE(p_po_no text, p_po_dt date, p_party_cd text, p_total_value numeric, p_depot_cd text)
    LANGUAGE plpgsql
    AS $$
 
BEGIN

	 SELECT DISTINCT SUBSTR(DEPOT_CD,1,2) 
	 INTO P_DEPOT_CD 
	 FROM SIM_DEPOT SD 
	 WHERE SD.UNIT_CD = uni_cd;

 FOR P_PO_NO, P_PO_DT, P_PARTY_CD, P_TOTAL_VALUE
	IN SELECT  SSPH.PO_NO,
			SSPH.PO_DT,
			SSPH.PARTY_CD,
			SSPH.TOTAL_VALUE
	 FROM SIT_STD_PO_HDR SSPH
	 INNER JOIN SIM_PUR_SECTION SPS ON
		SPS.PUR_SEC=SSPH.PUR_SEC AND SUBSTR(SPS.LOC_CD,1,2) = P_DEPOT_CD
	 WHERE 
		SSPH.PO_FLAG IN ('F','M') LOOP 
	 RETURN NEXT;   
  END LOOP;
END ;

$$;


ALTER FUNCTION public.sip_getpurchaseorder(uni_cd character varying) OWNER TO postgres;

