--
-- TOC entry 6811 (class 1255 OID 376792)
-- Name: sip_po_dtls(date, date); Type: FUNCTION; Schema: public; Owner: itstaff
--

CREATE FUNCTION public.sip_po_dtls(in_loa_start date, in_loa_end date) RETURNS TABLE(com_liability_no text, loa_date text, loa_po_no text, loa_amount numeric, department_name text, name_of_work text, loatype text, party text, efileno text, unit text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY

  SELECT DISTINCT B.PO_NO::text,
  to_char(A.PO_DT,'DD/MM/YYYY')::text,
  B.PO_NO::text,
  SUM(A.TOTAL_VALUE)::numeric,
 'STORES'::text,
 'PROCUREMENT'::text, 
 '-'::text,
 A.party_cd||'-'||c.party_name::text,
 '-'::text,
 '-'::text
 
  FROM 
  SIT_STD_PO_HDR A, SIT_PO_STD_DTL B, sim_party c WHERE A.PO_NO=B.PO_NO 
  AND A.PO_FLAG='F'
  and A.party_cd=c.party_cd
  AND A.PO_DT
  BETWEEN in_loa_start AND in_loa_end
  GROUP BY 1,2,3,5,6,7,8,9,10;
  
   
END;
$$;


ALTER FUNCTION public.sip_po_dtls(in_loa_start date, in_loa_end date) OWNER TO itstaff;

--
-- TOC entry 6801 (class 1255 OID 270298)
-- Name: sip_po_summary_dtls(date, date); Type: FUNCTION; Schema: public; Owner: itstaff
--

CREATE FUNCTION public.sip_po_summary_dtls(in_loa_start date, in_loa_end date) RETURNS TABLE(department_name text, total_loa numeric, total_loa_amount numeric, loa_po_type text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
  
  SELECT 
  'STORES'::text,
  COUNT(DISTINCT A.PO_NO)::numeric as total_loa,
  SUM(A.TOTAL_VALUE)::numeric as total_loa_amount,
  'PO'::text
  FROM SITK_IND_CD  C , 
  SIT_STD_PO_HDR A, SIT_PO_STD_DTL B WHERE A.PO_NO=B.PO_NO AND A.PO_FLAG='F'
  AND C.DEPT_IND_CD=LEFT(B.CONSIGNEE_CD,2)  
  AND A.PO_DT
  BETWEEN in_loa_start AND in_loa_end GROUP BY 1;
   
END;
$$;


ALTER FUNCTION public.sip_po_summary_dtls(in_loa_start date, in_loa_end date) OWNER TO itstaff;

--
-- TOC entry 6979 (class 1255 OID 24020)
-- Name: sip_saveorupdateparty(character, character, character, character, character, character, character, character, integer, character, character, character, character, character, character, character, character varying, character varying, character, numeric, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_saveorupdateparty(in_case character, in_party_cd character, in_party_initial character, in_party_name character, in_party_addr1 character, in_party_addr2 character, in_contact_person character, in_city character, in_pin integer, in_tel_no1 character, in_tel_no2 character, in_telex character, in_fax character, in_email character, in_vendor_type character, in_vendor_status character, in_cst_no character varying, in_sst_no character varying, in_isi_mark character, in_auc_comm numeric, in_vendor_category character) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

BEGIN
--CASE 1 INSERT
IF IN_CASE ='I' THEN

	
	INSERT INTO SIM_PARTY 
		(	PARTY_CD,
			PARTY_INITIAL,
			PARTY_NAME,
			PARTY_ADDR1,
			PARTY_ADDR2,
			CONTACT_PERSON,
			CITY,
			PIN,
			TEL_NO1,
			TEL_NO2,
			TELEX,
			FAX,
			EMAIL,
			VENDOR_TYPE,
			VENDOR_STATUS,
			CST_NO,
			SST_NO,
			ISI_MARK,
			AUC_COMM,
			VENDOR_CATEGORY
			) 
	VALUES( IN_PARTY_CD,
			IN_PARTY_INITIAL,
			IN_PARTY_NAME,
			IN_PARTY_ADDR1,
			IN_PARTY_ADDR2,
			IN_CONTACT_PERSON, 
			IN_CITY,
			IN_PIN,
			IN_TEL_NO1,
			IN_TEL_NO2,
			IN_TELEX,
			IN_FAX,
			IN_EMAIL,
			IN_VENDOR_TYPE,
			IN_VENDOR_STATUS,
			IN_CST_NO,
			IN_SST_NO,
			IN_ISI_MARK,
			IN_AUC_COMM,
			IN_VENDOR_CATEGORY);

--CASE 2 UPDATE
ELSIF IN_CASE ='U' THEN

	UPDATE SIM_PARTY SET
		PARTY_NAME=		IN_PARTY_NAME,
		PARTY_INITIAL = IN_PARTY_INITIAL,
		PARTY_ADDR1=	IN_PARTY_ADDR1,
		PARTY_ADDR2=	IN_PARTY_ADDR2,
		CONTACT_PERSON= IN_CONTACT_PERSON,
		CITY=			IN_CITY,
		PIN=			IN_PIN,
		TEL_NO1=		IN_TEL_NO1, 
		TEL_NO2=		IN_TEL_NO2,
		TELEX=			IN_TELEX,
		FAX=			IN_FAX,
		EMAIL=			IN_EMAIL, 
		VENDOR_TYPE=	IN_VENDOR_TYPE,
		VENDOR_STATUS=	IN_VENDOR_STATUS,
		CST_NO=			IN_CST_NO,
		SST_NO=			IN_SST_NO,
		ISI_MARK=		IN_ISI_MARK,
		AUC_COMM=		IN_AUC_COMM,
		VENDOR_CATEGORY=IN_VENDOR_CATEGORY
	WHERE PARTY_CD=		IN_PARTY_CD ;
	
END IF;
return(true);

Exception when others  then
return(false);

END;

$$;


ALTER FUNCTION public.sip_saveorupdateparty(in_case character, in_party_cd character, in_party_initial character, in_party_name character, in_party_addr1 character, in_party_addr2 character, in_contact_person character, in_city character, in_pin integer, in_tel_no1 character, in_tel_no2 character, in_telex character, in_fax character, in_email character, in_vendor_type character, in_vendor_status character, in_cst_no character varying, in_sst_no character varying, in_isi_mark character, in_auc_comm numeric, in_vendor_category character) OWNER TO postgres;

--
-- TOC entry 6983 (class 1255 OID 24021)
-- Name: sip_savepartytradegroup(character, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_savepartytradegroup(in_trade_grp character, in_party_cd character) RETURNS TABLE(resultval boolean)
    LANGUAGE plpgsql
    AS $$

begin

RETURN QUERY
    WITH ins AS (
        INSERT INTO SIM_PARTY_TRADE (TRADE_GRP, PARTY_CD) 
        VALUES (in_trade_grp, in_party_cd)
        RETURNING true
    )
    SELECT true as resultval FROM ins
    UNION ALL
    SELECT false as resultval
    WHERE NOT EXISTS (SELECT 1 FROM ins);

END;
$$;


ALTER FUNCTION public.sip_savepartytradegroup(in_trade_grp character, in_party_cd character) OWNER TO postgres;

--
-- TOC entry 6980 (class 1255 OID 24022)
-- Name: sip_validatepurchaseorder(character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sip_validatepurchaseorder(in_po_number character) RETURNS TABLE(v_valid integer)
    LANGUAGE plpgsql
    AS $$

begin

FOR V_VALID
		IN SELECT
			(CASE WHEN PO_COUNT >=1 THEN 1 ELSE 0 END) AS VALID
			FROM (
			SELECT 
				COUNT(*) AS PO_COUNT
			FROM SIT_STD_PO_HDR 
			WHERE PO_NO = IN_PO_NUMBER
		) s LOOP
	RETURN NEXT;
END LOOP;
END;

$$;


ALTER FUNCTION public.sip_validatepurchaseorder(in_po_number character) OWNER TO postgres;

