--
-- TOC entry 6989 (class 1255 OID 24031)
-- Name: ta_sp_alloc_hd(character, character, character, character, character, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ta_sp_alloc_hd(p_flag character, p_alloc_cd character, p_alloc_desc character, p_cr_acct_cd character, p_dr_acct_cd character, p_cr_dr_flag character) RETURNS smallint
    LANGUAGE plpgsql
    AS $$

        DECLARE  p_ret_val       SMALLINT;
BEGIN

        IF p_flag = 'A' then

            
                INSERT INTO tam_alloc_hd
                (
                        alloc_cd,
                        alloc_desc,
                        cr_acct_cd,
                        dr_acct_cd,
                        cr_dr_flag
                )
                VALUES
                (
                        p_alloc_cd,
                        p_alloc_desc,
                        p_cr_acct_cd,
                        p_dr_acct_cd,
                        p_cr_dr_flag
                );

        END IF;

        IF p_flag = 'M' THEN

                UPDATE  tam_alloc_hd
                SET     alloc_desc = p_alloc_desc,
                        cr_acct_cd = p_cr_acct_cd,
                        dr_acct_cd = p_dr_acct_cd,
                        cr_dr_flag = p_cr_dr_flag
                WHERE   alloc_cd = p_alloc_cd;

                DELETE FROM tam_alloc_dt WHERE alloc_cd = p_alloc_cd;

        END IF;

        IF p_flag = 'D' then

                DELETE FROM tam_alloc_hd
                WHERE   alloc_cd = p_alloc_cd;

                DELETE FROM tam_alloc_dt WHERE alloc_cd = p_alloc_cd;

        END IF;

        RETURN 1;
      --  p_ret_val = DBINFO('SQLCA.SQLERRD2');
	  
	  	exception when others then 
    	raise notice 'ta_sp_alloc_hd %',  SQLSTATE;
		
        RETURN  0;

END;
$$;


ALTER FUNCTION public.ta_sp_alloc_hd(p_flag character, p_alloc_cd character, p_alloc_desc character, p_cr_acct_cd character, p_dr_acct_cd character, p_cr_dr_flag character) OWNER TO postgres;

