-- TOC entry 6994 (class 1255 OID 24034)
-- Name: ta_sp_charges(character, character, character, character, character, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ta_sp_charges(p_flag character, p_charge character, p_cc_cf character, p_desc character, p_app character, p_freight character) RETURNS smallint
    LANGUAGE plpgsql
    AS $$

        DECLARE  p_retval        SMALLINT;
BEGIN

        IF p_flag = 'A' THEN
              
                INSERT INTO tam_charges
                (
                        charge_type,
                        cc_cf_flag,
                        charge_desc,
                        app_charge,
                        freight_yn
                )
                VALUES
                (
                        p_charge,
                        p_cc_cf,
                        p_desc,
                        p_app,
                        p_freight
                );
        END IF;

        IF p_flag = 'M' THEN
                UPDATE  tam_charges
                SET     charge_desc = p_desc,
                        app_charge = p_app,
                        freight_yn = p_freight
                WHERE   charge_type = p_charge
                AND     cc_cf_flag = p_cc_cf;
        END IF;

        RETURN 1;
     	 --  p_ret_val = DBINFO('SQLCA.SQLERRD2');
	  
	 	exception when others then 
    	raise notice  'ta_sp_charges %',  SQLSTATE;
		
        RETURN  0;


END;
$$;


