CREATE FUNCTION public.ta_sp_err_dt(p_flag character, p_error_no character, p_item_no character, p_iss_date date, p_class_comm_cd character, p_wt_pass_chrgd numeric, p_act_wt_pass numeric, p_amt_chrgd numeric, p_act_amt numeric, p_diff_amt numeric, p_admit_amt numeric, p_admit character, p_rsn_raised character, p_rsn_admit character, p_rsn_reject character) RETURNS smallint
    LANGUAGE plpgsql
    AS $$

