--
-- TOC entry 6999 (class 1255 OID 24038)
-- Name: ta_sp_err_hd(character, character, character, date, integer, character, date, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ta_sp_err_hd(p_flag character, p_error_no character, p_stn_against character, p_date_raised date, p_raised_by integer, p_ack_yon character, p_ack_dt date, p_cc_cf_flag character) RETURNS smallint
    LANGUAGE plpgsql
    AS $$

        DECLARE  p_ret_val       SMALLINT;
BEGIN

        IF p_flag = 'A' then

                 INSERT INTO tat_error_hdr
                (
                        error_no,
                        stn_against,
                        date_raised,
                        raised_by,
                        ack_yon,
                        ack_dt,
                        cc_cf_flag 
                )
                VALUES
                (
                 p_error_no   ,
                 p_stn_against, 
                 p_date_raised,
                 p_raised_by ,
                 p_ack_yon  ,
                 p_ack_dt,   
                 p_cc_cf_flag 
                );

        END IF;

        IF p_flag = 'M' THEN

                UPDATE  tat_error_hdr
                SET     date_raised = p_date_raised,
                        raised_by   = p_raised_by,
                        ack_yon     = p_ack_yon,
                        ack_dt      = p_ack_dt,
                        cc_cf_flag  = p_cc_cf_flag
                WHERE   error_no    = p_error_no 
                AND     stn_against = p_stn_against ;

--  *** DELETE FROM tat_error_dtl
-- WHERE  error_no = p_error_no; 

        END IF;

        IF p_flag = 'D' then

                DELETE FROM tat_error_dtl 
                WHERE  error_no = p_error_no;  

                DELETE FROM tat_error_hdr
                WHERE   error_no    = p_error_no 
                AND     stn_against = p_stn_against ;

        END IF;

        RETURN 1;
		--  p_ret_val = DBINFO('SQLCA.SQLERRD2');
	    -- RETURN p_ret_val;
	  	exception when others then 
    	raise notice 'ta_sp_err_hd %',  SQLSTATE;

END;
$$;


ALTER FUNCTION public.ta_sp_err_hd(p_flag character, p_error_no character, p_stn_against character, p_date_raised date, p_raised_by integer, p_ack_yon character, p_ack_dt date, p_cc_cf_flag character) OWNER TO postgres;

--
-- TOC entry 6838 (class 1255 OID 24039)
-- Name: ta_sp_err_rep(character, character, numeric, numeric, numeric, character, integer, date); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.ta_sp_err_rep(IN p_error_no character, IN p_item_no character, IN p_diff_amt numeric, IN p_debit_amt numeric, IN p_admit_amt numeric, IN p_admit character, IN p_emp_no integer, IN p_clearance_dt date)
    LANGUAGE plpgsql
    AS $$
Declare 

		sysdate  timestamp(0);
        err_cnt SMALLINT;dbhdr_cnt SMALLINT;
        p_stn_against tat_error_hdr.stn_against%TYPE;
        p_raised_by tat_error_hdr.raised_by%TYPE;
        p_date_raised tat_error_hdr.date_raised%TYPE;
        p_stn_no otm_stn_master.stn_seq_no%TYPE;
        stnct smallint;
        p_cleared_amt tat_error_rep.cleared_amt%TYPE;
        erno tat_error_rep.error_no%TYPE;
        dbno tat_error_rep.error_no%TYPE;
        p_flag tat_error_hdr.cc_cf_flag%TYPE;

		
Begin
 
 err_cnt := 0;
        p_cleared_amt := 0;

     
        select count(*) into err_cnt
        from tat_error_rep where
        tat_error_rep.error_no = p_error_no and
        tat_error_rep.item_no = p_item_no;

        select stn_against,raised_by,date_raised,cc_cf_flag
        into p_stn_against,p_raised_by,p_date_raised,p_flag
        from tat_error_hdr where
        error_no = p_error_no;

       
        select sum(amount) into p_cleared_amt
        from tat_debit_dtl where
        error_no = p_error_no and
        debit_no = p_item_no and
        confirm = 'Y';

        IF p_cleared_amt IS NULL THEN
                 p_cleared_amt := 0;
        END IF;

--      select count(*) into stnct from otm_stn_master 
--      where stn_cde= p_stn_against; 
--and
--      rly_no = 0;

--      IF stnct = 1 THEN
                select distinct(stn_seq_no) into p_stn_no from otm_stn_master 
                where stn_cde = p_stn_against;
-- and
--              rly_no = 0;
--      else
--              select distinct stn_no into p_stn_no from ccm_tstnmst
--              select min(stn_no) into p_stn_no from ccm_tstnmst
--              where stn_cd = p_stn_against and
--              ((rly_no = 0 and
--              cc_cf_flag = "C") or
--              (rly_no = 0 and
--              cc_cf_flag = "B"));
--      END IF

        IF (err_cnt = 0  or err_cnt IS NULL) THEN
                
                INSERT INTO tat_error_rep
                (
                   error_no,
                   item_no,
                   action_dt,
                   stn_against,
                   raised_by,
                   date_raised,
                   diff_amt,
                   debit_amt,
                   admit_amt,
                   admit,
                   emp_no,
                   clearance_dt,
                   timestamp,
                   stn_no,
                   cleared_amt,
                   cc_cf_flag
                )
                VALUES
                (
                 p_error_no,
                 p_item_no,
                 CURRENT_DATE ,
                 p_stn_against,
                 p_raised_by,
                 p_date_raised,
                 p_diff_amt,
                 p_debit_amt,
                 p_admit_amt,
                 p_admit,
                 p_emp_no,
                 p_clearance_dt,
                 current_timestamp,
                p_stn_no,
               p_cleared_amt,
                p_flag
                );
        ELSE
                UPDATE  tat_error_rep
                SET     action_dt    = CURRENT_DATE ,
                        stn_against  = p_stn_against,
                        raised_by    = p_raised_by,
                        date_raised  = p_date_raised,
                        diff_amt     = p_diff_amt,
                        debit_amt    = p_debit_amt,
                        admit_amt    = p_admit_amt,
                        admit        = p_admit,
                        emp_no       = p_emp_no,
                        clearance_dt = p_clearance_dt,
                        timestamp    = current_timestamp,
                        stn_no = p_stn_no,
                        cleared_amt = p_cleared_amt,
                        cc_cf_flag =  p_flag
                WHERE   error_no     = p_error_no
                AND     item_no      = p_item_no
                AND     admit       != p_admit;
        END IF;

 
 
 
end;
$$;


ALTER PROCEDURE public.ta_sp_err_rep(IN p_error_no character, IN p_item_no character, IN p_diff_amt numeric, IN p_debit_amt numeric, IN p_admit_amt numeric, IN p_admit character, IN p_emp_no integer, IN p_clearance_dt date) OWNER TO postgres;

--
-- TOC entry 7000 (class 1255 OID 24040)
-- Name: ta_sp_err_scrdr(character, text, text, character, character, character, integer, numeric, integer, date, text, integer, text, character, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ta_sp_err_scrdr(p_flag character, p_station_no text, p_note_num text, p_cr_dr_flag character, p_cc_cf_flag character, p_cash_out_flag character, p_voucher_no integer, p_amount numeric, p_reason_cd integer, p_doc_date date, p_user_id text, p_raised_by integer, p_remarks text, p_auth_flag character, p_auth_date date) RETURNS smallint
    LANGUAGE plpgsql
    AS $$

        DECLARE  p_ret_val SMALLINT;
BEGIN

        IF p_flag = 'A' THEN

                INSERT INTO tat_scrdr
                (
                        station_no,
                        note_num,
                        cr_dr_flag,
                        cc_cf_flag,
                        cash_out_flag, 
                        voucher_no,
                        amount,
                        reason_cd,
                        doc_date,
                        user_id,
                        raised_by,
                        remarks,
                        auth_flag,
                        auth_date  
                )
                VALUES  
                (
                        p_station_no,
                        p_note_num,
                        p_cr_dr_flag,
                        p_cc_cf_flag,
                        p_cash_out_flag, 
                        p_voucher_no,
                        p_amount,
                        p_reason_cd,
                        p_doc_date,
                        p_user_id,
                        p_raised_by,
                        p_remarks,
                        p_auth_flag,
                        p_auth_date 
                );
            
        END IF;

      
		RETURN 1;
		--  p_ret_val = DBINFO('SQLCA.SQLERRD2');
	  	-- RETURN  p_ret_val;
	  	exception when others then 
    	raise notice 'ta_sp_err_scrdr %',  SQLSTATE;
END;
$$;


