--
-- TOC entry 6836 (class 1255 OID 24041)
-- Name: ta_sp_errcl_rep(character, character, numeric); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.ta_sp_errcl_rep(IN p_error_no character, IN p_debit_no character, IN p_amount numeric)
    LANGUAGE plpgsql
    AS $$
Declare 

--RETURNING SMALLINT;

        DECLARE  sysdate         timestamp(0);
         err_cnt SMALLINT;
		 dbhdr_cnt SMALLINT;
        p_stn_against  tat_error_hdr.stn_against%TYPE;
        p_raised_by  tat_error_hdr.raised_by%TYPE;
        p_date_raised  tat_error_hdr.date_raised%TYPE;
        p_stn_no  ccm_tstnmst.stn_no%TYPE;
        stnct smallint;
        p_cleared_amt  tat_error_rep.cleared_amt%TYPE;
        erno  tat_error_rep.error_no%TYPE;
        dbno  tat_error_rep.error_no%TYPE;
BEGIN

--SET DEBUG FILE TO "/tmp/ta_sp_err_rep.dbg";
--TRACE ON;

        err_cnt := 0; 
        p_cleared_amt := 0;

        select count(*) into err_cnt
        from tat_error_rep where
        tat_error_rep.error_no = p_error_no and
        tat_error_rep.item_no = p_debit_no;

        IF err_cnt > 0 THEN
        select sum(amount) into p_cleared_amt
        from tat_debit_dtl where
        error_no = p_error_no and
        debit_no = p_debit_no and
        confirm = 'Y';
        else 
                 p_cleared_amt := 0;
        END IF;

--IF p_admit in ("A","W","R","L") THEN
--      IF (err_cnt = 0  or err_cnt IS NULL) THEN
                UPDATE  tat_error_rep
                SET     cleared_amt = p_cleared_amt
                WHERE   error_no     = p_error_no
                AND     item_no      = p_debit_no;

--        END IF;
--END IF;
END;
$$;


ALTER PROCEDURE public.ta_sp_errcl_rep(IN p_error_no character, IN p_debit_no character, IN p_amount numeric) OWNER TO postgres;

