--
-- TOC entry 7003 (class 1255 OID 24046)
-- Name: ta_sp_scrdr(character, character, character, character, character, character, integer, numeric, integer, date, character, integer, character, character, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ta_sp_scrdr(p_flag character, p_station_no character, p_note_num character, p_cr_dr_flag character, p_cc_cf_flag character, p_cash_out_flag character, p_voucher_no integer, p_amount numeric, p_reason_cd integer, p_doc_date date, p_user_id character, p_raised_by integer, p_remarks character, p_auth_flag character, p_auth_date date) RETURNS smallint
    LANGUAGE plpgsql
    AS $$

        DECLARE  p_ret_val SMALLINT;
BEGIN

        IF p_flag = 'A' THEN
 
                INSERT INTO tat_scrdr
                (
                        station_no,
                        note_num,
                        cr_dr_flag,
                        cc_cf_flag,
                        cash_out_flag, 
                        voucher_no,
                        amount,
                        reason_cd,
                        doc_date,
                        user_id,
                        raised_by,
                        remarks,
                        auth_flag,
                        auth_date  
                )
                VALUES  
                (
                        p_station_no,
                        p_note_num,
                        p_cr_dr_flag,
                        p_cc_cf_flag,
                        p_cash_out_flag, 
                        p_voucher_no,
                        p_amount,
                        p_reason_cd,
                        p_doc_date,
                        p_user_id,
                        p_raised_by,
                        p_remarks,
                        p_auth_flag,
                        p_auth_date 
                );
            
        END IF;

        IF p_flag = 'M' THEN

                UPDATE  tat_scrdr
                SET     auth_flag = p_auth_flag ,
                        auth_date = p_auth_date  
                WHERE   note_num = p_note_num  
                AND     station_no = p_station_no 
                AND     cr_dr_flag = p_cr_dr_flag   
                AND     cc_cf_flag = p_cc_cf_flag  ;

        END IF;
    
        IF p_flag = 'D' THEN

                DELETE  FROM tat_scrdr 
                WHERE   note_num = p_note_num  
                AND     station_no = p_station_no 
                AND     cr_dr_flag = p_cr_dr_flag   
                AND     cc_cf_flag = p_cc_cf_flag  ;

        END IF;

        RETURN 1;
		--  p_ret_val = DBINFO('SQLCA.SQLERRD2');
	  	-- RETURN  p_ret_val;
	  	exception when others then 
    	raise notice 'ta_sp_scrdr %',  SQLSTATE;
		RETURN  0;
END;
$$;


ALTER FUNCTION public.ta_sp_scrdr(p_flag character, p_station_no character, p_note_num character, p_cr_dr_flag character, p_cc_cf_flag character, p_cash_out_flag character, p_voucher_no integer, p_amount numeric, p_reason_cd integer, p_doc_date date, p_user_id character, p_raised_by integer, p_remarks character, p_auth_flag character, p_auth_date date) OWNER TO postgres;

