--
-- TOC entry 7005 (class 1255 OID 24049)
-- Name: tap_getjv(smallint, smallint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tap_getjv(in_year smallint, in_month smallint) RETURNS TABLE(v_jv_no integer, v_jv_amt numeric, v_reg_id character, v_post_dt date, v_unit_id bigint, v_state_id bigint, v_profit_centre_id bigint, v_voucher_type_id bigint, v_jv_type character, v_led_cd character)
    LANGUAGE plpgsql
    AS $$

BEGIN
        FOR V_JV_NO, V_JV_AMT, V_REG_ID, V_POST_DT, V_UNIT_ID, V_STATE_ID, V_PROFIT_CENTRE_ID, V_VOUCHER_TYPE_ID, V_JV_TYPE, V_LED_CD 
                IN SELECT  FJ.JV_NO,
                                FJ.JV_AMT,
                                FJ.REG_ID,
                                FJ.POST_DT,
                                TTLM.UNIT_ID,
                                TTLM.STATE_ID,
                                TTLM.PROFIT_CENTRE_ID,
                                TTJCM.VOUCHER_TYPE_ID,
                                FJ.JV_TYPE AS JV_TYPE,
                                TTJ.LED_CD AS LED_CD
                                               FROM FAT_JVHD FJ 
                LEFT OUTER JOIN TAPK_TAFA_JVTYPE_CCCD_MAP TTJCM
                        ON FJ.JV_TYPE = TTJCM.JV_TYPE
                LEFT OUTER JOIN TATK_TB_JV TTJ
                        ON  FJ.JV_NO = TTJ.JV_NO
                LEFT OUTER JOIN TAPK_TAFA_LED_MAP TTLM
                        ON TTJ.LED_CD = TTLM.LED_CD
                WHERE  
                        TTJ.JV_YEAR = IN_YEAR 
                        AND TTJ.JV_MONTH =  IN_MONTH LOOP
                RETURN NEXT;
        END LOOP;
END ;
$$;


ALTER FUNCTION public.tap_getjv(in_year smallint, in_month smallint) OWNER TO postgres;

