--
-- TOC entry 7007 (class 1255 OID 24051)
-- Name: tap_getjvaccounthead(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tap_getjvaccounthead(in_year integer, in_month integer) RETURNS TABLE(v_jv_no integer, v_alloc_amt numeric, v_dr_cr_flag character, v_au6_no integer, v_cost_centre_id bigint, v_account_head_id bigint, v_account_head_code text, v_cost_centre_code integer, v_sh_desc text)
    LANGUAGE plpgsql
    AS $$
BEGIN

        FOR V_JV_NO, V_ALLOC_AMT, V_DR_CR_FLAG, V_AU6_NO, V_COST_CENTRE_ID, V_ACCOUNT_HEAD_ID, V_ACCOUNT_HEAD_CODE, V_COST_CENTRE_CODE, V_SH_DESC 
                IN SELECT  TBJ.JV_NO,
                                FA.ALLOC_AMT,
                                FA.DR_CR_FLAG,
                                FA.AU6_NO,
                                TTJCM.COST_CENTRE_ID,
                                TTAM.ACCOUNT_HEAD_ID,
                                FA.ACCT_HEAD AS ACCOUNT_HEAD_CODE,
                                FA.CC_CD AS COST_CENTRE_CODE,
                                FACT.SH_DESC
                                               FROM FAA_ALLOC FA
                                LEFT OUTER JOIN TAPK_TAFA_JVTYPE_CCCD_MAP TTJCM
                                        ON FA.CC_CD = TTJCM.CC_CD
                                LEFT OUTER JOIN TAPK_TAFA_ACCT_MAP TTAM
                                        ON FA.ACCT_HEAD = TTAM.ACCT_HEAD
                                LEFT OUTER JOIN TATK_TB_JV TBJ
                                        ON FA.TXN_NO = TBJ.TXN_NO
                                LEFT OUTER join fam_acct  FACT ON
                                        FA.ACCT_HEAD = FACT.ACCT_HEAD
                                WHERE 
                                                TBJ.JV_YEAR = IN_YEAR 
                                        AND TBJ.JV_MONTH =  IN_MONTH
                                        AND FA.MOD_CD = 'JV' 
                                        AND FA.LED_CD = '01' LOOP

                RETURN NEXT;
        END LOOP;
END   ;
$$;


ALTER FUNCTION public.tap_getjvaccounthead(in_year integer, in_month integer) OWNER TO postgres;

