--
-- TOC entry 2614 (class 1259 OID 26276)
-- Name: favh_bank_emp_pay; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.favh_bank_emp_pay AS
 SELECT x2.zone_cd,
    x2.pay_yearmonth,
    x2.sub_au6_jv_no AS mod_cd,
    x2.regis_date AS bill_dt,
    x2.fa_sub_au6_jv_no AS fa_mod_cd,
    x2.fa_date AS fa_bill_dt,
    x1.party_cd,
    x0.bank_code AS bank_cd,
    sum(x0.tot_allow) AS totalallow,
    sum(x0.net_allow) AS net_allow,
    x2.addl_charges AS bank_charges
   FROM public.pmhk_emp_netpay x0,
    public.pmmk_pay_bank_zone x1,
    public.fahk_sub_bill x2
  WHERE ((x0.bank_code = x1.bank_code) AND (x1.party_cd = x2.party_cd))
  GROUP BY x2.zone_cd, x2.pay_yearmonth, x2.sub_au6_jv_no, x1.party_cd, x0.bank_code, x2.regis_date, x2.fa_sub_au6_jv_no, x2.fa_date, x2.addl_charges
  ORDER BY x2.zone_cd;


ALTER VIEW public.favh_bank_emp_pay OWNER TO postgres;

