--
-- TOC entry 4070 (class 1259 OID 31144)
-- Name: pmvk_grp_allowance; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pmvk_grp_allowance AS
 SELECT x0.emp_no,
    x0.pay_yearmonth,
    x1.group_cd,
    sum(x0.ad_amount) AS ad_grp_amt
   FROM public.pmhk_pay_monthly x0,
    public.pmmk_adcd_groupmap x1
  WHERE ((x0.ad_cd = x1.ad_cd) AND (x1.ad_flg = 'A'::bpchar) AND (x1.group_cd <> 19))
  GROUP BY x0.emp_no, x0.pay_yearmonth, x1.group_cd
UNION
 SELECT x2.emp_no,
    x2.pay_yearmonth,
    x3.group_cd,
    sum(x2.ad_amount) AS ad_grp_amt
   FROM public.pmhk_pay_monthly x2,
    public.pmmk_adcd_group x3
  WHERE ((x2.ad_cd IN ( SELECT x6.ad_cd
           FROM public.pmm_ad x6
          WHERE ((x6.ad_flg = 'A'::bpchar) AND (x6.ad_cd <> ALL ( SELECT x7.ad_cd
                   FROM public.pmmk_adcd_groupmap x7
                  WHERE (x7.ad_flg = 'A'::bpchar)))))) AND (x3.group_cd = 19))
  GROUP BY x2.emp_no, x2.pay_yearmonth, x3.group_cd
UNION
 SELECT x4.emp_no,
    x4.pay_yearmonth,
    x5.group_cd,
    sum(x4.pension_amt) AS ad_grp_amt
   FROM public.pmhk_emp_data x4,
    public.pmmk_adcd_group x5
  WHERE ((x5.group_cd = 2) AND (x4.pension_amt > 0))
  GROUP BY x4.emp_no, x4.pay_yearmonth, x5.group_cd;


ALTER VIEW public.pmvk_grp_allowance OWNER TO postgres;

--
-- TOC entry 4071 (class 1259 OID 31149)
-- Name: pmvk_grp_deduction; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pmvk_grp_deduction AS
 SELECT x0.emp_no,
    x0.pay_yearmonth,
    x1.group_cd,
    sum(x0.ad_amount) AS ad_grp_amt
   FROM public.pmhk_pay_monthly x0,
    public.pmmk_adcd_groupmap x1
  WHERE ((x0.ad_cd = x1.ad_cd) AND (x1.ad_flg = 'D'::bpchar) AND (x1.group_cd <> 43))
  GROUP BY x0.emp_no, x0.pay_yearmonth, x1.group_cd
UNION
 SELECT x2.emp_no,
    x2.pay_yearmonth,
    x3.group_cd,
    sum(x2.ad_amount) AS ad_grp_amt
   FROM public.pmhk_pay_monthly x2,
    public.pmmk_adcd_group x3
  WHERE ((x2.ad_cd IN ( SELECT x4.ad_cd
           FROM public.pmm_ad x4
          WHERE ((x4.ad_flg = 'D'::bpchar) AND (x4.ad_cd <> ALL ( SELECT x5.ad_cd
                   FROM public.pmmk_adcd_groupmap x5
                  WHERE (x5.ad_flg = 'D'::bpchar)))))) AND (x3.group_cd = 43))
  GROUP BY x2.emp_no, x2.pay_yearmonth, x3.group_cd;


ALTER VIEW public.pmvk_grp_deduction OWNER TO postgres;

